package referenz;


public class Solution {
    public int numMagicSquaresInside(int[][] grid) {
        int m = grid.length;
        if (m < 3) return 0;
        int n = grid[0].length;
        if (n < 3) return 0;
        int count = 0;
        for (int i = 0; i <= m - 3; i++) {
            for (int j = 0; j <= n - 3; j++) {
                if (isMagic(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean isMagic(int[][] g, int r, int c) {
        // Check distinct numbers from 1 to 9
        boolean[] seen = new boolean[10];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                int val = g[r + i][c + j];
                if (val < 1 || val > 9 || seen[val]) {
                    return false;
                }
                seen[val] = true;
            }
        }

        // Center must be 5
        if (g[r + 1][c + 1] != 5) {
            return false;
        }

        // Expected sum for each row, column, and diagonal
        final int SUM = 15;

        // Check rows
        for (int i = 0; i < 3; i++) {
            int s = 0;
            for (int j = 0; j < 3; j++) {
                s += g[r + i][c + j];
            }
            if (s != SUM) {
                return false;
            }
        }

        // Check columns
        for (int j = 0; j < 3; j++) {
            int s = 0;
            for (int i = 0; i < 3; i++) {
                s += g[r + i][c + j];
            }
            if (s != SUM) {
                return false;
            }
        }

        // Check diagonals
        if (g[r][c] + g[r + 1][c + 1] + g[r + 2][c + 2] != SUM) {
            return false;
        }
        if (g[r][c + 2] + g[r + 1][c + 1] + g[r + 2][c] != SUM) {
            return false;
        }

        return true;
    }
}

