import java.util.*;

public class Solution {
    // Union-Find data structure
    private int[] parent;
    private int[] size;
    private int n;

    public int largestIsland(int[][] grid) {
        if (grid == null || grid.length == 0) return 0;
        n = grid.length;
        int totalCells = n * n;
        parent = new int[totalCells];
        size = new int[totalCells];
        Arrays.fill(parent, -1); // -1 indicates water

        // Initialize Union-Find for land cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int idx = i * n + j;
                    parent[idx] = idx;
                    size[idx] = 1;
                }
            }
        }

        // Directions: up, down, left, right
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};

        // Union adjacent land cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int idx = i * n + j;
                    for (int[] d : dirs) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n && grid[ni][nj] == 1) {
                            int nIdx = ni * n + nj;
                            union(idx, nIdx);
                        }
                    }
                }
            }
        }

        // If the whole grid is land, return its area
        int maxArea = 0;
        for (int i = 0; i < totalCells; i++) {
            if (parent[i] != -1) {
                maxArea = Math.max(maxArea, size[find(i)]);
            }
        }
        if (maxArea == totalCells) return maxArea; // already full

        // Try flipping each water cell to land
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> neighborRoots = new HashSet<>();
                    for (int[] d : dirs) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n && grid[ni][nj] == 1) {
                            int nIdx = ni * n + nj;
                            neighborRoots.add(find(nIdx));
                        }
                    }
                    int newArea = 1; // the flipped cell itself
                    for (int root : neighborRoots) {
                        newArea += size[root];
                    }
                    maxArea = Math.max(maxArea, newArea);
                }
            }
        }

        return maxArea;
    }

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // path compression
        }
        return parent[x];
    }

    private void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) return;
        // Union by size
        if (size[rootX] < size[rootY]) {
            parent[rootX] = rootY;
            size[rootY] += size[rootX];
        } else {
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }
}

