public class Solution {
    public int[][] flipAndInvertImage(int[][] image) {
        for (int[] row : image) {
            int left = 0;
            int right = row.length - 1;
            while (left <= right) {
                // Invert bits
                int leftVal = row[left] ^ 1;
                int rightVal = row[right] ^ 1;
                // Swap inverted values
                row[left] = rightVal;
                row[right] = leftVal;
                left++;
                right--;
            }
        }
        return image;
    }
}

