import java.util.Arrays;

public class Solution {
    public int[] shortestToChar(String s, char c) {
        int n = s.length();
        int[] answer = new int[n];
        int last = -1;
        // Left to right pass
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == c) {
                last = i;
                answer[i] = 0;
            } else {
                if (last != -1) {
                    answer[i] = i - last;
                } else {
                    answer[i] = Integer.MAX_VALUE;
                }
            }
        }
        // Right to left pass
        int next = -1;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == c) {
                next = i;
            } else {
                if (next != -1) {
                    int dist = next - i;
                    if (dist < answer[i]) {
                        answer[i] = dist;
                    }
                }
            }
        }
        return answer;
    }
}

