import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int robotSim(int[] commands, int[][] obstacles) {
        // Directions: 0=East, 1=North, 2=West, 3=South
        int[] dx = {1, 0, -1, 0};
        int[] dy = {0, 1, 0, -1};

        // Store obstacles in a set for O(1) lookup
        Set<Long> obstacleSet = new HashSet<>();
        for (int[] obs : obstacles) {
            long key = ((long) obs[0] << 32) | (obs[1] & 0xffffffffL);
            obstacleSet.add(key);
        }

        int x = 0, y = 0;
        int dir = 1; // start facing north
        long maxDistSq = 0;

        for (int cmd : commands) {
            if (cmd == -2) {          // turn left
                dir = (dir + 1) % 4;
            } else if (cmd == -1) {   // turn right
                dir = (dir + 3) % 4;
            } else {                  // move forward cmd steps
                for (int step = 0; step < cmd; step++) {
                    int nx = x + dx[dir];
                    int ny = y + dy[dir];
                    long key = ((long) nx << 32) | (ny & 0xffffffffL);
                    if (obstacleSet.contains(key)) {
                        break; // hit obstacle, stop moving for this command
                    }
                    x = nx;
                    y = ny;
                    long distSq = (long) x * x + (long) y * y;
                    if (distSq > maxDistSq) {
                        maxDistSq = distSq;
                    }
                }
            }
        }

        return (int) maxDistSq;
    }
}

