import java.util.Arrays;

public class Solution {
    private double[][] memo;

    public double soupServings(int n) {
        // For large n the probability approaches 1
        if (n > 1000) return 1.0;

        int N = (n + 24) / 25; // scale by 25 ml
        memo = new double[N + 1][N + 1];
        for (double[] row : memo) Arrays.fill(row, -1.0);

        return dfs(N, N);
    }

    private double dfs(int a, int b) {
        if (a <= 0 && b > 0) return 1.0;   // A empty first
        if (b <= 0 && a > 0) return 0.0;   // B empty first
        if (a <= 0 && b <= 0) return 0.5;  // both empty simultaneously

        if (memo[a][b] >= 0) return memo[a][b];

        double prob = 0.25 * (
                dfs(a - 4, b) +   // 100 A, 0 B
                dfs(a - 3, b - 1) + // 75 A, 25 B
                dfs(a - 2, b - 2) + // 50 A, 50 B
                dfs(a - 1, b - 3)   // 25 A, 75 B
        );

        memo[a][b] = prob;
        return prob;
    }
}

