import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> findAndReplacePattern(String[] words, String pattern) {
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (matches(word, pattern)) {
                result.add(word);
            }
        }
        return result;
    }

    private boolean matches(String word, String pattern) {
        if (word.length() != pattern.length()) {
            return false;
        }
        int[] mapPatternToWord = new int[26];
        int[] mapWordToPattern = new int[26];
        for (int i = 0; i < 26; i++) {
            mapPatternToWord[i] = -1;
            mapWordToPattern[i] = -1;
        }
        for (int i = 0; i < word.length(); i++) {
            int p = pattern.charAt(i) - 'a';
            int w = word.charAt(i) - 'a';
            if (mapPatternToWord[p] == -1 && mapWordToPattern[w] == -1) {
                mapPatternToWord[p] = w;
                mapWordToPattern[w] = p;
            } else if (mapPatternToWord[p] != w || mapWordToPattern[w] != p) {
                return false;
            }
        }
        return true;
    }
}

