public class Solution {
    public int longestMountain(int[] arr) {
        int n = arr.length;
        if (n < 3) return 0;

        int[] left = new int[n];
        int[] right = new int[n];

        // Compute lengths of increasing sequences ending at each index
        for (int i = 1; i < n; i++) {
            if (arr[i] > arr[i - 1]) {
                left[i] = left[i - 1] + 1;
            } else {
                left[i] = 0;
            }
        }

        // Compute lengths of decreasing sequences starting at each index
        for (int i = n - 2; i >= 0; i--) {
            if (arr[i] > arr[i + 1]) {
                right[i] = right[i + 1] + 1;
            } else {
                right[i] = 0;
            }
        }

        int maxLen = 0;
        // Find the maximum mountain length
        for (int i = 1; i < n - 1; i++) {
            if (left[i] > 0 && right[i] > 0) {
                int len = left[i] + right[i] + 1;
                if (len > maxLen) {
                    maxLen = len;
                }
            }
        }

        return maxLen;
    }
}

