import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        // Remove the surrounding parentheses
        String inner = s.substring(1, s.length() - 1);
        int n = inner.length();

        // Try every possible split position
        for (int i = 1; i < n; i++) {
            String leftPart = inner.substring(0, i);
            String rightPart = inner.substring(i);

            List<String> leftOptions = generateOptions(leftPart);
            List<String> rightOptions = generateOptions(rightPart);

            for (String left : leftOptions) {
                for (String right : rightOptions) {
                    result.add("(" + left + ", " + right + ")");
                }
            }
        }

        return result;
    }

    // Generate all valid representations for a numeric string part
    private List<String> generateOptions(String part) {
        List<String> options = new ArrayList<>();
        int len = part.length();

        // Single digit is always valid
        if (len == 1) {
            options.add(part);
            return options;
        }

        // If the part starts with '0'
        if (part.charAt(0) == '0') {
            // Only "0.xxx" form is possible, but fractional part must not end with '0'
            if (part.charAt(len - 1) != '0') {
                options.add("0." + part.substring(1));
            }
            // No other forms are valid
            return options;
        }

        // If the part ends with '0', decimal form would have trailing zero -> invalid
        if (part.charAt(len - 1) == '0') {
            options.add(part); // only integer form
            return options;
        }

        // General case: integer form + all possible decimal insertions
        options.add(part); // integer form
        for (int i = 1; i < len; i++) {
            String left = part.substring(0, i);
            String right = part.substring(i);
            options.add(left + "." + right);
        }

        return options;
    }
}

