import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int shortestSubarray(int[] nums, int k) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        Deque<Integer> deque = new ArrayDeque<>();
        int answer = n + 1; // larger than any possible subarray length

        for (int i = 0; i <= n; i++) {
            // Check if we can form a subarray ending at i with sum >= k
            while (!deque.isEmpty() && prefix[i] - prefix[deque.peekFirst()] >= k) {
                answer = Math.min(answer, i - deque.peekFirst());
                deque.pollFirst();
            }

            // Maintain deque in increasing order of prefix sums
            while (!deque.isEmpty() && prefix[i] <= prefix[deque.peekLast()]) {
                deque.pollLast();
            }

            deque.offerLast(i);
        }

        return answer == n + 1 ? -1 : answer;
    }
}

