import java.util.*;

public class Solution {
    public int[] hitBricks(int[][] grid, int[][] hits) {
        int m = grid.length;
        int n = grid[0].length;
        int total = m * n;
        int top = total; // virtual top node

        // Copy original grid to check if a brick existed at a hit position
        int[][] original = new int[m][n];
        for (int i = 0; i < m; i++) {
            System.arraycopy(grid[i], 0, original[i], 0, n);
        }

        // Remove bricks that will be hit
        for (int[] hit : hits) {
            int r = hit[0], c = hit[1];
            if (grid[r][c] == 1) {
                grid[r][c] = 0;
            }
        }

        DSU dsu = new DSU(total + 1);

        // Union all remaining bricks
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int id = i * n + j;
                    if (i == 0) {
                        dsu.union(id, top);
                    }
                    // Union with upper neighbor
                    if (i > 0 && grid[i - 1][j] == 1) {
                        dsu.union(id, (i - 1) * n + j);
                    }
                    // Union with left neighbor
                    if (j > 0 && grid[i][j - 1] == 1) {
                        dsu.union(id, i * n + (j - 1));
                    }
                }
            }
        }

        int[] result = new int[hits.length];
        // Process hits in reverse order
        for (int idx = hits.length - 1; idx >= 0; idx--) {
            int r = hits[idx][0];
            int c = hits[idx][1];
            if (original[r][c] == 0) {
                result[idx] = 0;
                continue; // nothing to add back
            }

            int before = dsu.size(dsu.find(top));

            // Add the brick back
            grid[r][c] = 1;
            int id = r * n + c;
            if (r == 0) {
                dsu.union(id, top);
            }

            // Union with all four neighbors if they are bricks
            if (r > 0 && grid[r - 1][c] == 1) {
                dsu.union(id, (r - 1) * n + c);
            }
            if (r < m - 1 && grid[r + 1][c] == 1) {
                dsu.union(id, (r + 1) * n + c);
            }
            if (c > 0 && grid[r][c - 1] == 1) {
                dsu.union(id, r * n + (c - 1));
            }
            if (c < n - 1 && grid[r][c + 1] == 1) {
                dsu.union(id, r * n + (c + 1));
            }

            int after = dsu.size(dsu.find(top));
            int fallen = after - before - 1; // subtract the brick we just added
            result[idx] = Math.max(0, fallen);
        }

        return result;
    }

    // Union-Find (Disjoint Set Union) implementation
    private static class DSU {
        private final int[] parent;
        private final int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) return;
            // union by size
            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        int size(int x) {
            return size[find(x)];
        }
    }
}

