import java.util.*;

public class Solution {
    public double new21Game(int n, int k, int w) {
        // If Alice never draws or already has enough points, she always wins
        if (k == 0 || n < k) {
            return 1.0;
        }

        double[] dp = new double[n + 1];
        dp[0] = 1.0;
        double windowSum = 1.0; // sum of dp[i-w] ... dp[i-1]
        double result = 0.0;

        for (int i = 1; i <= n; i++) {
            if (i < k) {
                dp[i] = windowSum / w;
            } else {
                // Probability of finishing with exactly i points
                result += windowSum / w;
                dp[i] = 0.0; // not needed, but keeps array size consistent
            }

            windowSum += dp[i];
            if (i - w >= 0) {
                windowSum -= dp[i - w];
            }
        }

        return result;
    }
}

