public class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] result = new int[total][2];
        int idx = 0;

        // Include the starting position if it is inside the grid
        if (rStart >= 0 && rStart < rows && cStart >= 0 && cStart < cols) {
            result[idx++] = new int[]{rStart, cStart};
        }

        // Directions: east, south, west, north
        int[][] dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        int dirIdx = 0;      // current direction index
        int stepSize = 1;    // number of steps to take in current direction
        int r = rStart;
        int c = cStart;

        while (idx < total) {
            // Perform two directions with the same stepSize
            for (int repeat = 0; repeat < 2 && idx < total; repeat++) {
                int dr = dirs[dirIdx % 4][0];
                int dc = dirs[dirIdx % 4][1];
                for (int step = 0; step < stepSize && idx < total; step++) {
                    r += dr;
                    c += dc;
                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        result[idx++] = new int[]{r, c};
                    }
                }
                dirIdx++;
            }
            stepSize++; // increase step size after completing two directions
        }

        return result;
    }
}

