import java.util.Comparator;
import java.util.stream.IntStream;

public class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        int n = indices.length;
        int[] order = IntStream.range(0, n)
                .boxed()
                .sorted(Comparator.comparingInt(i -> indices[i]))
                .mapToInt(Integer::intValue)
                .toArray();

        StringBuilder sb = new StringBuilder();
        int prev = 0;

        for (int pos : order) {
            int idx = indices[pos];
            String src = sources[pos];
            String tgt = targets[pos];

            sb.append(s, prev, idx);

            if (s.startsWith(src, idx)) {
                sb.append(tgt);
                prev = idx + src.length();
            } else {
                int endIdx = idx + src.length();
                if (endIdx > s.length()) {
                    endIdx = s.length();
                }
                sb.append(s, idx, endIdx);
                prev = endIdx;
            }
        }

        sb.append(s.substring(prev));
        return sb.toString();
    }
}

