import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Queue;

public class Solution {
    public boolean possibleBipartition(int n, int[][] dislikes) {
        // Build adjacency list
        ArrayList<Integer>[] graph = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            graph[i] = new ArrayList<>();
        }
        for (int[] pair : dislikes) {
            int a = pair[0];
            int b = pair[1];
            graph[a].add(b);
            graph[b].add(a);
        }

        // 0 = uncolored, 1 = group A, -1 = group B
        int[] color = new int[n + 1];

        // Check each component
        for (int i = 1; i <= n; i++) {
            if (color[i] != 0) continue; // already processed

            // BFS from node i
            Queue<Integer> queue = new ArrayDeque<>();
            queue.offer(i);
            color[i] = 1; // assign to group A

            while (!queue.isEmpty()) {
                int node = queue.poll();
                int currentColor = color[node];
                int nextColor = -currentColor;

                for (int neighbor : graph[node]) {
                    if (color[neighbor] == 0) {
                        color[neighbor] = nextColor;
                        queue.offer(neighbor);
                    } else if (color[neighbor] != nextColor) {
                        // Conflict detected
                        return false;
                    }
                }
            }
        }

        return true;
    }
}

