public class Solution {
    public int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        // Pair jobs by difficulty and profit
        int[][] jobs = new int[n][2];
        for (int i = 0; i < n; i++) {
            jobs[i][0] = difficulty[i];
            jobs[i][1] = profit[i];
        }
        // Sort jobs by difficulty ascending
        Arrays.sort(jobs, Comparator.comparingInt(a -> a[0]));

        // Sort workers by ability ascending
        Arrays.sort(worker);

        long totalProfit = 0;
        int jobIdx = 0;
        int maxProfitSoFar = 0;

        for (int ability : worker) {
            // Advance jobIdx while jobs are doable by this worker
            while (jobIdx < n && jobs[jobIdx][0] <= ability) {
                maxProfitSoFar = Math.max(maxProfitSoFar, jobs[jobIdx][1]);
                jobIdx++;
            }
            totalProfit += maxProfitSoFar;
        }

        return (int) totalProfit;
    }
}

