public class Solution {
    public int expressiveWords(String s, String[] words) {
        int count = 0;
        for (String w : words) {
            if (isStretchy(s, w)) {
                count++;
            }
        }
        return count;
    }

    private boolean isStretchy(String s, String w) {
        int i = 0, j = 0;
        int n = s.length(), m = w.length();

        while (i < n && j < m) {
            char cs = s.charAt(i);
            char cw = w.charAt(j);
            if (cs != cw) {
                return false;
            }

            int iEnd = i;
            while (iEnd < n && s.charAt(iEnd) == cs) iEnd++;
            int jEnd = j;
            while (jEnd < m && w.charAt(jEnd) == cw) jEnd++;

            int lenS = iEnd - i;
            int lenW = jEnd - j;

            if (lenW > lenS) {
                return false;
            }
            if (lenS < 3 && lenS != lenW) {
                return false;
            }

            i = iEnd;
            j = jEnd;
        }

        return i == n && j == m;
    }
}

