        if (a.charAt(start) == b.charAt(start)) {
            int res = dfs(a, b, start + 1, memo);
            memo.put(key, res);
            return res;
        }

        int minSwaps = Integer.MAX_VALUE;
        char target = b.charAt(start);

        for (int i = start + 1; i < a.length(); i++) {
            if (a.charAt(i) == target && a.charAt(i) != b.charAt(i)) {
                char[] arr = a.toCharArray();
                char temp = arr[start];
                arr[start] = arr[i];
                arr[i] = temp;
                String swapped = new String(arr);
                int swaps = 1 + dfs(swapped, b, start + 1, memo);
                if (swaps < minSwaps) {
                    minSwaps = swaps;
                }
            }
        }

        memo.put(key, minSwaps);
        return minSwaps;
    }
}

