public class Solution {
    public int minSwap(int[] listA, int[] listB) {
        int n = listA.length;
        if (n <= 1) return 0;

        int[] keep = new int[n]; // no swap at i
        int[] swap = new int[n]; // swap at i

        keep[0] = 0;
        swap[0] = 1;

        for (int i = 1; i < n; i++) {
            keep[i] = Integer.MAX_VALUE;
            swap[i] = Integer.MAX_VALUE;

            // Condition 1: sequences stay increasing without swapping at i
            if (listA[i - 1] < listA[i] && listB[i - 1] < listB[i]) {
                keep[i] = Math.min(keep[i], keep[i - 1]);          // keep from keep
                swap[i] = Math.min(swap[i], swap[i - 1] + 1);      // keep from swap (swap at i)
            }

            // Condition 2: sequences stay increasing if we swap at i
            if (listA[i - 1] < listB[i] && listB[i - 1] < listA[i]) {
                keep[i] = Math.min(keep[i], swap[i - 1]);          // keep from swap (no swap at i)
                swap[i] = Math.min(swap[i], keep[i - 1] + 1);      // swap from keep (swap at i)
            }
        }

        return Math.min(keep[n - 1], swap[n - 1]);
    }
}

