import java.util.*;

public class Solution {
    public int primePalindrome(int n) {
        if (n <= 2) return 2;
        if (n <= 3) return 3;
        if (n <= 5) return 5;
        if (n <= 7) return 7;
        if (n <= 11) return 11;

        int len = String.valueOf(n).length();
        for (int l = len; l <= 8; l++) {
            if (l == 2) {
                if (n <= 11) return 11;
                continue;
            }
            if (l % 2 == 0) continue; // skip even length palindromes except 11

            int halfLen = (l + 1) / 2;
            int start = (int) Math.pow(10, halfLen - 1);
            int end = (int) Math.pow(10, halfLen) - 1;
            for (int i = start; i <= end; i++) {
                String s = Integer.toString(i);
                String rev = new StringBuilder(s.substring(0, s.length() - 1)).reverse().toString();
                String palStr = s + rev;
                int pal = Integer.parseInt(palStr);
                if (pal >= n && isPrime(pal)) {
                    return pal;
                }
            }
        }
        return -1; // should not reach here
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        if (num % 2 == 0) return num == 2;
        int limit = (int) Math.sqrt(num);
        for (int i = 3; i <= limit; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }
}

