import java.util.*;

public class Solution {
    public int numSimilarGroups(String[] strs) {
        int n = strs.length;
        DSU dsu = new DSU(n);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (areSimilar(strs[i], strs[j])) {
                    dsu.union(i, j);
                }
            }
        }
        return dsu.countSets();
    }

    private boolean areSimilar(String a, String b) {
        int diff = 0;
        int first = -1, second = -1;
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) {
                diff++;
                if (diff == 1) first = i;
                else if (diff == 2) second = i;
                else return false; // more than 2 differences
            }
        }
        if (diff == 0) return true;
        if (diff != 2) return false;
        return a.charAt(first) == b.charAt(second) && a.charAt(second) == b.charAt(first);
    }

    private static class DSU {
        private final int[] parent;
        private final int[] rank;
        private int sets;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            sets = n;
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        void union(int x, int y) {
            int px = find(x);
            int py = find(y);
            if (px == py) return;
            if (rank[px] < rank[py]) {
                parent[px] = py;
            } else if (rank[px] > rank[py]) {
                parent[py] = px;
            } else {
                parent[py] = px;
                rank[px]++;
            }
            sets--;
        }

        int countSets() {
            return sets;
        }
    }
}

