public class Solution {

    public TreeNode increasingBST(final TreeNode root) {
        if (root == null) {
            return null;
        }

        TreeNode dummy = new TreeNode(0);
        TreeNode curr = dummy;
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode node = root;

        while (node != null || !stack.isEmpty()) {
            while (node != null) {
                stack.push(node);
                node = node.left;
            }

            node = stack.pop();
            node.left = null;
            curr.right = node;
            curr = curr.right;
            node = node.right;
        }

        return dummy.right;
    }
}

