public class Solution {
    public int matrixScore(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        // Ensure the first column is all 1s by flipping rows where needed
        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 0) {
                for (int j = 0; j < n; j++) {
                    grid[i][j] ^= 1; // toggle bit
                }
            }
        }

        int score = 0;
        // Compute contribution of each column
        for (int j = 0; j < n; j++) {
            int ones = 0;
            for (int i = 0; i < m; i++) {
                if (grid[i][j] == 1) {
                    ones++;
                }
            }
            int zeros = m - ones;
            int bestOnes = Math.max(ones, zeros);
            int weight = 1 << (n - j - 1);
            score += bestOnes * weight;
        }

        return score;
    }
}

