import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    private static final int MOD = 1_000_000_007;

    private static class Event implements Comparable<Event> {
        int x;
        int y1, y2;
        int type; // +1 for add, -1 for remove

        Event(int x, int y1, int y2, int type) {
            this.x = x;
            this.y1 = y1;
            this.y2 = y2;
            this.type = type;
        }

        @Override
        public int compareTo(Event o) {
            return Integer.compare(this.x, o.x);
        }
    }

    public int rectangleArea(int[][] rectangles) {
        int n = rectangles.length;
        List<Event> events = new ArrayList<>(2 * n);
        List<Integer> yCoords = new ArrayList<>(2 * n);

        for (int[] rect : rectangles) {
            int x1 = rect[0], y1 = rect[1], x2 = rect[2], y2 = rect[3];
            events.add(new Event(x1, y1, y2, 1));
            events.add(new Event(x2, y1, y2, -1));
            yCoords.add(y1);
            yCoords.add(y2);
        }

        // Coordinate compression for y
        int[] yArr = yCoords.stream().mapToInt(Integer::intValue).toArray();
        Arrays.sort(yArr);
        int m = 0;
        for (int i = 0; i < yArr.length; i++) {
            if (i == 0 || yArr[i] != yArr[i - 1]) {
                yArr[m++] = yArr[i];
            }
        }
        yArr = Arrays.copyOf(yArr, m);

        // Build segment tree
        int size = m - 1; // number of intervals
        if (size <= 0) return 0;
        int[] count = new int[4 * size];
        long[] length = new long[4 * size];

        // Sort events by x
        events.sort(null);

        long area = 0;
        int prevX = events.get(0).x;

        for (Event e : events) {
            int curX = e.x;
            long coveredY = length[1];
            area = (area + coveredY * (curX - prevX)) % MOD;
            int l = Arrays.binarySearch(yArr, e.y1);
            int r = Arrays.binarySearch(yArr, e.y2) - 1; // inclusive
            update(1, 0, size - 1, l, r, e.type, yArr, count, length);
            prevX = curX;
        }

        return (int) area;
    }

    private void update(int node, int l, int r, int ql, int qr, int val,
                        int[] yArr, int[] count, long[] length) {
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            count[node] += val;
        } else {
            int mid = (l + r) >> 1;
            update(node << 1, l, mid, ql, qr, val, yArr, count, length);
            update(node << 1 | 1, mid + 1, r, ql, qr, val, yArr, count, length);
        }

        if (count[node] > 0) {
            length[node] = (long) yArr[r + 1] - yArr[l];
        } else {
            if (l == r) {
                length[node] = 0;
            } else {
                length[node] = length[node << 1] + length[node << 1 | 1];
            }
        }
    }
}

