public class Solution {
    public int[] sumOfDistancesInTree(int n, int[][] edges) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        long[] count = new long[n];   // number of nodes in subtree rooted at i (including i)
        long[] ans = new long[n];     // sum of distances from node i to all nodes in its subtree

        dfs1(0, -1, graph, count, ans);

        dfs2(0, -1, graph, count, ans, n);

        int[] result = new int[n];
        for (int i = 0; i < n; i++) result[i] = (int) ans[i];
        return result;
    }

    private void dfs1(int node, int parent, List<Integer>[] graph, long[] count, long[] ans) {
        count[node] = 1;
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            dfs1(nei, node, graph, count, ans);
            count[node] += count[nei];
            ans[node] += ans[nei] + count[nei];
        }
    }

    private void dfs2(int node, int parent, List<Integer>[] graph, long[] count, long[] ans, int n) {
        for (int nei : graph[node]) {
            if (nei == parent) continue;
            ans[nei] = ans[node] - count[nei] + (n - count[nei]);
            dfs2(nei, node, graph, count, ans, n);
        }
    }
}

