import java.util.Arrays;

public class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        int[] prev = new int[n];
        int[] next = new int[n];
        int[] last = new int[128];
        Arrays.fill(last, -1);

        // Compute previous occurrence for each position
        for (int i = 0; i < n; i++) {
            int idx = s.charAt(i);
            prev[i] = last[idx];
            last[idx] = i;
        }

        // Compute next occurrence for each position
        Arrays.fill(last, n); // n indicates no next occurrence
        for (int i = n - 1; i >= 0; i--) {
            int idx = s.charAt(i);
            next[i] = last[idx];
            last[idx] = i;
        }

        // Sum contributions
        long result = 0;
        for (int i = 0; i < n; i++) {
            result += (long) (i - prev[i]) * (next[i] - i);
        }

        return (int) result;
    }
}

