import java.util.Arrays;

public class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        int n = nums1.length;
        int[] result = new int[n];

        // Sort nums1 ascending
        int[] sortedNums1 = nums1.clone();
        Arrays.sort(sortedNums1);

        // Create pairs of (nums2 value, original index)
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums2[i];
            pairs[i][1] = i;
        }

        // Sort pairs by nums2 value in descending order
        Arrays.sort(pairs, (a, b) -> Integer.compare(b[0], a[0]));

        int low = 0;
        int high = n - 1;

        for (int[] pair : pairs) {
            int val = pair[0];
            int idx = pair[1];
            if (sortedNums1[high] > val) {
                result[idx] = sortedNums1[high];
                high--;
            } else {
                result[idx] = sortedNums1[low];
                low++;
            }
        }

        return result;
    }
}

