public class Solution {
    public String shiftingLetters(String s, int[][] shifts) {
        int n = s.length();
        int[] diff = new int[n + 1];

        for (int[] shift : shifts) {
            int start = shift[0];
            int end = shift[1];
            int direction = shift[2];
            int delta = direction == 1 ? 1 : -1;
            diff[start] += delta;
            if (end + 1 < diff.length) {
                diff[end + 1] -= delta;
            }
        }

        StringBuilder sb = new StringBuilder(n);
        int currentShift = 0;
        for (int i = 0; i < n; i++) {
            currentShift += diff[i];
            int shift = ((currentShift % 26) + 26) % 26;
            char c = s.charAt(i);
            char shifted = (char) ('a' + (c - 'a' + shift) % 26);
            sb.append(shifted);
        }

        return sb.toString();
    }
}

