public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numberOfWays(int startPos, int endPos, int k) {
        long d = (long) endPos - startPos;
        long sum = k + d;
        if ((sum & 1L) != 0) return 0; // parity mismatch
        long r = sum / 2;
        if (r < 0 || r > k) return 0;

        long[] fact = new long[k + 1];
        long[] invFact = new long[k + 1];
        fact[0] = 1;
        for (int i = 1; i <= k; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[k] = modInverse(fact[k]);
        for (int i = k - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        long res = fact[k];
        res = res * invFact[(int) r] % MOD;
        res = res * invFact[k - (int) r] % MOD;
        return (int) res;
    }

    private long modInverse(long a) {
        return modPow(a, MOD - 2);
    }

    private long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1L) == 1L) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

