public class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        // Use a set to keep only unique numbers
        Set<Integer> unique = new HashSet<>();
        for (int num : nums) {
            unique.add(num);
        }

        // Frequency of each popcount (0 to 31)
        int[] freq = new int[32];
        for (int num : unique) {
            int pc = Integer.bitCount(num);
            freq[pc]++;
        }

        long result = 0L;
        for (int pc1 = 0; pc1 < 32; pc1++) {
            if (freq[pc1] == 0) continue;
            for (int pc2 = 0; pc2 < 32; pc2++) {
                if (freq[pc2] == 0) continue;
                if (pc1 + pc2 >= k) {
                    result += (long) freq[pc1] * freq[pc2];
                }
            }
        }
        return result;
    }
}

