public class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length;
        int n = grid[0].length;
        long[] dpPrev = new long[n];
        for (int c = 0; c < n; c++) {
            dpPrev[c] = grid[0][c];
        }
        for (int r = 1; r < m; r++) {
            long[] dpCurr = new long[n];
            for (int c = 0; c < n; c++) {
                long best = Long.MAX_VALUE;
                for (int pc = 0; pc < n; pc++) {
                    int valPrev = grid[r - 1][pc];
                    long cost = dpPrev[pc] + moveCost[valPrev][c];
                    if (cost < best) {
                        best = cost;
                    }
                }
                dpCurr[c] = best + grid[r][c];
            }
            dpPrev = dpCurr;
        }
        long answer = Long.MAX_VALUE;
        for (long val : dpPrev) {
            if (val < answer) {
                answer = val;
            }
        }
        return (int) answer;
    }
}

