import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    private static int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public int distinctSequences(int n) {
        if (n == 1) return 6;

        // dp[prev1][prev2] : number of sequences ending with prev1 (last roll) and prev2 (second last roll)
        int[][] dp = new int[7][7];

        // initialize for position 2
        for (int v1 = 1; v1 <= 6; v1++) {
            for (int v2 = 1; v2 <= 6; v2++) {
                if (v1 == v2) continue;
                if (gcd(v1, v2) != 1) continue;
                dp[v2][v1] = 1;
            }
        }

        if (n == 2) {
            long sum = 0;
            for (int i = 1; i <= 6; i++) {
                for (int j = 1; j <= 6; j++) {
                    sum += dp[i][j];
                }
            }
            return (int) (sum % MOD);
        }

        for (int pos = 3; pos <= n; pos++) {
            int[][] next = new int[7][7];
            for (int prev1 = 1; prev1 <= 6; prev1++) {
                for (int prev2 = 1; prev2 <= 6; prev2++) {
                    int cur = dp[prev1][prev2];
                    if (cur == 0) continue;
                    for (int newVal = 1; newVal <= 6; newVal++) {
                        if (newVal == prev1) continue;          // no adjacent equal values
                        if (newVal == prev2) continue;          // no equal values within distance 2
                        if (gcd(newVal, prev1) != 1) continue; // adjacent gcd must be 1
                        int val = next[newVal][prev1] + cur;
                        if (val >= MOD) val -= MOD;
                        next[newVal][prev1] = val;
                    }
                }
            }
            dp = next;
        }

        long ans = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = 1; j <= 6; j++) {
                ans += dp[i][j];
            }
        }
        return (int) (ans % MOD);
    }
}

