import java.util.*;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) return 0;

        Map<Integer, List<Integer>> graph = new HashMap<>();
        buildGraph(root, null, graph);

        Queue<Integer> queue = new ArrayDeque<>();
        Set<Integer> visited = new HashSet<>();

        queue.offer(start);
        visited.add(start);
        int minutes = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            boolean infectedThisMinute = false;

            for (int i = 0; i < size; i++) {
                int node = queue.poll();
                List<Integer> neighbors = graph.getOrDefault(node, Collections.emptyList());
                for (int nb : neighbors) {
                    if (!visited.contains(nb)) {
                        visited.add(nb);
                        queue.offer(nb);
                        infectedThisMinute = true;
                    }
                }
            }

            if (infectedThisMinute) minutes++;
        }

        return minutes;
    }

    private void buildGraph(TreeNode node, TreeNode parent, Map<Integer, List<Integer>> graph) {
        if (node == null) return;

        graph.computeIfAbsent(node.val, k -> new ArrayList<>());
        if (parent != null) {
            graph.get(node.val).add(parent.val);
            graph.get(parent.val).add(node.val);
        }

        buildGraph(node.left, node, graph);
        buildGraph(node.right, node, graph);
    }
}

