import java.util.*;

public class Solution {
    // Union-Find (Disjoint Set Union) implementation
    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        void union(int a, int b) {
            int pa = find(a);
            int pb = find(b);
            if (pa == pb) return;
            // union by size
            if (size[pa] < size[pb]) {
                int tmp = pa;
                pa = pb;
                pb = tmp;
            }
            parent[pb] = pa;
            size[pa] += size[pb];
        }

        int getSize(int x) {
            return size[find(x)];
        }
    }

    public long countPairs(int n, int[][] edges) {
        DSU dsu = new DSU(n);
        for (int[] e : edges) {
            dsu.union(e[0], e[1]);
        }

        // Count component sizes
        Map<Integer, Integer> compSize = new HashMap<>();
        for (int i = 0; i < n; i++) {
            int root = dsu.find(i);
            compSize.put(root, compSize.getOrDefault(root, 0) + 1);
        }

        long result = 0;
        long processed = 0;
        for (int sz : compSize.values()) {
            result += sz * processed;
            processed += sz;
        }
        return result;
    }
}

