import java.util.Deque;
import java.util.ArrayDeque;

public class Solution {
    // use sliding window to track the largest in a way that the sliding window only grows.
    //   then the maximum size is the size of the sliding window at the end.
    // if condition is met, we just grow the sliding window.
    // if condition is not met, we shift the sliding window with the same size to the next position.
    // e.g., if [0,3] is valid, next time we will try [0,4].
    //       if [0,3] is invalid, next time we will try [1,4],
    //         by adjusting the window to [1,3] first in the current round.
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;
        int left = 0;
        long sumRunning = 0;
        int maxLen = 0;
        Deque<Integer> maxDeque = new ArrayDeque<>(); // indices with decreasing chargeTimes

        for (int right = 0; right < n; right++) {
            // add new robot to window
            sumRunning += runningCosts[right];
            while (!maxDeque.isEmpty() && chargeTimes[maxDeque.peekLast()] <= chargeTimes[right]) {
                maxDeque.pollLast();
            }
            maxDeque.offerLast(right);

            // shrink window if cost exceeds budget
            while (left <= right) {
                long maxCharge = chargeTimes[maxDeque.peekFirst()];
                long cost = maxCharge + (long)(right - left + 1) * sumRunning;
                if (cost <= budget) {
                    break;
                }
                // remove leftmost robot
                if (maxDeque.peekFirst() == left) {
                    maxDeque.pollFirst();
                }
                sumRunning -= runningCosts[left];
                left++;
            }

            // update answer
            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}

