import java.util.Arrays;

public class Solution {
    public int closestMeetingNode(int[] edges, int node1, int node2) {
        int n = edges.length;
        int[] dist1 = new int[n];
        int[] dist2 = new int[n];
        Arrays.fill(dist1, -1);
        Arrays.fill(dist2, -1);

        // Compute distances from node1
        int current = node1;
        int d = 0;
        while (current != -1 && dist1[current] == -1) {
            dist1[current] = d;
            current = edges[current];
            d++;
        }

        // Compute distances from node2
        current = node2;
        d = 0;
        while (current != -1 && dist2[current] == -1) {
            dist2[current] = d;
            current = edges[current];
            d++;
        }

        int bestIndex = -1;
        int bestMaxDist = Integer.MAX_VALUE;

        for (int i = 0; i < n; i++) {
            if (dist1[i] != -1 && dist2[i] != -1) {
                int maxDist = Math.max(dist1[i], dist2[i]);
                if (maxDist < bestMaxDist || (maxDist == bestMaxDist && i < bestIndex)) {
                    bestMaxDist = maxDist;
                    bestIndex = i;
                }
            }
        }

        return bestIndex;
    }
}

