public class Solution {
    public int shortestSequence(int[] rolls, int k) {
        int n = rolls.length;
        // next[i][c] = next index >= i where rolls[index] == c+1, or -1 if none
        int[][] next = new int[n + 1][k];
        for (int c = 0; c < k; c++) {
            next[n][c] = -1;
        }
        for (int i = n - 1; i >= 0; i--) {
            // copy from next[i+1]
            for (int c = 0; c < k; c++) {
                next[i][c] = next[i + 1][c];
            }
            int val = rolls[i] - 1; // 0-based
            if (val >= 0 && val < k) {
                next[i][val] = i;
            }
        }

        int[] dp = new int[n + 1];
        dp[n] = 1; // after the end, any single character is missing
        for (int i = n - 1; i >= 0; i--) {
            int best = Integer.MAX_VALUE / 2;
            for (int c = 0; c < k; c++) {
                int nxt = next[i][c];
                if (nxt == -1) {
                    best = 1;
                    break;
                } else {
                    int candidate = dp[nxt + 1] + 1;
                    if (candidate < best) {
                        best = candidate;
                    }
                }
            }
            dp[i] = best;
        }
        return dp[0];
    }
}

