public class Solution {
    public boolean matchReplacement(String s, String sub, char[][] mappings) {
        if (sub == null || s == null) return false;
        int n = s.length();
        int m = sub.length();
        if (m == 0 || n < m) return false;

        // Build mapping from old char to set of new chars
        Map<Character, Set<Character>> map = new HashMap<>();
        for (char[] pair : mappings) {
            if (pair == null || pair.length != 2) continue;
            char old = pair[0];
            char newC = pair[1];
            map.computeIfAbsent(old, k -> new HashSet<>()).add(newC);
        }

        // Try every possible starting position in s
        for (int i = 0; i <= n - m; i++) {
            boolean ok = true;
            for (int j = 0; j < m; j++) {
                char sc = s.charAt(i + j);
                char subc = sub.charAt(j);
                if (sc == subc) continue;
                Set<Character> allowed = map.get(subc);
                if (allowed == null || !allowed.contains(sc)) {
                    ok = false;
                    break;
                }
            }
            if (ok) return true;
        }
        return false;
    }
}

