public class Solution {
    public boolean canChange(String start, String target) {
        int n = start.length();
        int i = 0, j = 0;
        while (i < n || j < n) {
            // Skip blanks in start
            while (i < n && start.charAt(i) == '_') i++;
            // Skip blanks in target
            while (j < n && target.charAt(j) == '_') j++;

            // If both pointers reached the end, strings are compatible
            if (i == n && j == n) return true;
            // If only one reached the end, they differ
            if (i == n || j == n) return false;

            char cStart = start.charAt(i);
            char cTarget = target.charAt(j);

            // Characters must match
            if (cStart != cTarget) return false;

            // Check movement constraints
            if (cStart == 'L' && i < j) return false; // L can only move left
            if (cStart == 'R' && i > j) return false; // R can only move right

            i++;
            j++;
        }
        return true;
    }
}

