public class Solution {
    public long minimumReplacement(int[] nums) {
        int n = nums.length;
        long operations = 0;
        long last = nums[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            long current = nums[i];
            if (current <= last) {
                last = current;
                continue;
            }
            // Need to split current into k parts such that each part <= last
            long k = (current + last - 1) / last; // ceil division
            operations += k - 1;
            last = current / k; // largest part after splitting
        }
        return operations;
    }
}

