public class Solution {
    public int maximumsSplicedArray(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long sum1 = 0, sum2 = 0;
        for (int i = 0; i < n; i++) {
            sum1 += nums1[i];
            sum2 += nums2[i];
        }
        long total = sum1 + sum2;
        long diff0 = sum1 - sum2;

        // Compute delta array values on the fly
        long maxEnding = nums2[0] - nums1[0];
        long maxSoFar = maxEnding;
        long minEnding = maxEnding;
        long minSoFar = minEnding;

        for (int i = 1; i < n; i++) {
            long delta = (long) nums2[i] - (long) nums1[i];
            maxEnding = Math.max(delta, maxEnding + delta);
            maxSoFar = Math.max(maxSoFar, maxEnding);

            minEnding = Math.min(delta, minEnding + delta);
            minSoFar = Math.min(minSoFar, minEnding);
        }

        long diffMax = diff0 + 2L * maxSoFar;
        long diffMin = diff0 + 2L * minSoFar;

        long maxAbsDiff = Math.abs(diff0);
        maxAbsDiff = Math.max(maxAbsDiff, Math.abs(diffMax));
        maxAbsDiff = Math.max(maxAbsDiff, Math.abs(diffMin));

        long answer = (total + maxAbsDiff) / 2L;
        return (int) answer;
    }
}

