import java.util.Arrays;

public class Solution {
    private int best;

    public int distributeCookies(int[] c, int k) {
        // Sort cookies in descending order to enable effective pruning
        Arrays.sort(c);
        int n = c.length;
        int[] sorted = new int[n];
        for (int i = 0; i < n; i++) {
            sorted[i] = c[n - 1 - i];
        }

        best = Integer.MAX_VALUE;
        int[] sums = new int[k];
        dfs(0, sorted, sums, k);
        return best;
    }

    private void dfs(int idx, int[] cookies, int[] sums, int k) {
        if (idx == cookies.length) {
            int currentMax = 0;
            for (int s : sums) {
                if (s > currentMax) currentMax = s;
            }
            if (currentMax < best) best = currentMax;
            return;
        }

        int cookie = cookies[idx];
        for (int i = 0; i < k; i++) {
            // Prune if this child already has the same sum as a previous child
            // to avoid symmetric assignments
            if (i > 0 && sums[i] == sums[i - 1]) continue;

            // Prune if adding this cookie would not improve the best found so far
            if (sums[i] + cookie >= best) continue;

            sums[i] += cookie;
            dfs(idx + 1, cookies, sums, k);
            sums[i] -= cookie;

            // If this child had no cookies before adding, break to avoid duplicate work
            if (sums[i] == 0) break;
        }
    }
}

