public class Solution {
    public int garbageCollection(String[] garbage, int[] travel) {
        int n = garbage.length;
        int lastM = -1, lastP = -1, lastG = -1;

        // Find the last house that contains each type of garbage
        for (int i = 0; i < n; i++) {
            String s = garbage[i];
            for (int j = 0; j < s.length(); j++) {
                char c = s.charAt(j);
                if (c == 'M') lastM = i;
                else if (c == 'P') lastP = i;
                else if (c == 'G') lastG = i;
            }
        }

        // Total time spent picking up garbage
        int totalGarbage = 0;
        for (String s : garbage) {
            totalGarbage += s.length();
        }

        // Total travel time for each truck up to its last required house
        int travelM = 0, travelP = 0, travelG = 0;
        for (int i = 0; i < lastM; i++) {
            travelM += travel[i];
        }
        for (int i = 0; i < lastP; i++) {
            travelP += travel[i];
        }
        for (int i = 0; i < lastG; i++) {
            travelG += travel[i];
        }

        return totalGarbage + travelM + travelP + travelG;
    }
}

