import java.util.ArrayDeque;
import java.util.Deque;

public class Solution {
    public int validSubarraySize(int[] nums, int threshold) {
        int n = nums.length;
        for (int k = n; k >= 1; k--) {
            int limit = threshold / k; // integer division
            Deque<Integer> dq = new ArrayDeque<>();
            for (int i = 0; i < n; i++) {
                // Remove indices that are out of the current window
                while (!dq.isEmpty() && dq.peekFirst() <= i - k) {
                    dq.pollFirst();
                }
                // Maintain increasing order of values in the deque
                while (!dq.isEmpty() && nums[dq.peekLast()] >= nums[i]) {
                    dq.pollLast();
                }
                dq.offerLast(i);
                // When the window is full, check the minimum
                if (i >= k - 1) {
                    int minVal = nums[dq.peekFirst()];
                    if (minVal > limit) {
                        return k; // largest valid k found
                    }
                }
            }
        }
        return -1; // no valid subarray found
    }
}

