import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countPaths(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];

        int total = m * n;
        int[][] cells = new int[total][3];
        int idx = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                cells[idx][0] = grid[i][j];
                cells[idx][1] = i;
                cells[idx][2] = j;
                idx++;
            }
        }

        Arrays.sort(cells, Comparator.comparingInt(a -> a[0]));

        long answer = 0;
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        for (int[] cell : cells) {
            int val = cell[0];
            int r = cell[1];
            int c = cell[2];

            long paths = 1;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] < val) {
                    paths += dp[nr][nc];
                    if (paths >= MOD) paths -= MOD;
                }
            }
            dp[r][c] = (int) paths;
            answer += dp[r][c];
            if (answer >= MOD) answer -= MOD;
        }

        return (int) answer;
    }
}

