public class Solution {
    public int countSpecialNumbers(int n) {
        String s = Integer.toString(n);
        int len = s.length();
        long[][][][] memo = new long[len + 1][2][1 << 10][2];
        for (int i = 0; i <= len; i++) {
            for (int t = 0; t < 2; t++) {
                for (int m = 0; m < (1 << 10); m++) {
                    for (int st = 0; st < 2; st++) {
                        memo[i][t][m][st] = -1;
                    }
                }
            }
        }
        return (int) dfs(0, 1, 0, 0, s, memo);
    }

    private long dfs(int pos, int tight, int mask, int started, String s, long[][][][] memo) {
        if (pos == s.length()) {
            return started == 1 ? 1 : 0;
        }
        if (memo[pos][tight][mask][started] != -1) {
            return memo[pos][tight][mask][started];
        }
        long res = 0;
        int limit = tight == 1 ? s.charAt(pos) - '0' : 9;
        for (int d = 0; d <= limit; d++) {
            int newStarted = started == 1 || d != 0 ? 1 : 0;
            if (newStarted == 1 && ((mask >> d) & 1) == 1) {
                continue; // digit already used
            }
            int newMask = newStarted == 1 ? mask | (1 << d) : mask;
            int newTight = (tight == 1 && d == limit) ? 1 : 0;
            res += dfs(pos + 1, newTight, newMask, newStarted, s, memo);
        }
        memo[pos][tight][mask][started] = res;
        return res;
    }
}

