public class Solution {
    public long distinctNames(String[] ideas) {
        // Map from first letter to set of suffixes
        Map<Character, Set<String>> groups = new HashMap<>();
        for (String idea : ideas) {
            char first = idea.charAt(0);
            String suffix = idea.substring(1);
            groups.computeIfAbsent(first, k -> new HashSet<>()).add(suffix);
        }

        // List of distinct first letters
        Character[] letters = groups.keySet().toArray(new Character[0]);
        long result = 0L;

        // For each unordered pair of first letters
        for (int i = 0; i < letters.length; i++) {
            for (int j = i + 1; j < letters.length; j++) {
                char a = letters[i];
                char b = letters[j];
                Set<String> setA = groups.get(a);
                Set<String> setB = groups.get(b);

                // Count suffixes unique to each group
                int uniqueA = 0;
                int uniqueB = 0;

                // Iterate over smaller set for efficiency
                if (setA.size() <= setB.size()) {
                    for (String suf : setA) {
                        if (!setB.contains(suf)) uniqueA++;
                    }
                    for (String suf : setB) {
                        if (!setA.contains(suf)) uniqueB++;
                    }
                } else {
                    for (String suf : setB) {
                        if (!setA.contains(suf)) uniqueB++;
                    }
                    for (String suf : setA) {
                        if (!setB.contains(suf)) uniqueA++;
                    }
                }

                result += (long) uniqueA * uniqueB * 2;
            }
        }

        return result;
    }
}

