public class Solution {
    public long countSubarrays(int[] nums, long k) {
        int n = nums.length;
        long ans = 0;
        int left = 0, right = 0;
        long sum = 0;
        int len = 0;

        while (left < n) {
            // Expand the window to the right as far as possible
            while (right < n) {
                long newSum = sum + nums[right];
                int newLen = len + 1;
                // Compute the maximum allowed sum for this length
                long threshold = (k - 1) / newLen; // product < k  =>  newSum <= threshold
                if (newSum <= threshold) {
                    sum = newSum;
                    len = newLen;
                    right++;
                } else {
                    break;
                }
            }

            // All subarrays starting at 'left' and ending before 'right' satisfy the condition
            ans += right - left;

            // Move left pointer forward
            if (right == left) {
                // No element could be added; skip this element
                right++;
                left++;
            } else {
                sum -= nums[left];
                len--;
                left++;
            }
        }

        return ans;
    }
}

