import java.util.*;

public class Solution {
    public int minOperations(int[] nums, int[] numsDivide) {
        // Compute GCD of all elements in numsDivide
        long gcd = numsDivide[0];
        for (int i = 1; i < numsDivide.length; i++) {
            gcd = gcd(gcd, numsDivide[i]);
        }

        // Frequency map for nums
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : nums) {
            freq.put(v, freq.getOrDefault(v, 0) + 1);
        }

        // Sorted copy of nums for binary search
        int[] sorted = nums.clone();
        Arrays.sort(sorted);

        // Find all divisors of gcd
        List<Integer> divisors = new ArrayList<>();
        for (long d = 1; d * d <= gcd; d++) {
            if (gcd % d == 0) {
                divisors.add((int) d);
                if (d != gcd / d) {
                    divisors.add((int) (gcd / d));
                }
            }
        }

        int minDel = Integer.MAX_VALUE;
        for (int d : divisors) {
            Integer countEqual = freq.get(d);
            if (countEqual == null) continue; // d not present in nums

            int countLess = lowerBound(sorted, d);
            int deletions = countLess; // keep all occurrences of d
            if (deletions < minDel) {
                minDel = deletions;
            }
        }

        return minDel == Integer.MAX_VALUE ? -1 : minDel;
    }

    private long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    // Returns the index of the first element >= target
    private int lowerBound(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] < target) {
                l = m + 1;
            } else {
                r = m;
            }
        }
        return l;
    }
}

