import java.util.ArrayList;
import java.util.List;

public class Solution {
    private int[] parent;
    private int[] depth;
    private int[] tin;
    private int[] tout;
    private int timer;
    private int[] xorSub;
    private int[] nums;
    private List<Integer>[] graph;

    public int minimumScore(int[] nums, int[][] edges) {
        this.nums = nums;
        int n = nums.length;
        graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            graph[u].add(v);
            graph[v].add(u);
        }

        parent = new int[n];
        depth = new int[n];
        tin = new int[n];
        tout = new int[n];
        xorSub = new int[n];
        timer = 0;
        dfs(0, -1);

        int total = xorSub[0];

        // Build list of child nodes (each edge represented by its child)
        List<Integer> children = new ArrayList<>();
        for (int i = 1; i < n; i++) {
            children.add(i);
        }

        int minScore = Integer.MAX_VALUE;
        int m = children.size();
        for (int i = 0; i < m; i++) {
            int c1 = children.get(i);
            int xor1 = xorSub[c1];
            for (int j = i + 1; j < m; j++) {
                int c2 = children.get(j);
                int xor2 = xorSub[c2];
                int score;
                if (isAncestor(c1, c2)) {
                    // c1 is ancestor of c2
                    int partA = xor2;                     // subtree of c2
                    int partB = xor1 ^ xor2;              // remaining part of subtree c1
                    int partC = total ^ xor1;             // rest of the tree
                    score = max(partA, partB, partC) - min(partA, partB, partC);
                } else if (isAncestor(c2, c1)) {
                    // c2 is ancestor of c1
                    int partA = xor1;                     // subtree of c1
                    int partB = xor2 ^ xor1;              // remaining part of subtree c2
                    int partC = total ^ xor2;             // rest of the tree
                    score = max(partA, partB, partC) - min(partA, partB, partC);
                } else {
                    // disjoint
                    int partA = xor1;
                    int partB = xor2;
                    int partC = total ^ xor1 ^ xor2;
                    score = max(partA, partB, partC) - min(partA, partB, partC);
                }
                if (score < minScore) minScore = score;
            }
        }
        return minScore;
    }

    private void dfs(int node, int par) {
        parent[node] = par;
        tin[node] = ++timer;
        xorSub[node] = nums[node];
        for (int nb : graph[node]) {
            if (nb == par) continue;
            dfs(nb, node);
            xorSub[node] ^= xorSub[nb];
        }
        tout[node] = ++timer;
    }

    private boolean isAncestor(int anc, int desc) {
        return tin[anc] <= tin[desc] && tout[desc] <= tout[anc];
    }

    private int max(int a, int b, int c) {
        return Math.max(a, Math.max(b, c));
    }

    private int min(int a, int b, int c) {
        return Math.min(a, Math.min(b, c));
    }
}

