import java.util.Arrays;

public class Solution {
    public Long[] maximumSegmentSum(int[] nums, int[] removeQueries) {
        int n = nums.length;
        Long[] ans = new Long[n];
        boolean[] active = new boolean[n];
        DSU dsu = new DSU(n);
        long maxSum = 0;
        for (int i = n - 1; i >= 0; i--) {
            int idx = removeQueries[i];
            ans[i] = maxSum;          // record state before adding back
            active[idx] = true;
            dsu.add(idx, nums[idx]);
            if (idx > 0 && active[idx - 1]) {
                dsu.union(idx, idx - 1);
            }
            if (idx + 1 < n && active[idx + 1]) {
                dsu.union(idx, idx + 1);
            }
            maxSum = Math.max(maxSum, dsu.getSum(idx));
        }
        return ans;
    }

    private static class DSU {
        private final int[] parent;
        private final int[] size;
        private final long[] sum;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            sum = new long[n];
            Arrays.fill(parent, -1);
        }

        void add(int idx, int val) {
            parent[idx] = idx;
            size[idx] = 1;
            sum[idx] = val;
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
            sum[ra] += sum[rb];
        }

        long getSum(int x) {
            return sum[find(x)];
        }
    }
}

