public class Solution {
    public boolean validPartition(int[] nums) {
        int n = nums.length;
        if (n < 2) return false;
        boolean[] dp = new boolean[n + 1];
        dp[0] = true; // empty prefix is valid

        for (int i = 1; i <= n; i++) {
            // pair of equal elements
            if (i >= 2 && nums[i - 1] == nums[i - 2] && dp[i - 2]) {
                dp[i] = true;
            }
            // triplet of equal elements
            if (!dp[i] && i >= 3 &&
                nums[i - 1] == nums[i - 2] &&
                nums[i - 2] == nums[i - 3] &&
                dp[i - 3]) {
                dp[i] = true;
            }
            // triplet of consecutive increasing elements
            if (!dp[i] && i >= 3 &&
                nums[i - 3] + 1 == nums[i - 2] &&
                nums[i - 2] + 1 == nums[i - 1] &&
                dp[i - 3]) {
                dp[i] = true;
            }
        }
        return dp[n];
    }
}

