public class Solution {
    public String largestPalindromic(String num) {
        int[] freq = new int[10];
        for (char c : num.toCharArray()) {
            freq[c - '0']++;
        }

        StringBuilder left = new StringBuilder();
        for (int d = 9; d >= 0; d--) {
            while (freq[d] >= 2) {
                left.append(d);
                freq[d] -= 2;
            }
        }

        // Find the largest middle digit (odd count)
        int middleDigit = -1;
        for (int d = 9; d >= 0; d--) {
            if (freq[d] % 2 == 1) {
                middleDigit = d;
                break;
            }
        }

        StringBuilder palindrome = new StringBuilder();
        palindrome.append(left);
        if (middleDigit != -1) {
            palindrome.append(middleDigit);
        }
        palindrome.append(left.reverse());

        String result = palindrome.toString();
        if (result.isEmpty()) {
            return "";
        }
        // Remove leading zeros: if the palindrome starts with '0', the only valid palindrome is "0"
        if (result.charAt(0) == '0') {
            return "0";
        }
        return result;
    }
}

