import java.util.*;

public class Solution {
    public int longestCycle(int[] edges) {
        int n = edges.length;
        int[] depth = new int[n];
        Arrays.fill(depth, -1);
        boolean[] visited = new boolean[n];
        int maxLen = -1;

        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;

            int step = 0;
            int cur = i;
            List<Integer> path = new ArrayList<>();

            while (cur != -1 && !visited[cur]) {
                visited[cur] = true;
                depth[cur] = step++;
                path.add(cur);
                cur = edges[cur];
            }

            if (cur != -1 && depth[cur] != -1) {
                int cycleLen = step - depth[cur];
                if (cycleLen > maxLen) maxLen = cycleLen;
            }

            // reset depth for nodes in this traversal
            for (int node : path) {
                depth[node] = -1;
            }
        }

        return maxLen;
    }
}

