        // Check for Three of a Kind (at least 3 of the same rank)
        for (int cnt : rankCount.values()) {
            if (cnt >= 3) {
                return "Three of a Kind";
            }
        }

        // Check for Pair (at least 2 of the same rank)
        for (int cnt : rankCount.values()) {
            if (cnt >= 2) {
                return "Pair";
            }
        }

        // Otherwise High Card
        return "High Card";
    }
}

