public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        int[] diff = new int[n];
        int maxDiff = 0;
        for (int i = 0; i < n; i++) {
            diff[i] = Math.abs(nums1[i] - nums2[i]);
            if (diff[i] > maxDiff) maxDiff = diff[i];
        }

        long[] freq = new long[maxDiff + 1];
        for (int d : diff) {
            freq[d]++;
        }

        long ops = (long) k1 + k2;
        for (int d = maxDiff; d > 0 && ops > 0; d--) {
            long cnt = freq[d];
            if (cnt == 0) continue;
            if (ops >= cnt) {
                freq[d - 1] += cnt;
                ops -= cnt;
                freq[d] = 0;
            } else {
                freq[d - 1] += ops;
                freq[d] -= ops;
                ops = 0;
            }
        }

        long result = 0;
        for (int d = 0; d <= maxDiff; d++) {
            if (freq[d] > 0) {
                result += freq[d] * d * d;
            }
        }
        return result;
    }
}

