public class Solution {
    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        if (m == 0) return 0;
        int n = matrix[0].length;

        // Convert each row to a bitmask
        long[] rowMasks = new long[m];
        for (int i = 0; i < m; i++) {
            long mask = 0L;
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 1) {
                    mask |= (1L << j);
                }
            }
            rowMasks[i] = mask;
        }

        int maxCovered = 0;
        int totalSubsets = 1 << m; // m <= 20 in typical constraints

        for (int subset = 0; subset < totalSubsets; subset++) {
            long unionMask = 0L;
            int rowsInSubset = 0;
            for (int i = 0; i < m; i++) {
                if ((subset & (1 << i)) != 0) {
                    rowsInSubset++;
                    unionMask |= rowMasks[i];
                }
            }
            if (Long.bitCount(unionMask) <= numSelect) {
                if (rowsInSubset > maxCovered) {
                    maxCovered = rowsInSubset;
                }
            }
        }

        return maxCovered;
    }
}

