import java.util.HashMap;
import java.util.Map;

public class Solution {
    public long sellingWood(int m, int n, int[][] prices) {
        // Map to store price for each exact (height,width) pair
        Map<Long, Long> priceMap = new HashMap<>();
        for (int[] p : prices) {
            long key = ((long) p[0] << 32) | (p[1] & 0xffffffffL);
            priceMap.put(key, (long) p[2]);
        }

        long[][] dp = new long[m + 1][n + 1];

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                long best = 0;

                // Direct sale if available
                long key = ((long) i << 32) | (j & 0xffffffffL);
                if (priceMap.containsKey(key)) {
                    best = priceMap.get(key);
                }

                // Horizontal cuts
                for (int k = 1; k < i; k++) {
                    long val = dp[k][j] + dp[i - k][j];
                    if (val > best) best = val;
                }

                // Vertical cuts
                for (int k = 1; k < j; k++) {
                    long val = dp[i][k] + dp[i][j - k];
                    if (val > best) best = val;
                }

                dp[i][j] = best;
            }
        }

        return dp[m][n];
    }
}

