public class Solution {
    public int minimumRecolors(String blocks, int k) {
        int n = blocks.length();
        if (k > n) return -1; // or throw exception, but problem guarantees k <= n

        int whiteCount = 0;
        // Count whites in the first window
        for (int i = 0; i < k; i++) {
            if (blocks.charAt(i) == 'W') whiteCount++;
        }

        int minRecolors = whiteCount;

        // Slide the window
        for (int i = k; i < n; i++) {
            if (blocks.charAt(i - k) == 'W') whiteCount--; // leftmost leaving
            if (blocks.charAt(i) == 'W') whiteCount++;     // new entering
            if (whiteCount < minRecolors) minRecolors = whiteCount;
        }

        return minRecolors;
    }
}

