import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    // Using topological sort to solve this problem
    public int[][] buildMatrix(int k, int[][] rowC, int[][] colC) {
        int[] rowOrder = topoSort(k, rowC);
        int[] colOrder = topoSort(k, colC);
        if (rowOrder == null || colOrder == null) {
            return new int[0][0];
        }

        int[][] matrix = new int[k][k];
        int[] rowIndex = new int[k + 1];
        int[] colIndex = new int[k + 1];

        for (int i = 0; i < k; i++) {
            rowIndex[rowOrder[i]] = i;
            colIndex[colOrder[i]] = i;
        }

        for (int num = 1; num <= k; num++) {
            matrix[rowIndex[num]][colIndex[num]] = num;
        }

        return matrix;
    }

    private int[] topoSort(int k, int[][] conditions) {
        List<Integer>[] graph = new ArrayList[k + 1];
        for (int i = 1; i <= k; i++) {
            graph[i] = new ArrayList<>();
        }
        int[] indegree = new int[k + 1];

        for (int[] edge : conditions) {
            int from = edge[0];
            int to = edge[1];
            graph[from].add(to);
            indegree[to]++;
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= k; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
        }

        List<Integer> order = new ArrayList<>();
        while (!queue.isEmpty()) {
            int node = queue.poll();
            order.add(node);
            for (int neighbor : graph[node]) {
                indegree[neighbor]--;
                if (indegree[neighbor] == 0) {
                    queue.offer(neighbor);
                }
            }
        }

        if (order.size() != k) {
            return null; // cycle detected
        }

        int[] result = new int[k];
        for (int i = 0; i < k; i++) {
            result[i] = order.get(i);
        }
        return result;
    }
}

