public class Solution {
    public int[] smallestTrimmedNumbers(String[] nums, int[][] queries) {
        int n = nums.length;
        int len = nums[0].length();

        // Precompute sorted indices for each trim length
        Map<Integer, Integer[]> sortedByTrim = new HashMap<>();
        for (int trim = 1; trim <= len; trim++) {
            Integer[] idx = new Integer[n];
            for (int i = 0; i < n; i++) idx[i] = i;
            final int t = trim;
            Arrays.sort(idx, (i, j) -> {
                int cmp = nums[i].substring(len - t).compareTo(nums[j].substring(len - t));
                if (cmp != 0) return cmp;
                return Integer.compare(i, j);
            });
            sortedByTrim.put(trim, idx);
        }

        int q = queries.length;
        int[] answer = new int[q];
        for (int qi = 0; qi < q; qi++) {
            int k = queries[qi][0];
            int trim = queries[qi][1];
            Integer[] sortedIdx = sortedByTrim.get(trim);
            answer[qi] = sortedIdx[k - 1];
        }
        return answer;
    }
}

