public class Solution {
    public int minimumNumbers(int nums, int k) {
        // Handle the special case where the target sum is zero.
        if (nums == 0) {
            return 0;
        }

        // If k is 0, each number must be a multiple of 10.
        if (k == 0) {
            return (nums % 10 == 0) ? 1 : -1;
        }

        // If the target sum is less than k, it's impossible.
        if (nums < k) {
            return -1;
        }

        // Try all possible counts from 1 to 10.
        // The modulo 10 condition repeats every 10 numbers.
        for (int m = 1; m <= 10; m++) {
            int remaining = nums - m * k;
            if (remaining >= 0 && remaining % 10 == 0) {
                return m;
            }
        }

        // No valid count found.
        return -1;
    }
}

