public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int countHousePlacements(int n) {
        long f = fib(n + 2)[0];          // number of ways for one side
        long ans = (f * f) % MOD;        // independent choices for two sides
        return (int) ans;
    }

    // Returns an array {F(n), F(n+1)} modulo MOD
    private static long[] fib(long n) {
        if (n == 0) {
            return new long[]{0L, 1L};
        }
        long[] half = fib(n >> 1);
        long a = half[0]; // F(k)
        long b = half[1]; // F(k+1)

        long c = (a * ((2 * b % MOD - a + MOD) % MOD)) % MOD; // F(2k)
        long d = (a * a % MOD + b * b % MOD) % MOD;           // F(2k+1)

        if ((n & 1) == 0) {
            return new long[]{c, d};
        } else {
            long e = (c + d) % MOD; // F(2k+2)
            return new long[]{d, e};
        }
    }
}

