import java.util.Arrays;

public class Solution {
    public int[] answerQueries(int[] nums, int[] queries) {
        int n = nums.length;
        int m = queries.length;
        int[] result = new int[m];

        if (n == 0) {
            // No elements to form a subsequence
            return result;
        }

        // Sort the array to pick smallest elements first
        Arrays.sort(nums);

        // Compute prefix sums using long to avoid overflow
        long[] prefix = new long[n];
        prefix[0] = nums[0];
        for (int i = 1; i < n; i++) {
            prefix[i] = prefix[i - 1] + nums[i];
        }

        // Answer each query
        for (int i = 0; i < m; i++) {
            long q = queries[i];
            int idx = upperBound(prefix, q); // last index with prefix <= q
            result[i] = idx + 1; // size of subsequence
        }

        return result;
    }

    // Binary search to find the last index where arr[idx] <= target
    private int upperBound(long[] arr, long target) {
        int left = 0;
        int right = arr.length - 1;
        int res = -1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] <= target) {
                res = mid;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return res;
    }
}

