public class Solution {
    public int latestTimeCatchTheBus(int[] buses, int[] passengers, int capacity) {
        Arrays.sort(buses);
        Arrays.sort(passengers);
        Set<Integer> passengerSet = new HashSet<>();
        for (int p : passengers) passengerSet.add(p);

        int passengerIdx = 0;
        int lastBusCapacityUsed = 0;
        int lastPassengerTime = -1;

        for (int bus : buses) {
            int used = 0;
            while (passengerIdx < passengers.length && passengers[passengerIdx] <= bus && used < capacity) {
                used++;
                lastPassengerTime = passengers[passengerIdx];
                passengerIdx++;
            }
            if (bus == buses[buses.length - 1]) {
                lastBusCapacityUsed = used;
            }
        }

        if (lastBusCapacityUsed < capacity) {
            return buses[buses.length - 1];
        } else {
            int candidate = lastPassengerTime - 1;
            while (candidate >= 0 && passengerSet.contains(candidate)) {
                candidate--;
            }
            return candidate;
        }
    }
}

