import java.util.Arrays;

public class Solution {
    public int countSubarrays(int[] nums, int k) {
        int n = nums.length;
        int[] prefix = new int[n + 1];
        int idx = -1;
        for (int i = 0; i < n; i++) {
            if (nums[i] == k) idx = i;
            if (nums[i] > k) {
                prefix[i + 1] = prefix[i] + 1;
            } else if (nums[i] < k) {
                prefix[i + 1] = prefix[i] - 1;
            } else {
                prefix[i + 1] = prefix[i];
            }
        }

        // Build sorted array of prefix sums up to idx (inclusive)
        int[] left = new int[idx + 1];
        System.arraycopy(prefix, 0, left, 0, idx + 1);
        Arrays.sort(left);

        long result = 0;
        for (int r = idx + 1; r <= n; r++) {
            int val = prefix[r];
            int pos = Arrays.binarySearch(left, val);
            int count;
            if (pos >= 0) {
                count = pos + 1; // all indices <= pos are <= val
            } else {
                count = -(pos + 1); // insertion point gives number of elements <= val
            }
            result += count;
        }
        return (int) result;
    }
}

