public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        long INF = (long) k + 1; // any value > k is considered invalid
        long[][] dp = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = INF;
            }
        }
        dp[0][0] = 0;
        for (int pos = 0; pos < n; pos++) {
            char c = s.charAt(pos);
            int bit = c - '0';
            for (int len = 0; len <= pos; len++) {
                long cur = dp[pos][len];
                if (cur > k) continue; // unreachable or already > k
                // skip current character
                if (dp[pos + 1][len] > cur) {
                    dp[pos + 1][len] = cur;
                }
                // take current character
                long newVal = cur * 2 + bit;
                if (newVal <= k) {
                    if (dp[pos + 1][len + 1] > newVal) {
                        dp[pos + 1][len + 1] = newVal;
                    }
                }
            }
        }
        int best = 0;
        for (int len = 0; len <= n; len++) {
            if (dp[n][len] <= k && len > best) {
                best = len;
            }
        }
        return best;
    }
}

