import java.util.Arrays;

public class Solution {

    public long numberOfPairs(int[] nums1, int[] nums2, int diff) {
        return countPairs(nums1, nums2, diff);
    }

    private long countPairs(int[] nums1, int[] nums2, int diff) {
        int n = nums1.length;
        long[] A = new long[n];
        for (int i = 0; i < n; i++) {
            A[i] = (long) nums1[i] - nums2[i];
        }

        // Coordinate compression
        long[] sortedVals = A.clone();
        Arrays.sort(sortedVals);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sortedVals[i] != sortedVals[i - 1]) {
                sortedVals[m++] = sortedVals[i];
            }
        }
        long[] uniq = Arrays.copyOf(sortedVals, m);

        BIT bit = new BIT(m);
        long ans = 0;
        for (int j = 0; j < n; j++) {
            long threshold = A[j] + diff;
            int idx = upperBound(uniq, threshold); // number of elements <= threshold
            ans += bit.query(idx);
            int pos = Arrays.binarySearch(uniq, A[j]) + 1; // 1-indexed
            bit.update(pos, 1);
        }
        return ans;
    }

    // Binary Indexed Tree (Fenwick Tree)
    private static class BIT {
        private final int size;
        private final long[] tree;

        BIT(int n) {
            size = n;
            tree = new long[n + 2];
        }

        void update(int idx, long delta) {
            for (int i = idx; i <= size; i += i & -i) {
                tree[i] += delta;
            }
        }

        long query(int idx) {
            long sum = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }

    // Returns the number of elements in arr that are <= target
    private static int upperBound(long[] arr, long target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] <= target) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l; // count of elements <= target
    }
}

