import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int unequalTriplets(int[] nums) {
        int n = nums.length;
        if (n < 3) return 0;

        // Count occurrences of each value
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        long totalTriplets = (long) n * (n - 1) * (n - 2) / 6; // n choose 3

        long subtractTwoEqual = 0;
        long subtractAllEqual = 0;

        for (int count : freq.values()) {
            if (count >= 2) {
                long c2 = (long) count * (count - 1) / 2; // C(count, 2)
                subtractTwoEqual += c2 * (n - count);
            }
            if (count >= 3) {
                long c3 = (long) count * (count - 1) * (count - 2) / 6; // C(count, 3)
                subtractAllEqual += c3;
            }
        }

        long result = totalTriplets - subtractTwoEqual - subtractAllEqual;
        return (int) result;
    }
}

