import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int subarrayGCD(int[] nums, int k) {
        long ans = 0;
        Map<Integer, Integer> current = new HashMap<>();

        for (int num : nums) {
            Map<Integer, Integer> next = new HashMap<>();

            // Subarray consisting of only the current element
            next.put(num, next.getOrDefault(num, 0) + 1);

            // Extend previous subarrays by the current element
            for (Map.Entry<Integer, Integer> entry : current.entrySet()) {
                int g = entry.getKey();
                int cnt = entry.getValue();
                int newG = gcd(g, num);
                next.put(newG, next.getOrDefault(newG, 0) + cnt);
            }

            ans += next.getOrDefault(k, 0);
            current = next;
        }

        return (int) ans;
    }

    private int gcd(int a, int b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

