    public int[][] onesMinusZeros(int[][] grid) {
        int m = grid.length;
        if (m == 0) return new int[0][0];
        int n = grid[0].length;
        if (n == 0) return new int[m][0];

        int[] onesRow = new int[m];
        int[] onesCol = new int[n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    onesRow[i]++;
                    onesCol[j]++;
                }
            }
        }

        int[][] diff = new int[m][n];
        int constant = m + n;

        for (int i = 0; i < m; i++) {
            int rowContribution = 2 * onesRow[i];
            for (int j = 0; j < n; j++) {
                diff[i][j] = rowContribution + 2 * onesCol[j] - constant;
            }
        }

        return diff;
    }
}

