import java.util.*;

public class Solution {
    private static class State {
        long sum;
        int idx;

        State(long sum, int idx) {
            this.sum = sum;
            this.idx = idx;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof State)) return false;
            State s = (State) o;
            return sum == s.sum && idx == s.idx;
        }

        @Override
        public int hashCode() {
            return Objects.hash(sum, idx);
        }
    }

    public long kSum(int[] nums, int k) {
        if (nums == null || nums.length == 0) {
            return 0L;
        }

        int n = nums.length;
        // sort in non‑increasing order
        Arrays.sort(nums);
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }

        long total = 0L;
        for (int v : nums) {
            total += v;
        }

        PriorityQueue<State> pq = new PriorityQueue<>(
                (a, b) -> Long.compare(b.sum, a.sum)); // max‑heap
        Set<State> seen = new HashSet<>();

        State start = new State(total, n - 1);
        pq.offer(start);
        seen.add(start);

        State cur = null;
        for (int i = 0; i < k; i++) {
            cur = pq.poll();
            if (cur == null) {
                break;
            }
            int idx = cur.idx;
            if (idx > 0) {
                // Exclude current element
                long excludeSum = cur.sum - nums[idx];
                State exclude = new State(excludeSum, idx - 1);
                if (seen.add(exclude)) {
                    pq.offer(exclude);
                }

                // Replace current element with next smaller one
                long replaceSum = cur.sum - nums[idx] + nums[idx - 1];
                State replace = new State(replaceSum, idx - 1);
                if (seen.add(replace)) {
                    pq.offer(replace);
                }
            }
        }

        return cur == null ? 0L : cur.sum;
    }
}

