public class Solution {
    public String oddString(String[] w) {
        int n = w[0].length();
        String diff0 = diffKey(w[0], n);
        String diff1 = diffKey(w[1], n);

        // If first two are the same, find the first different one
        if (diff0.equals(diff1)) {
            for (int i = 2; i < w.length; i++) {
                if (!diffKey(w[i], n).equals(diff0)) {
                    return w[i];
                }
            }
            // Should not reach here as per problem statement
            return w[0];
        } else {
            // First two differ, need to determine which one is odd
            String diff2 = diffKey(w[2], n);
            if (diff2.equals(diff0)) {
                // w[1] is odd
                return w[1];
            } else if (diff2.equals(diff1)) {
                // w[0] is odd
                return w[0];
            } else {
                // w[2] is odd
                return w[2];
            }
        }
    }

    // Helper to compute a string representation of the difference array
    private String diffKey(String s, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n - 1; i++) {
            sb.append(s.charAt(i + 1) - s.charAt(i));
            sb.append(',');
        }
        return sb.toString();
    }
}

