import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public class Solution {
    public long minimumTotalDistance(List<Integer> robot, int[][] f) {
        int n = robot.size();
        int m = f.length;

        // Convert robot list to array for sorting
        int[] robots = new int[n];
        for (int i = 0; i < n; i++) {
            robots[i] = robot.get(i);
        }
        Arrays.sort(robots);

        // Copy factories and sort by position
        int[][] factories = new int[m][2];
        for (int i = 0; i < m; i++) {
            factories[i][0] = f[i][0]; // position
            factories[i][1] = f[i][1]; // remaining capacity
        }
        Arrays.sort(factories, Comparator.comparingInt(a -> a[0]));

        long totalDistance = 0L;
        int factoryIdx = 0;

        for (int rPos : robots) {
            // Skip factories that are already full
            while (factoryIdx < m && factories[factoryIdx][1] == 0) {
                factoryIdx++;
            }

            // Problem guarantees that a factory will be found
            int fPos = factories[factoryIdx][0];
            totalDistance += Math.abs(rPos - fPos);

            // Decrease capacity and move to next factory if needed
            factories[factoryIdx][1]--;
            if (factories[factoryIdx][1] == 0) {
                factoryIdx++;
            }
        }

        return totalDistance;
    }
}

