import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }

        // Sort intervals by start time
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // Min-heap to keep track of the earliest ending interval in each group
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();

        int maxGroups = 0;

        for (int[] interval : intervals) {
            int start = interval[0];
            int end = interval[1];

            // Remove all intervals that end before the current start (no overlap)
            while (!minHeap.isEmpty() && minHeap.peek() < start) {
                minHeap.poll();
            }

            // Add current interval's end to the heap
            minHeap.offer(end);

            // Update maximum number of groups needed so far
            maxGroups = Math.max(maxGroups, minHeap.size());
        }

        return maxGroups;
    }
}

