public class Solution {
    public int[] applyOperations(int[] nums) {
        int n = nums.length;
        // Apply the operations sequentially
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] == nums[i + 1]) {
                nums[i] *= 2;
                nums[i + 1] = 0;
            }
        }
        // Shift all zeros to the end
        int write = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] != 0) {
                nums[write++] = nums[i];
            }
        }
        while (write < n) {
            nums[write++] = 0;
        }
        return nums;
    }
