public class Solution {
    private static final long BASE = 911382323L;

    public int deleteString(String s) {
        int n = s.length();
        long[] pref = new long[n + 1];
        long[] pow = new long[n + 1];
        pow[0] = 1;
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] * BASE + (s.charAt(i) - 'a' + 1);
            pow[i + 1] = pow[i] * BASE;
        }

        java.util.function.IntBinaryOperator getHash = (l, r) -> {
            long h = pref[r] - pref[l] * pow[r - l];
            return (int) h;
        };

        int[] dp = new int[n + 1];
        dp[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            int best = 1; // delete entire suffix
            int maxJ = (n - i) / 2;
            for (int j = 1; j <= maxJ; j++) {
                if (getHash.applyAsInt(i, i + j) == getHash.applyAsInt(i + j, i + 2 * j)) {
                    best = Math.max(best, 1 + dp[i + j]);
                }
            }
            dp[i] = best;
        }
        return dp[0];
    }
}

