import java.util.*;

public class Solution {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public class Solution {
    public int[] treeQueries(TreeNode root, int[] queries) {
        int nodeCount = countNodes(root);
        int[] depth = new int[nodeCount + 1];
        int[] subtreeMaxDepth = new int[nodeCount + 1];
        int[] bestOutside = new int[nodeCount + 1];

        computeDepthAndSubtree(root, 0, depth, subtreeMaxDepth);
        computeBestOutside(root, -1, depth, subtreeMaxDepth, bestOutside);

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            answer[i] = bestOutside[queries[i]];
        }
        return answer;
    }

    private int countNodes(TreeNode node) {
        if (node == null) return 0;
        return 1 + countNodes(node.left) + countNodes(node.right);
    }

    private int computeDepthAndSubtree(TreeNode node, int d, int[] depth, int[] subtreeMaxDepth) {
        depth[node.val] = d;
        int leftMax = -1;
        int rightMax = -1;
        if (node.left != null) leftMax = computeDepthAndSubtree(node.left, d + 1, depth, subtreeMaxDepth);
        if (node.right != null) rightMax = computeDepthAndSubtree(node.right, d + 1, depth, subtreeMaxDepth);
        int maxSub = Math.max(d, Math.max(leftMax, rightMax));
        subtreeMaxDepth[node.val] = maxSub;
        return maxSub;
    }

    private void computeBestOutside(TreeNode node, int bestOutsideParent, int[] depth, int[] subtreeMaxDepth, int[] bestOutside) {
        bestOutside[node.val] = bestOutsideParent;
        if (node.left != null) {
            int siblingMax = (node.right != null) ? subtreeMaxDepth[node.right.val] : -1;
            int bestOutsideChild = Math.max(bestOutsideParent, Math.max(siblingMax, depth[node.val]));
            computeBestOutside(node.left, bestOutsideChild, depth, subtreeMaxDepth, bestOutside);
        }
        if (node.right != null) {
            int siblingMax = (node.left != null) ? subtreeMaxDepth[node.left.val] : -1;
            int bestOutsideChild = Math.max(bestOutsideParent, Math.max(siblingMax, depth[node.val]));
            computeBestOutside(node.right, bestOutsideChild, depth, subtreeMaxDepth, bestOutside);
        }
    }
}

