public class Solution {
    public int[] smallestSubarrays(int[] nums) {
        int n = nums.length;
        int[] answer = new int[n];
        if (n == 0) return answer;

        final int BITS = 31; // handle up to 2^30
        int[][] nextPos = new int[BITS][n + 1];
        // initialize sentinel
        for (int b = 0; b < BITS; b++) {
            nextPos[b][n] = n;
        }

        // compute next occurrence of each bit from right to left
        for (int i = n - 1; i >= 0; i--) {
            int val = nums[i];
            for (int b = 0; b < BITS; b++) {
                if (((val >> b) & 1) == 1) {
                    nextPos[b][i] = i;
                } else {
                    nextPos[b][i] = nextPos[b][i + 1];
                }
            }
        }

        // suffix OR array
        int[] suffixOr = new int[n + 1];
        suffixOr[n] = 0;
        for (int i = n - 1; i >= 0; i--) {
            suffixOr[i] = suffixOr[i + 1] | nums[i];
        }

        // compute answer for each starting index
        for (int i = 0; i < n; i++) {
            int targetOr = suffixOr[i];
            int j = i;
            for (int b = 0; b < BITS; b++) {
                if (((targetOr >> b) & 1) == 1) {
                    int pos = nextPos[b][i];
                    if (pos > j) j = pos;
                }
            }
            answer[i] = j - i + 1;
        }

        return answer;
    }
}

