public class Solution {
    public long totalCost(int[] costs, int k, int candidates) {
        int n = costs.length;
        // Min-heap ordered by cost, then by index
        PriorityQueue<int[]> left = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        PriorityQueue<int[]> right = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });

        int leftIdx = 0;
        int rightIdx = n - 1;

        // Fill left heap
        while (leftIdx <= rightIdx && left.size() < candidates) {
            left.offer(new int[]{costs[leftIdx], leftIdx});
            leftIdx++;
        }

        // Fill right heap
        while (rightIdx >= leftIdx && right.size() < candidates) {
            right.offer(new int[]{costs[rightIdx], rightIdx});
            rightIdx--;
        }

        long total = 0;
        for (int hire = 0; hire < k; hire++) {
            int[] pick;
            if (left.isEmpty()) {
                pick = right.poll();
                // Add next from right side if available
                if (rightIdx >= leftIdx) {
                    right.offer(new int[]{costs[rightIdx], rightIdx});
                    rightIdx--;
                }
            } else if (right.isEmpty()) {
                pick = left.poll();
                // Add next from left side if available
                if (leftIdx <= rightIdx) {
                    left.offer(new int[]{costs[leftIdx], leftIdx});
                    leftIdx++;
                }
            } else {
                int[] leftTop = left.peek();
                int[] rightTop = right.peek();
                if (leftTop[0] < rightTop[0] || (leftTop[0] == rightTop[0] && leftTop[1] < rightTop[1])) {
                    pick = left.poll();
                    if (leftIdx <= rightIdx) {
                        left.offer(new int[]{costs[leftIdx], leftIdx});
                        leftIdx++;
                    }
                } else {
                    pick = right.poll();
                    if (rightIdx >= leftIdx) {
                        right.offer(new int[]{costs[rightIdx], rightIdx});
                        rightIdx--;
                    }
                }
            }
            total += pick[0];
        }

        return total;
    }
}

