        buildSet(root, set);

        int[][] answer = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            Integer floor = set.floor(queries[i]);   // largest <= query
            Integer ceil  = set.ceiling(queries[i]); // smallest >= query

