public class Solution {
    public List<List<String>> mostPopularCreator(String[] creators, String[] ids, int[] views) {
        // Map to store total views per creator
        Map<String, Long> totalViews = new HashMap<>();
        // Map to store best video info per creator
        Map<String, VideoInfo> bestVideo = new HashMap<>();

        for (int i = 0; i < creators.length; i++) {
            String creator = creators[i];
            String id = ids[i];
            long viewCount = views[i];

            // Update total views
            totalViews.put(creator, totalViews.getOrDefault(creator, 0L) + viewCount);

            // Update best video
            VideoInfo currentBest = bestVideo.get(creator);
            if (currentBest == null ||
                viewCount > currentBest.views ||
                (viewCount == currentBest.views && id.compareTo(currentBest.id) < 0)) {
                bestVideo.put(creator, new VideoInfo(viewCount, id));
            }
        }

        // Find maximum total views
        long maxTotal = 0;
        for (long v : totalViews.values()) {
            if (v > maxTotal) {
                maxTotal = v;
            }
        }

        // Collect creators with maximum total views
        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<String, Long> entry : totalViews.entrySet()) {
            if (entry.getValue() == maxTotal) {
                String creator = entry.getKey();
                String bestId = bestVideo.get(creator).id;
                List<String> pair = new ArrayList<>(2);
                pair.add(creator);
                pair.add(bestId);
                result.add(pair);
            }
        }

        return result;
    }

    // Helper class to store best video information
    private static class VideoInfo {
        long views;
        String id;

        VideoInfo(long views, String id) {
            this.views = views;
            this.id = id;
        }
    }
