import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int destroyTargets(int[] nums, int space) {
        // Group numbers by their remainder modulo space
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int num : nums) {
            int rem = num % space;
            groups.computeIfAbsent(rem, k -> new ArrayList<>()).add(num);
        }

        int bestCount = -1;
        int bestSeed = Integer.MAX_VALUE;

        // For each remainder group, sort ascending and evaluate each possible seed
        for (List<Integer> list : groups.values()) {
            Collections.sort(list);
            int size = list.size();
            for (int i = 0; i < size; i++) {
                int seed = list.get(i);
                int count = size - i; // all numbers from i to end are >= seed and same remainder
                if (count > bestCount || (count == bestCount && seed < bestSeed)) {
                    bestCount = count;
                    bestSeed = seed;
                }
            }
        }

        return bestSeed;
    }
}

