public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        int n = nodeValues.length;
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        int maxSum = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            int centerVal = nodeValues[i];
            List<Integer> positiveNeighbors = new ArrayList<>();
            for (int nb : adj.get(i)) {
                int val = nodeValues[nb];
                if (val > 0) {
                    positiveNeighbors.add(val);
                }
            }
            if (!positiveNeighbors.isEmpty()) {
                positiveNeighbors.sort(Collections.reverseOrder());
            }
            int edgesToTake = Math.min(maxNumberOfEdges, positiveNeighbors.size());
            int sum = centerVal;
            for (int j = 0; j < edgesToTake; j++) {
                sum += positiveNeighbors.get(j);
            }
            if (sum > maxSum) {
                maxSum = sum;
            }
        }
        return maxSum;
    }
}

