import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int minScore(int n, int[][] roads) {
        // Build adjacency list for BFS
        List<List<Integer>> adj = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            adj.get(a).add(b);
            adj.get(b).add(a);
        }

        // BFS from city 1 to find reachable cities
        boolean[] visited = new boolean[n + 1];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        visited[1] = true;
        queue.add(1);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int next : adj.get(cur)) {
                if (!visited[next]) {
                    visited[next] = true;
                    queue.add(next);
                }
            }
        }

        // Find the minimum edge weight in the component containing city 1 (and n)
        int minWeight = Integer.MAX_VALUE;
        for (int[] road : roads) {
            int a = road[0];
            int b = road[1];
            int w = road[2];
            if (visited[a] && visited[b]) {
                if (w < minWeight) {
                    minWeight = w;
                }
            }
        }

        return minWeight;
    }
}

