/**
 * Solution for the minimum fuel cost problem.
 */
public class Solution {

    private long totalFuel;

    public int minimumFuelCost(int[][] roads, int seats) {
        int n = roads.length + 1;
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] e : roads) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        totalFuel = 0;
        dfs(0, -1, adj, seats);
        return (int) totalFuel;
    }

    /**
     * Depth‑first search that returns the number of representatives in the subtree rooted at {@code node}.
     * While returning, it accumulates the fuel needed to bring those representatives up to the parent.
     */
    private long dfs(int node, int parent, List<List<Integer>> adj, int seats) {
        long reps = 1; // representative of this city
        for (int nei : adj.get(node)) {
            if (nei == parent) continue;
            long sub = dfs(nei, node, adj, seats);
            totalFuel += (sub + seats - 1) / seats; // fuel for this child subtree
            reps += sub;
        }
        return reps;
    }
}

