import java.util.Arrays;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;

        // dp arrays: prev[j][r] = number of ways to reach cell (i-1, j) with sum % k == r
        // cur[j][r] = number of ways to reach cell (i, j) with sum % k == r
        int[][] prev = new int[n][k];
        int[][] cur = new int[n][k];

        // Initialize first cell (0,0)
        int valMod = mod(grid[0][0], k);
        cur[0][valMod] = 1;

        // First row (i = 0), only moves from left
        for (int j = 1; j < n; j++) {
            valMod = mod(grid[0][j], k);
            for (int rPrev = 0; rPrev < k; rPrev++) {
                int cnt = cur[j - 1][rPrev];
                if (cnt == 0) continue;
                int r = (rPrev + valMod) % k;
                cur[j][r] += cnt;
                if (cur[j][r] >= MOD) cur[j][r] -= MOD;
            }
        }

        // Swap prev and cur for next iteration
        int[][] temp = prev;
        prev = cur;
        cur = temp;

        // Process remaining rows
        for (int i = 1; i < m; i++) {
            // Reset cur array
            for (int j = 0; j < n; j++) {
                Arrays.fill(cur[j], 0);
            }

            for (int j = 0; j < n; j++) {
                valMod = mod(grid[i][j], k);

                // From above (prev row)
                for (int rPrev = 0; rPrev < k; rPrev++) {
                    int cnt = prev[j][rPrev];
                    if (cnt == 0) continue;
                    int r = (rPrev + valMod) % k;
                    cur[j][r] += cnt;
                    if (cur[j][r] >= MOD) cur[j][r] -= MOD;
                }

                // From left (current row)
                if (j > 0) {
                    for (int rPrev = 0; rPrev < k; rPrev++) {
                        int cnt = cur[j - 1][rPrev];
                        if (cnt == 0) continue;
                        int r = (rPrev + valMod) % k;
                        cur[j][r] += cnt;
                        if (cur[j][r] >= MOD) cur[j][r] -= MOD;
                    }
                }
            }

            // Prepare for next row
            temp = prev;
            prev = cur;
            cur = temp;
        }

        return prev[n - 1][0];
    }

    // Helper to compute positive modulo for possibly negative numbers
    private static int mod(int value, int k) {
        int res = value % k;
        if (res < 0) res += k;
        return res;
    }
}

