public class Solution {
    public List<Integer> goodIndices(int[] nums, int k) {
        int n = nums.length;
        List<Integer> result = new ArrayList<>();

        // left[i] = number of consecutive non‑increasing pairs ending at i
        int[] left = new int[n];
        for (int i = 1; i < n; i++) {
            if (nums[i] <= nums[i - 1]) {
                left[i] = left[i - 1] + 1;
            } else {
                left[i] = 0;
            }
        }

        // right[i] = number of consecutive non‑decreasing pairs starting at i
        int[] right = new int[n];
        for (int i = n - 2; i >= 0; i--) {
            if (nums[i] <= nums[i + 1]) {
                right[i] = right[i + 1] + 1;
            } else {
                right[i] = 0;
            }
        }

        for (int i = k; i <= n - k - 1; i++) {
            if (left[i - 1] >= k - 1 && right[i + 1] >= k - 1) {
                result.add(i);
            }
        }

        return result;
    }
}

