import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        if (k > n) return 0;

        @SuppressWarnings("unchecked")
        List<Integer>[] ends = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            ends[i] = new ArrayList<>();
        }

        // Find all palindromic substrings of length >= k
        for (int center = 0; center < n; center++) {
            // odd length palindromes
            int l = center, r = center;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                if (r - l + 1 >= k) {
                    ends[l].add(r);
                }
                l--;
                r++;
            }
            // even length palindromes
            l = center;
            r = center + 1;
            while (l >= 0 && r < n && s.charAt(l) == s.charAt(r)) {
                if (r - l + 1 >= k) {
                    ends[l].add(r);
                }
                l--;
                r++;
            }
        }

        int[] dp = new int[n + 1]; // dp[i] = max number of substrings in prefix [0, i)
        for (int i = 0; i < n; i++) {
            // carry forward the best result up to i
            dp[i + 1] = Math.max(dp[i + 1], dp[i]);

            // try to place a palindrome starting at i
            for (int r : ends[i]) {
                dp[r + 1] = Math.max(dp[r + 1], dp[i] + 1);
            }
        }

        return dp[n];
    }
}

