public class Solution {
    private static final int MOD = 1_000_000_007;

    private static boolean isPrimeDigit(char c) {
        return c == '2' || c == '3' || c == '5' || c == '7';
    }

    private static boolean isNonPrimeDigit(char c) {
        return !isPrimeDigit(c);
    }

    public int beautifulPartitions(String s, int k, int l) {
        int n = s.length();
        if (k == 0) return n == 0 ? 1 : 0;
        if (l > n || k * l > n) return 0;

        int[][] dp = new int[n + 1][k + 1];
        dp[0][0] = 1;

        for (int part = 1; part <= k; part++) {
            // prefixPrimeSum[i] = sum of dp[t][part-1] for t < i and s[t] is prime
            int[] prefixPrimeSum = new int[n + 1];
            for (int idx = 0; idx < n; idx++) {
                prefixPrimeSum[idx + 1] = prefixPrimeSum[idx];
                if (isPrimeDigit(s.charAt(idx))) {
                    prefixPrimeSum[idx + 1] += dp[idx][part - 1];
                    if (prefixPrimeSum[idx + 1] >= MOD) prefixPrimeSum[idx + 1] -= MOD;
                }
            }

            for (int i = 1; i <= n; i++) {
                char endChar = s.charAt(i - 1);
                if (isNonPrimeDigit(endChar) && i >= l) {
                    int limitIndex = i - l + 1; // sum over t <= i-l
                    dp[i][part] = prefixPrimeSum[limitIndex];
                } else {
                    dp[i][part] = 0;
                }
            }
        }

        return dp[n][k];
    }
}

