import java.util.ArrayList;
import java.util.List;

public class Solution {
    public int componentValue(int[] nums, int[][] edges) {
        int n = nums.length;
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int a = e[0], b = e[1];
            adj[a].add(b);
            adj[b].add(a);
        }

        long total = 0;
        for (int v : nums) total += v;

        // If all values are zero, we can delete all edges
        if (total == 0) {
            return n - 1;
        }

        // Find all divisors of total (possible number of components)
        List<Integer> divisors = new ArrayList<>();
        for (long i = 1; i * i <= total; i++) {
            if (total % i == 0) {
                divisors.add((int) i);
                if (i != total / i) {
                    divisors.add((int) (total / i));
                }
            }
        }

        int maxComponents = 1; // at least one component
        for (int k : divisors) {
            long target = total / k;
            int[] count = new int[1];
            long[] subSum = new long[n];
            if (dfs(0, -1, target, adj, nums, subSum, count)) {
                if (count[0] == k) {
                    if (k > maxComponents) {
                        maxComponents = k;
                    }
                }
            }
        }

        return maxComponents - 1; // edges removed = components - 1
    }

    private boolean dfs(int node, int parent, long target, List<Integer>[] adj,
                        int[] nums, long[] subSum, int[] count) {
        long sum = nums[node];
        for (int nb : adj[node]) {
            if (nb == parent) continue;
            if (!dfs(nb, node, target, adj, nums, subSum, count)) {
                return false;
            }
            sum += subSum[nb];
        }
        if (sum == target) {
            count[0]++;
            subSum[node] = 0;
        } else {
            subSum[node] = sum;
        }
        return true;
    }
}

