import java.util.*;

public class Solution {
    public int mostProfitablePath(int[][] edges, int bob, int[] amount) {
        int n = amount.length;
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }

        // Build parent array from root 0
        int[] parent = new int[n];
        Arrays.fill(parent, -1);
        dfsParent(0, -1, graph, parent);

        // Build bobTime only for nodes on path from bob to root
        int[] bobTime = new int[n];
        Arrays.fill(bobTime, -1);
        int cur = bob;
        int time = 0;
        while (cur != -1) {
            bobTime[cur] = time;
            cur = parent[cur];
            time++;
        }

        // DFS from root to leaves to compute maximum income
        return dfsAlice(0, -1, 0, graph, bobTime, amount);
    }

    private void dfsParent(int node, int par, List<Integer>[] graph, int[] parent) {
        parent[node] = par;
        for (int nei : graph[node]) {
            if (nei != par) {
                dfsParent(nei, node, graph, parent);
            }
        }
    }

    private int dfsAlice(int node, int parent, int time, List<Integer>[] graph,
                         int[] bobTime, int[] amount) {
        int income = 0;
        int bobArrival = bobTime[node];

        if (bobArrival == -1 || time < bobArrival) {
            // Alice arrives before Bob or Bob never visits
            income += amount[node];
        } else if (time == bobArrival) {
            // Share the amount
            income += amount[node] / 2;
        } // else time > bobArrival: Bob already opened, no effect

        boolean isLeaf = true;
        int maxChildIncome = Integer.MIN_VALUE;
        for (int nei : graph[node]) {
            if (nei != parent) {
                isLeaf = false;
                int childIncome = dfsAlice(nei, node, time + 1, graph, bobTime, amount);
                if (childIncome > maxChildIncome) {
                    maxChildIncome = childIncome;
                }
            }
        }

        if (isLeaf) {
            return income;
        }
        return income + maxChildIncome;
    }
}

