import java.util.Arrays;
import java.util.Comparator;

public class Solution {
    public long minCost(int[] nums, int[] cost) {
        int n = nums.length;
        // Pair nums and cost
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, Comparator.comparingInt(i -> nums[i]));

        long[] prefix = new long[n];
        long totalWeight = 0;
        for (int i = 0; i < n; i++) {
            int originalIndex = idx[i];
            totalWeight += cost[originalIndex];
            prefix[i] = totalWeight;
        }

        // Find weighted median
        long half = (totalWeight + 1) / 2;
        int medianPos = 0;
        while (medianPos < n && prefix[medianPos] < half) {
            medianPos++;
        }
        int target = nums[idx[medianPos]];

        // Compute total cost
        long result = 0;
        for (int i = 0; i < n; i++) {
            result += (long) cost[i] * Math.abs((long) nums[i] - target);
        }
        return result;
    }
}

