public class Solution {
    public int bestClosingTime(String customers) {
        int n = customers.length();
        int totalY = 0;
        for (int i = 0; i < n; i++) {
            if (customers.charAt(i) == 'Y') totalY++;
        }

        int bestJ = 0;
        int bestPenalty = totalY; // penalty when j = 0

        int penalty = bestPenalty;
        for (int j = 1; j <= n; j++) {
            char c = customers.charAt(j - 1);
            if (c == 'N') {
                penalty += 1; // open side adds a penalty
            } else { // c == 'Y'
                penalty -= 1; // closed side loses a penalty
            }
            if (penalty < bestPenalty) {
                bestPenalty = penalty;
                bestJ = j;
            }
        }
        return bestJ;
    }
}

