import java.util.Arrays;

public class Solution {

    private static class SegTree {
        private final int size;
        private final int[] tree;

        SegTree(int n) {
            size = 1 << (32 - Integer.numberOfLeadingZeros(n - 1));
            tree = new int[size << 1];
        }

        void update(int idx, int val) {
            idx += size;
            tree[idx] = Math.max(tree[idx], val);
            for (idx >>= 1; idx > 0; idx >>= 1) {
                tree[idx] = Math.max(tree[idx << 1], tree[(idx << 1) | 1]);
            }
        }

        int query(int l, int r) {
            if (l > r) return 0;
            l += size;
            r += size;
            int res = 0;
            while (l <= r) {
                if ((l & 1) == 1) res = Math.max(res, tree[l++]);
                if ((r & 1) == 0) res = Math.max(res, tree[r--]);
                l >>= 1;
                r >>= 1;
            }
            return res;
        }
    }

    public int longestSubsequence(int[] nums, int k) {
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
        }
        int[] uniq = Arrays.copyOf(sorted, m);

        SegTree seg = new SegTree(m);
        int answer = 0;

        for (int num : nums) {
            int idx = Arrays.binarySearch(uniq, num);
            int leftVal = num - k;
            int leftIdx = lowerBound(uniq, leftVal);
            int rightIdx = idx - 1; // strictly less than num

            int bestPrev = seg.query(leftIdx, rightIdx);
            int curLen = bestPrev + 1;

            seg.update(idx, curLen);
            answer = Math.max(answer, curLen);
        }

        return answer;
    }

    public int lengthOfLIS(int[] nums, int k) {
        return longestSubsequence(nums, k);
    }

    private int lowerBound(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] < target) l = mid + 1;
            else r = mid;
        }
        return l;
    }
}

