import java.util.*;

public class Solution {
    public int numberOfGoodPaths(int[] vals, int[][] edges) {
        int n = vals.length;
        // Build adjacency list
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        // DSU initialization
        int[] parent = new int[n];
        int[] size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        // Order nodes by value
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, Comparator.comparingInt(i -> vals[i]));

        long result = 0;
        int idx = 0;
        while (idx < n) {
            int currentVal = vals[order[idx]];
            int nextIdx = idx;
            while (nextIdx < n && vals[order[nextIdx]] == currentVal) nextIdx++;

            // Union edges where both ends have value <= currentVal
            for (int i = idx; i < nextIdx; i++) {
                int u = order[i];
                for (int v : adj[u]) {
                    if (vals[v] <= currentVal) {
                        union(u, v, parent, size);
                    }
                }
            }

            // Count nodes with currentVal per component
            Map<Integer, Integer> compCount = new HashMap<>();
            for (int i = idx; i < nextIdx; i++) {
                int u = order[i];
                int root = find(u, parent);
                compCount.put(root, compCount.getOrDefault(root, 0) + 1);
            }

            // Add contributions
            for (int cnt : compCount.values()) {
                result += (long) cnt * (cnt - 1) / 2 + cnt;
            }

            idx = nextIdx;
        }

        return (int) result;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) parent[x] = find(parent[x], parent);
        return parent[x];
    }

    private void union(int a, int b, int[] parent, int[] size) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (size[ra] < size[rb]) {
            int tmp = ra;
            ra = rb;
            rb = tmp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}

