public class Solution {
    public int minimizeXor(int num1, int num2) {
        int k = Integer.bitCount(num2);          // required number of set bits
        int x = 0;
        int count = 0;

        // First, set all bits that are 1 in num1
        for (int i = 0; i < 32; i++) {
            if (((num1 >> i) & 1) == 1) {
                x |= (1 << i);
                count++;
            }
        }

        // If we still need more bits, set the lowest zero bits of num1
        int remaining = k - count;
        if (remaining > 0) {
            for (int i = 0; i < 32 && remaining > 0; i++) {
                if (((num1 >> i) & 1) == 0 && ((x >> i) & 1) == 0) {
                    x |= (1 << i);
                    remaining--;
                }
            }
        }

        return x;
    }
}

