public class Solution {
    public long makeIntegerBeautiful(long n, int target) {
        long original = n;
        while (sumDigits(n) > target) {
            long pow10 = 1;
            while (true) {
                pow10 *= 10;
                if (n % pow10 != 0) {
                    n += pow10 - (n % pow10);
                    break;
                }
            }
        }
        return n - original;
    }

    private long sumDigits(long x) {
        long sum = 0;
        while (x > 0) {
            sum += x % 10;
            x /= 10;
        }
        return sum;
    }
}

