import java.util.Arrays;
import java.util.PriorityQueue;

public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        // Sort meetings by start time
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[0], b[0]));

        // Available rooms sorted by room number
        PriorityQueue<Integer> available = new PriorityQueue<>();

        // Busy rooms sorted by end time, then room number
        PriorityQueue<BusyRoom> busy = new PriorityQueue<>(
                (a, b) -> a.end == b.end ? Integer.compare(a.room, b.room) : Long.compare(a.end, b.end));

        for (int i = 0; i < n; i++) {
            available.offer(i);
        }

        int[] count = new int[n];

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];
            long duration = (long) end - start;

            // Release rooms that have finished before the current meeting starts
            while (!busy.isEmpty() && busy.peek().end <= start) {
                available.offer(busy.poll().room);
            }

            if (!available.isEmpty()) {
                // Assign the lowest-numbered available room
                int room = available.poll();
                busy.offer(new BusyRoom(room, start + duration));
                count[room]++;
            } else {
                // No room available, delay the meeting
                BusyRoom br = busy.poll(); // earliest finishing room
                long newStart = br.end;
                long newEnd = newStart + duration;
                busy.offer(new BusyRoom(br.room, newEnd));
                count[br.room]++;
            }
        }

        // Find the room with the maximum number of meetings
        int maxRoom = 0;
        int maxCount = count[0];
        for (int i = 1; i < n; i++) {
            if (count[i] > maxCount) {
                maxCount = count[i];
                maxRoom = i;
            }
        }
        return maxRoom;
    }

    private static class BusyRoom {
        int room;
        long end;

        BusyRoom(int room, long end) {
            this.room = room;
            this.end = end;
        }
    }
}

