import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int[] productQueries(int n, int[][] queries) {
        int m = Integer.bitCount(n);
        long[] powers = new long[m];
        int idx = 0;
        for (int i = 0; i < 31; i++) {
            if ((n & (1 << i)) != 0) {
                powers[idx++] = 1L << i;
            }
        }

        long[] pref = new long[m];
        pref[0] = powers[0] % MOD;
        for (int i = 1; i < m; i++) {
            pref[i] = (pref[i - 1] * powers[i]) % MOD;
        }

        int q = queries.length;
        int[] ans = new int[q];
        for (int i = 0; i < q; i++) {
            int l = queries[i][0];
            int r = queries[i][1];
            long res;
            if (l == 0) {
                res = pref[r];
            } else {
                long inv = modInverse(pref[l - 1], MOD);
                res = (pref[r] * inv) % MOD;
            }
            ans[i] = (int) res;
        }
        return ans;
    }

    private long modInverse(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }

    private long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

