import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {

    public int magnificentSets(int n, int[][] edges) {
        List<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        for (int[] e : edges) {
            int u = e[0];
            int v = e[1];
            adj[u].add(v);
            adj[v].add(u);
        }

        boolean[] visited = new boolean[n + 1];
        int[] color = new int[n + 1];
        int maxDiameter = 0;

        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                int[] first = bfs(i, adj, visited, color);
                if (first[0] == -1) {
                    return -1;
                }
                int farthest = first[0];
                int diameter = bfsDiameter(farthest, adj);
                if (diameter > maxDiameter) {
                    maxDiameter = diameter;
                }
            }
        }

        return maxDiameter + 1;
    }

    private int[] bfs(int start, List<Integer>[] adj, boolean[] visited, int[] color) {
        Queue<Integer> q = new LinkedList<>();
        q.add(start);
        visited[start] = true;
        color[start] = 0;
        int farthest = start;
        int maxDist = 0;
        int[] dist = new int[adj.length];
        dist[start] = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    color[v] = color[u] ^ 1;
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > maxDist) {
                        maxDist = dist[v];
                        farthest = v;
                    }
                } else {
                    if (color[v] == color[u]) {
                        return new int[]{-1, -1};
                    }
                }
            }
        }
        return new int[]{farthest, maxDist};
    }

    private int bfsDiameter(int start, List<Integer>[] adj) {
        Queue<Integer> q = new LinkedList<>();
        int[] dist = new int[adj.length];
        Arrays.fill(dist, -1);
        q.add(start);
        dist[start] = 0;
        int maxDist = 0;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                    if (dist[v] > maxDist) {
                        maxDist = dist[v];
                    }
                }
            }
        }
        return maxDist;
    }
}

