public class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] firstGreater = new int[n];
        Arrays.fill(firstGreater, -1);
        Deque<Integer> stack = new ArrayDeque<>();

        // Find the first greater element for each index
        for (int i = 0; i < n; i++) {
            while (!stack.isEmpty() && nums[i] > nums[stack.peek()]) {
                firstGreater[stack.pop()] = i;
            }
            stack.push(i);
        }

        // Prepare waiting lists: waiting[k] contains all indices i whose first greater is k
        List<List<Integer>> waiting = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            waiting.add(new ArrayList<>());
        }
        for (int i = 0; i < n; i++) {
            int k = firstGreater[i];
            if (k != -1) {
                waiting.get(k).add(i);
            }
        }

        int[] answer = new int[n];
        Arrays.fill(answer, -1);
        Deque<Integer> secondStack = new ArrayDeque<>();

        // Scan the array to find second greater elements
        for (int j = 0; j < n; j++) {
            // Resolve second greater for indices whose first greater has already been seen
            while (!secondStack.isEmpty() && nums[j] > nums[secondStack.peek()]) {
                int i = secondStack.pop();
                answer[i] = nums[j];
            }
            // Push indices waiting for this position as their first greater
            for (int i : waiting.get(j)) {
                secondStack.push(i);
            }
        }

        return answer;
    }
}

