import java.util.HashMap;
import java.util.Map;

public class Solution {
    public boolean equalFrequency(String word) {
        if (word == null || word.length() == 0) {
            return false;
        }
        if (word.length() == 1) {
            return true;
        }

        int[] freq = new int[26];
        for (char c : word.toCharArray()) {
            freq[c - 'a']++;
        }

        Map<Integer, Integer> freqCount = new HashMap<>();
        for (int f : freq) {
            if (f > 0) {
                freqCount.put(f, freqCount.getOrDefault(f, 0) + 1);
            }
        }

        int distinct = freqCount.size();
        if (distinct == 1) {
            int f = freqCount.keySet().iterator().next();
            return f == 1;
        } else if (distinct == 2) {
            Integer[] keys = freqCount.keySet().toArray(new Integer[0]);
            int f1 = keys[0];
            int f2 = keys[1];
            int c1 = freqCount.get(f1);
            int c2 = freqCount.get(f2);

            // Ensure f1 < f2
            if (f1 > f2) {
                int tmpF = f1; f1 = f2; f2 = tmpF;
                int tmpC = c1; c1 = c2; c2 = tmpC;
            }

            // Case 1: one letter appears once, remove it entirely
            if (f1 == 1 && c1 == 1) {
                return true;
            }
            // Case 2: one letter has frequency one more than others, remove one occurrence
            if (f2 == f1 + 1 && c2 == 1) {
                return true;
            }
            return false;
        } else {
            return false;
        }
    }
}

