import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Returns all words from {@code queries} that can be transformed into
     * some word from {@code dictionary} with at most two single-letter edits.
     *
     * @param queries    array of query words
     * @param dictionary array of dictionary words
     * @return list of matching query words in the original order
     */
    public List<String> twoEditWords(String[] queries, String[] dictionary) {
        return findMatches(queries, dictionary);
    }

    // Internal helper that performs the actual work
    private List<String> findMatches(String[] queries, String[] dictionary) {
        List<String> result = new ArrayList<>();
        if (queries == null || dictionary == null) {
            return result;
        }

        for (String query : queries) {
            if (matchesWithinTwoEdits(query, dictionary)) {
                result.add(query);
            }
        }
        return result;
    }

    // Checks whether the given query word can be transformed into
    // any word from dictionary with at most two edits.
    private boolean matchesWithinTwoEdits(String query, String[] dictionary) {
        for (String dictWord : dictionary) {
            if (hammingDistanceAtMostTwo(query, dictWord)) {
                return true;
            }
        }
        return false;
    }

    // Computes the Hamming distance between two words and returns true
    // if it is less than or equal to 2.
    private boolean hammingDistanceAtMostTwo(String a, String b) {
        int mismatches = 0;
        int len = a.length(); // all words have the same length
        for (int i = 0; i < len; i++) {
            if (a.charAt(i) != b.charAt(i)) {
                mismatches++;
                if (mismatches > 2) {
                    return false;
                }
            }
        }
        return true;
    }
}

