import java.util.*;

public class Solution {
    public String[] splitMessage(String message, int limit) {
        if (message == null) return new String[0];
        int n = message.length();
        // Binary search for minimal b
        int low = 1, high = n + 1; // upper bound
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (canSplit(mid, message, limit)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        if (low > n || !canSplit(low, message, limit)) {
            return new String[0];
        }
        int b = low;
        String[] parts = new String[b];
        int pos = 0;
        for (int i = 1; i <= b; i++) {
            int suffixLen = suffixLength(i, b);
            int maxContent = limit - suffixLen;
            int contentLen;
            if (i < b) {
                contentLen = maxContent;
            } else {
                contentLen = n - pos;
                if (contentLen > maxContent) contentLen = maxContent;
            }
            String part = message.substring(pos, pos + contentLen) + "<" + i + "/" + b + ">";
            parts[i - 1] = part;
            pos += contentLen;
        }
        return parts;
    }

    private boolean canSplit(int b, String message, int limit) {
        int n = message.length();
        long totalMax = 0;
        for (int i = 1; i <= b; i++) {
            int suffixLen = suffixLength(i, b);
            if (suffixLen > limit) return false;
            totalMax += (long)limit - suffixLen;
            if (totalMax >= n) return true; // early exit
        }
        return totalMax >= n;
    }

    private int suffixLength(int a, int b) {
        return 3 + digits(a) + digits(b); // "<" + a + "/" + b + ">"
    }

    private int digits(int x) {
        if (x == 0) return 1;
        int d = 0;
        while (x > 0) {
            d++;
            x /= 10;
        }
        return d;
    }
}

