import java.util.*;

public class Solution {
    public int subarrayLCM(int[] nums, int k) {
        if (k <= 0) return 0; // LCM defined for positive integers

        // Special case when k == 1
        if (k == 1) {
            int ans = 0;
            int len = 0;
            for (int v : nums) {
                if (v == 1) {
                    len++;
                } else {
                    ans += len * (len + 1) / 2;
                    len = 0;
                }
            }
            ans += len * (len + 1) / 2;
            return ans;
        }

        // Factorize k
        List<Integer> primes = new ArrayList<>();
        List<Integer> reqExp = new ArrayList<>();
        int temp = k;
        for (int p = 2; p * p <= temp; p++) {
            if (temp % p == 0) {
                int cnt = 0;
                while (temp % p == 0) {
                    temp /= p;
                    cnt++;
                }
                primes.add(p);
                reqExp.add(cnt);
            }
        }
        if (temp > 1) {
            primes.add(temp);
            reqExp.add(1);
        }
        int m = primes.size();
        int[] lastReq = new int[m];
        Arrays.fill(lastReq, -1);

        int ans = 0;
        int segmentStart = 0;

        for (int i = 0; i < nums.length; i++) {
            int val = nums[i];
            if (k % val != 0) { // element does not divide k, reset segment
                segmentStart = i + 1;
                Arrays.fill(lastReq, -1);
                continue;
            }

            // Update exponents for each prime
            for (int j = 0; j < m; j++) {
                int p = primes.get(j);
                int cnt = 0;
                int tmp = val;
                while (tmp % p == 0) {
                    tmp /= p;
                    cnt++;
                }
                if (cnt == reqExp.get(j)) {
                    lastReq[j] = i;
                }
            }

            // Check if all required exponents have been seen in current segment
            boolean allSeen = true;
            int minLast = Integer.MAX_VALUE;
            for (int j = 0; j < m; j++) {
                if (lastReq[j] < segmentStart) {
                    allSeen = false;
                    break;
                }
                if (lastReq[j] < minLast) minLast = lastReq[j];
            }
            if (allSeen) {
                ans += minLast - segmentStart + 1;
            }
        }

        return ans;
    }
}

