public class Solution {
    public int commonFactors(int a, int b) {
        int gcd = computeGCD(a, b);
        int count = 0;
        for (int i = 1; i * i <= gcd; i++) {
            if (gcd % i == 0) {
                if (i * i == gcd) {
                    count++;
                } else {
                    count += 2;
                }
            }
        }
        return count;
    }

    private int computeGCD(int x, int y) {
        while (y != 0) {
            int temp = x % y;
            x = y;
            y = temp;
        }
        return x;
    }
}

