public class Solution {
    private static final int MOD = 1_000_000_007;

    public int countGoodStrings(int low, int high, int zero, int one) {
        int[] dp = new int[high + 1];
        dp[0] = 1;
        for (int i = 1; i <= high; i++) {
            long val = 0;
            if (i - zero >= 0) {
                val += dp[i - zero];
            }
            if (i - one >= 0) {
                val += dp[i - one];
            }
            dp[i] = (int) (val % MOD);
        }
        long ans = 0;
        for (int i = low; i <= high; i++) {
            ans += dp[i];
        }
        return (int) (ans % MOD);
    }
}

