public class Solution {
    public String robotWithString(String s) {
        int n = s.length();
        char[] minRemaining = new char[n + 1];
        minRemaining[n] = Character.MAX_VALUE; // sentinel larger than any character
        for (int i = n - 1; i >= 0; i--) {
            minRemaining[i] = (char) Math.min(s.charAt(i), minRemaining[i + 1]);
        }

        Stack<Character> stack = new Stack<>();
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < n; i++) {
            stack.push(s.charAt(i));
            while (!stack.isEmpty() && stack.peek() <= minRemaining[i + 1]) {
                result.append(stack.pop());
            }
        }

        while (!stack.isEmpty()) {
            result.append(stack.pop());
        }

        return result.toString();
    }
}

