import java.util.PriorityQueue;
import java.util.Collections;

public class Solution {
    public int minimumDeviation(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        int n = nums.length;
        // Max-heap to keep track of current maximum
        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        int minVal = Integer.MAX_VALUE;

        // Preprocess: make all numbers even by multiplying odds by 2
        for (int num : nums) {
            if ((num & 1) == 1) { // odd
                num <<= 1; // multiply by 2
            }
            maxHeap.offer(num);
            if (num < minVal) minVal = num;
        }

        int bestDeviation = Integer.MAX_VALUE;

        while (!maxHeap.isEmpty()) {
            int currentMax = maxHeap.poll();
            // Update best deviation
            bestDeviation = Math.min(bestDeviation, currentMax - minVal);

            // If current max is odd, we cannot divide further; break
            if ((currentMax & 1) == 1) {
                break;
            }

            // Divide the current max by 2 and push back
            int newVal = currentMax >> 1;
            maxHeap.offer(newVal);
            if (newVal < minVal) {
                minVal = newVal;
            }
        }

        return bestDeviation;
    }
}

