public class Solution {

    public static class ListNode {
        int val;
        ListNode next;
        ListNode(int val) {
            this.val = val;
        }
    }

    public ListNode removeNodes(ListNode head) {
        if (head == null) return null;

        // Push all nodes onto a stack to process from right to left
        Deque<ListNode> stack = new ArrayDeque<>();
        ListNode current = head;
        while (current != null) {
            stack.push(current);
            current = current.next;
        }

        ListNode newHead = null;
        int maxVal = Integer.MIN_VALUE;

        // Build the resulting list by popping from the stack
        while (!stack.isEmpty()) {
            ListNode node = stack.pop();
            if (node.val >= maxVal) {
                maxVal = node.val;
                node.next = newHead;
                newHead = node;
            }
        }

        return newHead;
    }
}

