import java.util.HashMap;
import java.util.Map;

public class Solution {
    private int m, n, introvertsCount, extrovertsCount;
    private int states;
    private int[] pow3;
    private int[][] types;          // types[state][col] : 0 none, 1 intro, 2 extro
    private int[] introCnt;         // number of introverts in state
    private int[] extroCnt;         // number of extroverts in state
    private int[] baseHappiness;    // base happiness of state (without neighbor effects)
    private int[] leftEffect;       // effect of left neighbors within the same row
    private int[][] verticalEffect; // effect between prev row and current row
    private Map<Long, Integer> memo;

    public int getMaxGridHappiness(int m, int n, int introvertsCount, int extrovertsCount) {
        this.m = m;
        this.n = n;
        this.introvertsCount = introvertsCount;
        this.extrovertsCount = extrovertsCount;

        pow3 = new int[n];
        pow3[0] = 1;
        for (int i = 1; i < n; i++) pow3[i] = pow3[i - 1] * 3;
        states = pow3[n - 1] * 3; // 3^n

        types = new int[states][n];
        introCnt = new int[states];
        extroCnt = new int[states];
        baseHappiness = new int[states];
        leftEffect = new int[states];
        verticalEffect = new int[states][states];

        precomputeStates();
        memo = new HashMap<>();
        return dfs(0, 0, 0, 0);
    }

    private void precomputeStates() {
        for (int s = 0; s < states; s++) {
            int tmp = s;
            int intro = 0, extro = 0, base = 0, left = 0;
            for (int col = 0; col < n; col++) {
                int t = tmp % 3;
                types[s][col] = t;
                if (t == 1) {
                    intro++;
                    base += 120;
                } else if (t == 2) {
                    extro++;
                    base += 40;
                }
                tmp /= 3;
            }
            introCnt[s] = intro;
            extroCnt[s] = extro;
            baseHappiness[s] = base;

            // left neighbor effect within the same row
            for (int col = 1; col < n; col++) {
                int t1 = types[s][col];
                int t0 = types[s][col - 1];
                if (t1 != 0 && t0 != 0) {
                    left += pairEffect(t1, t0);
                }
            }
            leftEffect[s] = left;
        }

        // vertical effects between two rows
        for (int prev = 0; prev < states; prev++) {
            for (int cur = 0; cur < states; cur++) {
                int sum = 0;
                for (int col = 0; col < n; col++) {
                    int t1 = types[prev][col];
                    int t2 = types[cur][col];
                    if (t1 != 0 && t2 != 0) {
                        sum += pairEffect(t1, t2);
                    }
                }
                verticalEffect[prev][cur] = sum;
            }
        }
    }

    // pairEffect returns net happiness change for a pair of adjacent people
    private int pairEffect(int a, int b) {
        if (a == 1 && b == 1) return -60;   // intro + intro
        if (a == 2 && b == 2) return 40;    // extro + extro
        // intro + extro or extro + intro
        return -10;
    }

    private int dfs(int row, int prevState, int usedIntro, int usedExtro) {
        if (row == m) return 0;
        long key = (((long) row) << 48) | (((long) prevState) << 32) | (((long) usedIntro) << 16) | usedExtro;
        Integer cached = memo.get(key);
        if (cached != null) return cached;

        int best = 0;
        for (int cur = 0; cur < states; cur++) {
            int intro = introCnt[cur];
            int extro = extroCnt[cur];
            if (usedIntro + intro > introvertsCount || usedExtro + extro > extrovertsCount) continue;

            int happiness = baseHappiness[cur] + leftEffect[cur] + verticalEffect[prevState][cur];
            int next = dfs(row + 1, cur, usedIntro + intro, usedExtro + extro);
            best = Math.max(best, happiness + next);
        }
        memo.put(key, best);
        return best;
    }
}

