import java.util.Arrays;

public class Solution {
    public String getSmallestString(int n, int k) {
        // Start with all 'a's which gives the minimal numeric value n
        char[] result = new char[n];
        Arrays.fill(result, 'a');

        int remaining = k - n; // extra value we need to distribute

        // Distribute the remaining value from the end to keep the string lexicographically smallest
        for (int i = n - 1; i >= 0 && remaining > 0; i--) {
            int add = Math.min(25, remaining); // each position can increase by at most 25 (from 'a' to 'z')
            result[i] = (char) ('a' + add);
            remaining -= add;
        }

        return new String(result);
    }
}

