import java.util.*;

public class Solution {
    public boolean canDistribute(int[] nums, int[] quantity) {
        // Count frequencies of each unique number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        // Convert frequencies to array
        int[] counts = new int[freqMap.size()];
        int idx = 0;
        for (int val : freqMap.values()) {
            counts[idx++] = val;
        }

        // Filter out zero quantities and sort descending
        List<Integer> qtyList = new ArrayList<>();
        for (int q : quantity) {
            if (q > 0) qtyList.add(q);
        }
        if (qtyList.isEmpty()) return true; // all customers need 0 items

        Collections.sort(qtyList, Collections.reverseOrder());
        int[] qty = qtyList.stream().mapToInt(Integer::intValue).toArray();

        // Quick feasibility checks
        int totalNeeded = 0;
        for (int q : qty) totalNeeded += q;
        int totalAvailable = 0;
        for (int c : counts) totalAvailable += c;
        if (totalNeeded > totalAvailable) return false;

        // If any single quantity exceeds the largest count, impossible
        int maxCount = Arrays.stream(counts).max().orElse(0);
        if (qty[0] > maxCount) return false;

        // Memoization map
        Map<String, Boolean> memo = new HashMap<>();

        return dfs(0, counts, qty, memo);
    }

    private boolean dfs(int idx, int[] counts, int[] qty, Map<String, Boolean> memo) {
        if (idx == qty.length) return true;

        // Generate key for memoization
        String key = generateKey(counts);
        if (memo.containsKey(key)) return memo.get(key);

        int need = qty[idx];
        // Try to assign this customer to any value with enough remaining
        for (int i = 0; i < counts.length; i++) {
            if (counts[i] >= need) {
                counts[i] -= need;
                if (dfs(idx + 1, counts, qty, memo)) {
                    counts[i] += need; // backtrack before returning
                    memo.put(key, true);
                    return true;
                }
                counts[i] += need; // backtrack
            }
        }

        memo.put(key, false);
        return false;
    }

    private String generateKey(int[] counts) {
        // Sort counts descending to canonicalize state
        int[] copy = counts.clone();
        Arrays.sort(copy);
        StringBuilder sb = new StringBuilder();
        for (int i = copy.length - 1; i >= 0; i--) {
            sb.append(copy[i]).append(',');
        }
        return sb.toString();
    }
}

