public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;

        // Prefix sums for weights
        long[] weightPref = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            weightPref[i] = weightPref[i - 1] + boxes[i - 1][1];
        }

        // Prefix array for port changes
        int[] portChangePref = new int[n + 1];
        portChangePref[0] = 0;
        for (int i = 1; i <= n; i++) {
