                portChangePref[i] = 0;
            } else {
                portChangePref[i] = portChangePref[i - 1] + (boxes[i - 1][0] != boxes[i - 2][0] ? 1 : 0);
            }
        }

        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = i - 1; j >= 0; j--) {
                int boxCount = i - j;
                if (boxCount > maxBoxes) break;
                long weightSum = weightPref[i] - weightPref[j];
                if (weightSum > maxWeight) break;

                int changes = portChangePref[i] - portChangePref[j + 1];
                int cost = dp[j] + changes + 2; // +1 for first port trip, +1 for return to storage
                if (cost < dp[i]) dp[i] = cost;
            }
        }

        return dp[n];
    }
}

