import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    public int minimumIncompatibility(int[] nums, int k) {
        int n = nums.length;
        if (n % k != 0) return -1;
        int subsetSize = n / k;

        // Check if any number appears more than k times
        int[] freq = new int[101]; // nums[i] <= 100
        for (int num : nums) {
            if (++freq[num] > k) return -1;
        }

        int totalMasks = 1 << n;
        int[] incompat = new int[totalMasks];
        boolean[] valid = new boolean[totalMasks];
        List<Integer> validMasks = new ArrayList<>();

        // Precompute valid subsets and their incompatibility
        for (int mask = 0; mask < totalMasks; mask++) {
            if (Integer.bitCount(mask) != subsetSize) continue;
            boolean[] seen = new boolean[101];
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    int val = nums[i];
                    if (seen[val]) {
                        ok = false;
                        break;
                    }
                    seen[val] = true;
                    if (val < min) min = val;
                    if (val > max) max = val;
                }
            }
            if (ok) {
                valid[mask] = true;
                incompat[mask] = max - min;
                validMasks.add(mask);
            }
        }

        int fullMask = totalMasks - 1;
        int INF = Integer.MAX_VALUE / 2;
        int[] dp = new int[totalMasks];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int mask = 0; mask <= fullMask; mask++) {
            if (dp[mask] == INF) continue;
            int remaining = fullMask ^ mask;
            for (int sub : validMasks) {
                if ((sub & mask) != 0) continue; // already used
                if ((sub & remaining) != sub) continue; // not subset of remaining
                int newMask = mask | sub;
                int newVal = dp[mask] + incompat[sub];
                if (newVal < dp[newMask]) dp[newMask] = newVal;
            }
        }

        return dp[fullMask] == INF ? -1 : dp[fullMask];
    }
}

