public class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int[] stack = new int[k];
        int top = 0; // number of elements in stack

        for (int i = 0; i < nums.length; i++) {
            int remaining = nums.length - i; // elements left including current
            while (top > 0 && stack[top - 1] > nums[i] && (top - 1 + remaining) >= k) {
                top--; // pop
            }
            if (top < k) {
                stack[top++] = nums[i];
            }
        }

        // stack already contains the answer of size k
        return stack;
    }
}

