import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int createSortedArray(int[] instructions) {
        int n = instructions.length;
        // Coordinate compression
        int[] sorted = instructions.clone();
        Arrays.sort(sorted);
        int m = 0;
        int prev = Integer.MIN_VALUE;
        for (int val : sorted) {
            if (val != prev) {
                sorted[m++] = val;
                prev = val;
            }
        }
        int[] uniq = Arrays.copyOf(sorted, m);
        Map<Integer, Integer> idxMap = new HashMap<>(m * 2);
        for (int i = 0; i < m; i++) {
            idxMap.put(uniq[i], i + 1); // 1-based index for BIT
        }

        BIT bit = new BIT(m);
        long result = 0;
        for (int i = 0; i < n; i++) {
            int idx = idxMap.get(instructions[i]);
            long left = bit.sum(idx - 1);          // elements < current
            long right = i - bit.sum(idx);         // elements > current (exclude equals)
            result += Math.min(left, right);
            result %= MOD;
            bit.add(idx, 1);
        }
        return (int) result;
    }

    // Binary Indexed Tree (Fenwick Tree)
    private static class BIT {
        private final int size;
        private final int[] tree;

        BIT(int size) {
            this.size = size;
            this.tree = new int[size + 2];
        }

        void add(int idx, int delta) {
            for (int i = idx; i <= size; i += i & -i) {
                tree[i] += delta;
            }
        }

        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) {
                res += tree[i];
            }
            return res;
        }
    }
}

