public class Solution {
    public boolean canFormArray(int[] arr, int[][] pieces) {
        // Map each piece's first element to the piece itself
        Map<Integer, int[]> map = new HashMap<>();
        for (int[] piece : pieces) {
            if (piece.length > 0) {
                map.put(piece[0], piece);
            }
        }

        int i = 0;
        while (i < arr.length) {
            int current = arr[i];
            int[] piece = map.get(current);
            if (piece == null) {
                return false; // No piece starts with this element
            }
            // Verify that the entire piece matches the segment of arr
            for (int j = 0; j < piece.length; j++) {
                if (i + j >= arr.length || arr[i + j] != piece[j]) {
                    return false;
                }
            }
            i += piece.length; // Move index past this piece
        }
        return true;
    }
}

