public class Solution {
    public int countSubstrings(String s, String t) {
        int n = s.length();
        int m = t.length();
        int[][] lcp = new int[n + 1][m + 1];

        // Compute longest common prefix lengths for all pairs (i, j)
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (s.charAt(i) == t.charAt(j)) {
                    lcp[i][j] = 1 + lcp[i + 1][j + 1];
                }
            }
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int common = lcp[i][j];
                int maxLen = Math.min(n - i, m - j);
                if (common < maxLen) { // there is a mismatched character
                    int suffix = 0;
                    if (i + common + 1 <= n && j + common + 1 <= m) {
                        suffix = lcp[i + common + 1][j + common + 1];
                    }
                    ans += suffix + 1; // all lengths from common+1 to common+1+suffix
                }
            }
        }
        return ans;
    }
}

