public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int r = destination[0];
        int c = destination[1];
        long K = k; // use long for safety
        int n = r + c;
        long INF = K + 1; // any value > k

        // Precompute binomial coefficients up to n, capped at INF
        long[][] comb = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            comb[i][0] = comb[i][i] = 1;
            for (int j = 1; j < i; j++) {
                long val = comb[i - 1][j - 1] + comb[i - 1][j];
                if (val > INF) val = INF;
                comb[i][j] = val;
            }
        }

        StringBuilder sb = new StringBuilder();
        while (r > 0 || c > 0) {
            if (c == 0) { // only V left
                sb.append('V');
                r--;
                continue;
            }
            if (r == 0) { // only H left
                sb.append('H');
                c--;
                continue;
            }
            long count = comb[r + c - 1][r]; // number of strings starting with 'H'
            if (K <= count) {
                sb.append('H');
                c--;
            } else {
                sb.append('V');
                K -= count;
                r--;
            }
        }
        return sb.toString();
    }
}

