import java.util.*;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] ans = new int[m][n];
        int[] rowRank = new int[m];
        int[] colRank = new int[n];

        // Group positions by value
        TreeMap<Integer, List<int[]>> valueMap = new TreeMap<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                valueMap.computeIfAbsent(matrix[i][j], k -> new ArrayList<>()).add(new int[]{i, j});
            }
        }

        for (Map.Entry<Integer, List<int[]>> entry : valueMap.entrySet()) {
            List<int[]> positions = entry.getValue();
            int sz = positions.size();

            // DSU for positions of the same value
            int[] parent = new int[sz];
            int[] rankUF = new int[sz];
            for (int i = 0; i < sz; i++) parent[i] = i;

            Map<Integer, Integer> rowMap = new HashMap<>();
            Map<Integer, Integer> colMap = new HashMap<>();

            for (int i = 0; i < sz; i++) {
                int r = positions.get(i)[0];
                int c = positions.get(i)[1];
                if (rowMap.containsKey(r)) union(i, rowMap.get(r), parent, rankUF);
                else rowMap.put(r, i);
                if (colMap.containsKey(c)) union(i, colMap.get(c), parent, rankUF);
                else colMap.put(c, i);
            }

            // Determine rank for each component
            Map<Integer, Integer> compRank = new HashMap<>();
            for (int i = 0; i < sz; i++) {
                int root = find(i, parent);
                int r = positions.get(i)[0];
                int c = positions.get(i)[1];
                int rank = Math.max(rowRank[r], colRank[c]) + 1;
                compRank.merge(root, rank, Math::max);
            }

            // Assign ranks and update row/col ranks
            for (int i = 0; i < sz; i++) {
                int root = find(i, parent);
                int rank = compRank.get(root);
                int r = positions.get(i)[0];
                int c = positions.get(i)[1];
                ans[r][c] = rank;
                rowRank[r] = rank;
                colRank[c] = rank;
            }
        }

        return ans;
    }

    private int find(int x, int[] parent) {
        if (parent[x] != x) parent[x] = find(parent[x], parent);
        return parent[x];
    }

    private void union(int a, int b, int[] parent, int[] rankUF) {
        int ra = find(a, parent);
        int rb = find(b, parent);
        if (ra == rb) return;
        if (rankUF[ra] < rankUF[rb]) {
            parent[ra] = rb;
        } else if (rankUF[ra] > rankUF[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rankUF[ra]++;
        }
    }
}

