import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int[] frequencySort(int[] nums) {
        if (nums == null || nums.length == 0) {
            return nums;
        }

        // Count frequencies
        Map<Integer, Integer> freq = new HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }

        // Sort unique values by frequency ascending, then by value descending
        List<Integer> unique = new ArrayList<>(freq.keySet());
        Collections.sort(unique, (a, b) -> {
            int fa = freq.get(a);
            int fb = freq.get(b);
            if (fa != fb) {
                return Integer.compare(fa, fb); // ascending frequency
            }
            return Integer.compare(b, a); // descending value
        });

        // Build result array
        int[] result = new int[nums.length];
        int idx = 0;
        for (int val : unique) {
            int count = freq.get(val);
            for (int i = 0; i < count; i++) {
                result[idx++] = val;
            }
        }

        return result;
    }
}

