import java.util.ArrayList;
import java.util.List;

public class Solution {
    // Disjoint Set Union (Union-Find) implementation
    private static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]); // path compression
            }
            return parent[x];
        }

        void union(int a, int b) {
            int pa = find(a);
            int pb = find(b);
            if (pa == pb) return;
            // union by size
            if (size[pa] < size[pb]) {
                int tmp = pa;
                pa = pb;
                pb = tmp;
            }
            parent[pb] = pa;
            size[pa] += size[pb];
        }
    }

    public List<Boolean> areConnected(int n, int threshold, int[][] queries) {
        List<Boolean> result = new ArrayList<>(queries.length);

        // Special cases
        if (threshold >= n) {
            // No divisor > threshold exists for any pair
            for (int[] q : queries) {
                result.add(q[0] == q[1]); // only same city is connected
            }
            return result;
        }

        if (threshold <= 0) {
            // Divisor 1 > threshold, all cities connected
            for (int[] q : queries) {
                result.add(true);
            }
            return result;
        }

        DSU dsu = new DSU(n);

        // For each divisor d > threshold, union all its multiples
        for (int d = threshold + 1; d <= n; d++) {
            // Find first multiple of d (which is d itself)
            for (int multiple = d * 2; multiple <= n; multiple += d) {
                dsu.union(d, multiple);
            }
        }

        for (int[] q : queries) {
            int a = q[0];
            int b = q[1];
            result.add(dsu.find(a) == dsu.find(b));
        }

        return result;
    }
}

