import java.util.ArrayDeque;
import java.util.Arrays;

public class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        if (n <= 1) return new int[0];
        int N = n;
        int[] adjMask = new int[N];
        for (int[] e : edges) {
            int u = e[0] - 1;
            int v = e[1] - 1;
            adjMask[u] |= 1 << v;
            adjMask[v] |= 1 << u;
        }

        // Precompute all-pairs shortest distances
        int[][] dist = new int[N][N];
        for (int i = 0; i < N; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
            ArrayDeque<Integer> q = new ArrayDeque<>();
            dist[i][i] = 0;
            q.add(i);
            while (!q.isEmpty()) {
                int u = q.poll();
                int d = dist[i][u];
                int neighbors = adjMask[u];
                while (neighbors != 0) {
                    int v = Integer.numberOfTrailingZeros(neighbors);
                    neighbors &= neighbors - 1;
                    if (dist[i][v] == Integer.MAX_VALUE) {
                        dist[i][v] = d + 1;
                        q.add(v);
                    }
                }
            }
        }

        int totalMasks = 1 << N;
        int[] ans = new int[N - 1];

        for (int mask = 1; mask < totalMasks; mask++) {
            // Check connectivity
            int first = Integer.numberOfTrailingZeros(mask);
            ArrayDeque<Integer> stack = new ArrayDeque<>();
            stack.add(first);
            int visited = 0;
            while (!stack.isEmpty()) {
                int u = stack.poll();
                if ((visited & (1 << u)) != 0) continue;
                visited |= 1 << u;
                int neighbors = adjMask[u] & mask;
                while (neighbors != 0) {
                    int v = Integer.numberOfTrailingZeros(neighbors);
                    neighbors &= neighbors - 1;
                    if ((visited & (1 << v)) == 0) {
                        stack.add(v);
                    }
                }
            }
            if (visited != mask) continue; // not connected

            // Compute diameter
            int maxDist = 0;
            for (int u = 0; u < N; u++) {
                if ((mask & (1 << u)) == 0) continue;
                for (int v = u + 1; v < N; v++) {
                    if ((mask & (1 << v)) == 0) continue;
                    int d = dist[u][v];
                    if (d > maxDist) maxDist = d;
                }
            }
            if (maxDist >= 1) {
                ans[maxDist - 1]++; // diameter d corresponds to index d-1
            }
        }

        return ans;
    }
}

