            return null;
        }
        ListNode head = new ListNode(arr[0]);
        ListNode cur = head;
        for (int i = 1; i < arr.length; i++) {
            cur.next = new ListNode(arr[i]);
            cur = cur.next;
        }
        return head;
    }

    /** Converts a linked list to a List of Integer values. */
    public static List<Integer> toList(ListNode head) {
        List<Integer> result = new ArrayList<>();
        while (head != null) {
            result.add(head.val);
            head = head.next;
        }
        return result;
    }
}

/** Solution class containing the mergeInBetween method. */
public class Solution {

    /**
     * Replaces the nodes from index a to index b (inclusive) in list1 with list2.
     *
     * @param list1 the original list
     * @param a     start index (0‑based)
     * @param b     end index (0‑based)
     * @param list2 the list to insert
     * @return the head of the modified list
     */
    public ListNode mergeInBetween(ListNode list1, int a, int b, ListNode list2) {
        // Dummy node to simplify edge cases
        ListNode dummy = new ListNode(0, list1);

        // Find node just before position a
        ListNode prevA = dummy;
        for (int i = 0; i < a; i++) {
            if (prevA == null) {
                return null; // safety check
            }
            prevA = prevA.next;
        }

        // Find node just after position b
        ListNode afterB = prevA;
        // We need to move (b - a + 1) steps to reach the node after b
        for (int i = 0; i <= b - a + 1; i++) {
            if (afterB == null) {
                break;
            }
            afterB = afterB.next;
        }

        // Connect prevA to the head of list2
        prevA.next = list2;

        // Find the tail of list2
        ListNode tail = list2;
        while (tail != null && tail.next != null) {
            tail = tail.next;
        }

        // Connect the tail of list2 to afterB
        if (tail != null) {
            tail.next = afterB;
        }

        return dummy.next;
    }
}

