import java.util.*;

public class Solution {
    private static final int MOD = 1_000_000_007;

    public int numWays(String[] words, String target) {
        int m = words.length;
        if (m == 0) return 0;
        int n = words[0].length();
        int tLen = target.length();
        if (tLen == 0) return 1;
        if (tLen > n) return 0; // impossible to form longer target

        // Precompute counts of each letter at each column
        int[][] colCount = new int[n][26];
        for (String w : words) {
            for (int j = 0; j < n; j++) {
                char c = w.charAt(j);
                colCount[j][c - 'a']++;
            }
        }

        int[] dp = new int[tLen + 1];
        dp[tLen] = 1; // base case: empty suffix

        for (int col = 0; col < n; col++) {
            int[] next = dp.clone(); // copy current state
            for (int pos = tLen - 1; pos >= 0; pos--) {
                int cnt = colCount[col][target.charAt(pos) - 'a'];
                if (cnt > 0) {
                    long add = (long) cnt * dp[pos + 1] % MOD;
                    next[pos] = (int) ((next[pos] + add) % MOD);
                }
            }
            dp = next;
        }

        return dp[0];
    }
}

