import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        int same = 0;
        List<Double> angles = new ArrayList<>();

        int px = location.get(0);
        int py = location.get(1);

        for (List<Integer> p : points) {
            int x = p.get(0);
            int y = p.get(1);
            if (x == px && y == py) {
                same++;
                continue;
            }
            double ang = Math.toDegrees(Math.atan2(y - py, x - px));
            if (ang < 0) ang += 360.0;
            angles.add(ang);
        }

        if (angles.isEmpty()) return same;

        Collections.sort(angles);
        int m = angles.size();
        for (int i = 0; i < m; i++) {
            angles.add(angles.get(i) + 360.0);
        }

        int max = 0;
        int j = 0;
        double eps = 1e-9;
        for (int i = 0; i < m; i++) {
            while (j < angles.size() && angles.get(j) - angles.get(i) <= angle + eps) {
                j++;
            }
            max = Math.max(max, j - i);
        }

        return max + same;
    }
}

