import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;

public class Solution {

    /**
     * Returns the lexicographically smallest string obtainable by repeatedly
     * applying the two allowed operations on the input string {@code s}.
     *
     * @param s the original string of even length consisting of digits '0'–'9'
     * @param a the value to add to all characters at odd indices (0‑based)
     * @param b the number of positions to rotate the string to the right
     * @return the lexicographically smallest string reachable
     */
    public String findLexSmallestString(String s, int a, int b) {
        int n = s.length();

        // Normalize rotation amount to the range [0, n-1]
        b = ((b % n) + n) % n;

        String start = s;
        Queue<String> queue = new LinkedList<>();
        HashSet<String> visited = new HashSet<>();

        queue.add(start);
        visited.add(start);
        String best = start;

        while (!queue.isEmpty()) {
            String cur = queue.poll();

            if (cur.compareTo(best) < 0) {
                best = cur;
            }

            // Operation 1: add a to all odd indices
            StringBuilder sbAdd = new StringBuilder(cur);
            for (int i = 1; i < n; i += 2) {
                char c = sbAdd.charAt(i);
                int digit = c - '0';
                digit = (digit + a) % 10;
                if (digit < 0) {
                    digit += 10;
                }
                sbAdd.setCharAt(i, (char) ('0' + digit));
            }
            String nextAdd = sbAdd.toString();
            if (visited.add(nextAdd)) {
                queue.add(nextAdd);
            }

            // Operation 2: rotate right by b positions
            if (b != 0) {
                String nextRot = cur.substring(n - b) + cur.substring(0, n - b);
                if (visited.add(nextRot)) {
                    queue.add(nextRot);
                }
            }
        }

        return best;
    }
}

