public class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] result = new int[n];
        if (k == 0) {
            return result; // all zeros
        }
        if (k > 0) {
            for (int i = 0; i < n; i++) {
                int sum = 0;
                for (int j = 1; j <= k; j++) {
                    sum += code[(i + j) % n];
                }
                result[i] = sum;
            }
        } else { // k < 0
            int m = -k;
            for (int i = 0; i < n; i++) {
                int sum = 0;
                for (int j = 1; j <= m; j++) {
                    sum += code[(i - j + n) % n];
                }
                result[i] = sum;
            }
        }
        return result;
    }
}

