import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public int minimumJumps(int[] forbidden, int a, int b, int x) {
        if (x == 0) {
            return 0;
        }

        Set<Integer> forbiddenSet = new HashSet<>();
        int maxForbidden = 0;
        for (int f : forbidden) {
            forbiddenSet.add(f);
            if (f > maxForbidden) {
                maxForbidden = f;
            }
        }

        // If the target itself is forbidden, it's impossible.
        if (forbiddenSet.contains(x)) {
            return -1;
        }

        int limit = Math.max(x, maxForbidden) + a + b;

        Set<String> visited = new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();
        // state: position, lastWasBackward (0 = false, 1 = true)
        queue.offer(new int[]{0, 0});
        visited.add("0#0");

        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] cur = queue.poll();
                int pos = cur[0];
                int lastBack = cur[1];

                if (pos == x) {
                    return steps;
                }

                // Jump forward
                int nextPos = pos + a;
                if (nextPos <= limit && !forbiddenSet.contains(nextPos)) {
                    String key = nextPos + "#0";
                    if (!visited.contains(key)) {
                        visited.add(key);
                        queue.offer(new int[]{nextPos, 0});
                    }
                }

                // Jump backward (only if last jump was not backward)
                if (lastBack == 0) {
                    int nextPos2 = pos - b;
                    if (nextPos2 >= 0 && !forbiddenSet.contains(nextPos2)) {
                        String key = nextPos2 + "#1";
                        if (!visited.contains(key)) {
                            visited.add(key);
                            queue.offer(new int[]{nextPos2, 1});
                        }
                    }
                }
            }
            steps++;
        }

        return -1;
    }
}

