public class Solution {
    public int waysToMakeFair(int[] nums) {
        int n = nums.length;
        // Prefix sums for even and odd indices
        long[] prefixEven = new long[n + 1];
        long[] prefixOdd = new long[n + 1];
        for (int i = 0; i < n; i++) {
            if ((i & 1) == 0) { // even index
                prefixEven[i + 1] = prefixEven[i] + nums[i];
                prefixOdd[i + 1] = prefixOdd[i];
            } else { // odd index
                prefixOdd[i + 1] = prefixOdd[i] + nums[i];
                prefixEven[i + 1] = prefixEven[i];
            }
        }

        // Suffix sums for even and odd indices
        long[] suffixEven = new long[n + 1];
        long[] suffixOdd = new long[n + 1];
        for (int i = n - 1; i >= 0; i--) {
            if ((i & 1) == 0) { // even index
                suffixEven[i] = suffixEven[i + 1] + nums[i];
                suffixOdd[i] = suffixOdd[i + 1];
            } else { // odd index
                suffixOdd[i] = suffixOdd[i + 1] + nums[i];
                suffixEven[i] = suffixEven[i + 1];
            }
        }

        int count = 0;
        for (int i = 0; i < n; i++) {
            long newEven = prefixEven[i] + suffixOdd[i + 1];
            long newOdd = prefixOdd[i] + suffixEven[i + 1];
            if (newEven == newOdd) {
                count++;
            }
        }
        return count;
    }
}

