public class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        // Count the number of students preferring each sandwich type
        int[] prefCount = new int[2];
        for (int s : students) {
            prefCount[s]++;
        }

        // Process the sandwiches stack
        for (int sandwich : sandwiches) {
            if (prefCount[sandwich] > 0) {
                prefCount[sandwich]--; // a student takes this sandwich
            } else {
                // No student wants this sandwich, so the process stops
                break;
            }
        }

        // The remaining students are those who couldn't eat
        return prefCount[0] + prefCount[1];
    }
}

