import java.util.*;

public class Solution {
    public int minimumMountainRemovals(int[] nums) {
        int n = nums.length;
        if (n < 3) return -1;

        int[] lis = new int[n];
        int[] lds = new int[n];

        // Longest Increasing Subsequence ending at each index
        for (int i = 0; i < n; i++) {
            lis[i] = 1;
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i] && lis[j] + 1 > lis[i]) {
                    lis[i] = lis[j] + 1;
                }
            }
        }

        // Longest Decreasing Subsequence starting at each index
        for (int i = n - 1; i >= 0; i--) {
            lds[i] = 1;
            for (int j = i + 1; j < n; j++) {
                if (nums[j] < nums[i] && lds[j] + 1 > lds[i]) {
                    lds[i] = lds[j] + 1;
                }
            }
        }

        int maxLen = 0;
        for (int i = 0; i < n; i++) {
            if (lis[i] > 1 && lds[i] > 1) {
                int len = lis[i] + lds[i] - 1;
                if (len > maxLen) maxLen = len;
            }
        }

        if (maxLen < 3) return -1;
        return n - maxLen;
    }
}

