public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numberOfSets(int n, int k) {
        if (k == 0) return 1;
        long total = (long) n + k - 1;
        long choose = 2L * k;
        if (total < choose) return 0;

        int max = (int) total; // n + k - 1
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];

        fact[0] = 1;
        for (int i = 1; i <= max; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        invFact[max] = modPow(fact[max], MOD - 2);
        for (int i = max; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        long res = fact[(int) total];
        res = res * invFact[(int) choose] % MOD;
        res = res * invFact[(int) (total - choose)] % MOD;
        return (int) res;
    }

    private long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}

