            int sumI = aliceValues[i] + bobValues[i];
            int sumJ = aliceValues[j] + bobValues[j];
            return Integer.compare(sumJ, sumI); // descending order of total value
        });

        long diff = 0;
        for (int k = 0; k < n; k++) {
            int i = idx[k];
            if ((k & 1) == 0) { // Alice's turn
                diff += aliceValues[i];
            } else { // Bob's turn
                diff -= bobValues[i];
            }
        }

        if (diff > 0) return 1;
        if (diff < 0) return -1;
        return 0;
    }
