import java.util.*;

public class Solution {
    private static class Dsu {
        int[] parent;
        int[] rank;

        Dsu(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        void union(int a, int b) {
            int pa = find(a);
            int pb = find(b);
            if (pa == pb) return;
            if (rank[pa] < rank[pb]) {
                parent[pa] = pb;
            } else if (rank[pa] > rank[pb]) {
                parent[pb] = pa;
            } else {
                parent[pb] = pa;
                rank[pa]++;
            }
        }
    }

    public boolean[] distanceLimitedPathsExist(int n, int[][] edgeList, int[][] queries) {
        int m = edgeList.length;
        int q = queries.length;

        // Attach original index to each query
        int[][] qWithIdx = new int[q][4];
        for (int i = 0; i < q; i++) {
            qWithIdx[i][0] = queries[i][0];
            qWithIdx[i][1] = queries[i][1];
            qWithIdx[i][2] = queries[i][2];
            qWithIdx[i][3] = i;
        }

        Arrays.sort(edgeList, Comparator.comparingInt(a -> a[2]));
        Arrays.sort(qWithIdx, Comparator.comparingInt(a -> a[2]));

        Dsu dsu = new Dsu(n);
        boolean[] ans = new boolean[q];
        int eIdx = 0;

        for (int[] qu : qWithIdx) {
            int limit = qu[2];
            while (eIdx < m && edgeList[eIdx][2] < limit) {
                dsu.union(edgeList[eIdx][0], edgeList[eIdx][1]);
                eIdx++;
            }
            ans[qu[3]] = dsu.find(qu[0]) == dsu.find(qu[1]);
        }

        return ans;
    }
}

