public class Solution {
    public int bestTeamScore(int[] scores, int[] ages) {
        int n = scores.length;
        int[][] players = new int[n][2]; // [age, score]
        for (int i = 0; i < n; i++) {
            players[i][0] = ages[i];
            players[i][1] = scores[i];
        }
        Arrays.sort(players, (a, b) -> {
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]); // age ascending
            }
            return Integer.compare(a[1], b[1]); // score ascending for same age
        });

        int[] dp = new int[n];
        int best = 0;
        for (int i = 0; i < n; i++) {
            dp[i] = players[i][1]; // at least the player himself
            for (int j = 0; j < i; j++) {
                if (players[j][1] <= players[i][1]) {
                    dp[i] = Math.max(dp[i], dp[j] + players[i][1]);
                }
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

