public class Solution {
    public int maxHeight(int[][] arr) {
        // Normalize each cuboid: sort its dimensions ascending
        for (int[] cuboid : arr) {
            Arrays.sort(cuboid);
        }

        // Sort all cuboids by width, then length, then height
        Arrays.sort(arr, new Comparator<int[]>() {
            @Override
            public int compare(int[] a, int[] b) {
                if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
                if (a[1] != b[1]) return Integer.compare(a[1], b[1]);
                return Integer.compare(a[2], b[2]);
            }
        });

        int n = arr.length;
        int[] dp = new int[n];
        int max = 0;

        for (int i = 0; i < n; i++) {
            dp[i] = arr[i][2]; // height of current cuboid
            for (int j = 0; j < i; j++) {
                if (arr[j][0] <= arr[i][0] &&
                    arr[j][1] <= arr[i][1] &&
                    arr[j][2] <= arr[i][2]) {
                    dp[i] = Math.max(dp[i], dp[j] + arr[i][2]);
                }
            }
            max = Math.max(max, dp[i]);
        }

        return max;
    }
}

