public class Solution {
    public String reformatNumber(String number) {
        // Remove spaces and dashes
        StringBuilder digits = new StringBuilder();
        for (int i = 0; i < number.length(); i++) {
            char c = number.charAt(i);
            if (c >= '0' && c <= '9') {
                digits.append(c);
            }
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        int len = digits.length();

        // Group into blocks of 3 until 4 or fewer digits remain
        while (len - i > 4) {
            result.append(digits, i, i + 3).append('-');
            i += 3;
        }

        // Handle the remaining digits
        int remaining = len - i;
        if (remaining == 2) {
            result.append(digits, i, i + 2);
        } else if (remaining == 3) {
            result.append(digits, i, i + 3);
        } else if (remaining == 4) {
            result.append(digits, i, i + 2).append('-').append(digits, i + 2, i + 4);
        }

        return result.toString();
    }
}

