import java.util.Arrays;

public class Solution {
    public int maxProfit(int[] inventory, int orders) {
        final long MOD = 1_000_000_007L;
        Arrays.sort(inventory);
        int n = inventory.length;
        int i = n - 1;
        long remaining = orders;
        long result = 0;

        while (remaining > 0 && i >= 0) {
            long current = inventory[i];
            long next = (i > 0) ? inventory[i - 1] : 0;
            long count = n - i;          // number of colors with inventory >= current
            long diff = current - next;

            if (diff == 0) {
                i--;
                continue;
            }

            long totalBalls = diff * count;
            if (remaining >= totalBalls) {
                // sell all balls from current down to next+1
                long sum = ((current + next + 1) % MOD) * (diff % MOD) % MOD;
                sum = sum * inv2 % MOD; // divide by 2 modulo
                sum = sum * (count % MOD) % MOD;
                result = (result + sum) % MOD;
                remaining -= totalBalls;
                i--;
            } else {
                long fullLevels = remaining / count;
                long remainder = remaining % count;
                long newLevel = current - fullLevels;

                long sumFull = ((current + newLevel + 1) % MOD) * (fullLevels % MOD) % MOD;
                sumFull = sumFull * inv2 % MOD;
                sumFull = sumFull * (count % MOD) % MOD;
                result = (result + sumFull) % MOD;

                result = (result + (remainder % MOD) * (newLevel % MOD) % MOD) % MOD;
                remaining = 0;
            }
        }
        return (int) result;
    }

    // modular inverse of 2 modulo MOD
    private static final long inv2 = 500000004L; // since MOD is prime 1e9+7
}

