public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int maxSum = 2 * limit;
        int[] diff = new int[maxSum + 2]; // +2 to safely access high+1 and sum+1

        for (int i = 0; i < n / 2; i++) {
            int a = nums[i];
            int b = nums[n - 1 - i];
            int sum = a + b;
            int low = Math.min(a, b) + 1;
            int high = Math.max(a, b) + limit;

            // Initially assume 2 changes for all sums
            diff[2] += 2;
            // From low onwards, only 1 change needed
            diff[low] -= 1;
            // After high, back to 2 changes
            if (high + 1 <= maxSum) {
                diff[high + 1] += 1;
            }
            // At exact sum, 0 changes
            diff[sum] -= 1;
            // After sum, back to 1 change
            if (sum + 1 <= maxSum) {
                diff[sum + 1] += 1;
            }
        }

        int minMoves = Integer.MAX_VALUE;
        int current = 0;
        for (int s = 2; s <= maxSum; s++) {
            current += diff[s];
            if (current < minMoves) {
                minMoves = current;
            }
        }
        return minMoves;
    }
}

