public class Solution {
    public int countBinarySubstrings(String s) {
        if (s == null || s.length() == 0) {
            return 0;
        }
        int count = 0;
        int prevLen = 0; // length of previous group
        int currLen = 1; // length of current group

        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                currLen++;
            } else {
                // group boundary reached
                count += Math.min(prevLen, currLen);
                prevLen = currLen;
                currLen = 1;
            }
        }
        // account for the last group pair
        count += Math.min(prevLen, currLen);
        return count;
    }
}

