import java.util.*;

public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        int n = target.length();
        int fullMask = (1 << n) - 1;
        // Preprocess stickers into character count arrays
        int[][] stickerCounts = new int[stickers.length][26];
        for (int i = 0; i < stickers.length; i++) {
            for (char c : stickers[i].toCharArray()) {
                stickerCounts[i][c - 'a']++;
            }
        }

        int[] memo = new int[1 << n];
        Arrays.fill(memo, -2); // -2 means uncomputed

        int result = dfs(0, fullMask, target.toCharArray(), stickerCounts, memo);
        return result == Integer.MAX_VALUE ? -1 : result;
    }

    private int dfs(int mask, int fullMask, char[] targetChars,
                    int[][] stickerCounts, int[] memo) {
        if (mask == fullMask) return 0;
        if (memo[mask] != -2) return memo[mask];

        int min = Integer.MAX_VALUE;
        for (int[] sticker : stickerCounts) {
            int newMask = applySticker(mask, targetChars, sticker);
            if (newMask == mask) continue; // sticker doesn't help
            int sub = dfs(newMask, fullMask, targetChars, stickerCounts, memo);
            if (sub != Integer.MAX_VALUE) {
                min = Math.min(min, sub + 1);
            }
        }
        memo[mask] = min;
        return min;
    }

    private int applySticker(int mask, char[] targetChars, int[] sticker) {
        int[] cnt = sticker.clone();
        int newMask = mask;
        for (int i = 0; i < targetChars.length; i++) {
            if (((mask >> i) & 1) == 0) { // not yet covered
                int idx = targetChars[i] - 'a';
                if (cnt[idx] > 0) {
                    cnt[idx]--;
                    newMask |= (1 << i);
                }
            }
        }
        return newMask;
    }
}

