public class Solution {
    public int[] maxSumOfThreeSubarrays(int[] nums, int k) {
        int n = nums.length;
        if (n < 3 * k) {
            return new int[0];
        }

        int m = n - k + 1; // number of subarrays of length k
        int[] sums = new int[m];
        // compute sums of all subarrays of length k
        int windowSum = 0;
        for (int i = 0; i < k; i++) {
            windowSum += nums[i];
        }
        sums[0] = windowSum;
        for (int i = 1; i < m; i++) {
            windowSum += nums[i + k - 1] - nums[i - 1];
            sums[i] = windowSum;
        }

        // left[i] = index of best subarray in [0, i]
        int[] left = new int[m];
        int best = 0;
        for (int i = 0; i < m; i++) {
            if (sums[i] > sums[best]) {
                best = i;
            }
            left[i] = best;
        }

        // right[i] = index of best subarray in [i, m-1]
        int[] right = new int[m];
        best = m - 1;
        for (int i = m - 1; i >= 0; i--) {
            if (sums[i] >= sums[best]) { // >= to keep smallest index on ties
                best = i;
            }
            right[i] = best;
        }

        int maxSum = -1;
        int[] answer = new int[3];

        // middle subarray starts at j
        for (int j = k; j <= m - k - 1; j++) {
            int i = left[j - k];
            int l = right[j + k];
            int total = sums[i] + sums[j] + sums[l];
            if (total > maxSum) {
                maxSum = total;
                answer[0] = i;
                answer[1] = j;
                answer[2] = l;
            }
        }

        return answer;
    }
}

