import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    public int cutOffTree(List<List<Integer>> forest) {
        if (forest == null || forest.isEmpty() || forest.get(0).isEmpty()) {
            return -1;
        }
        int m = forest.size();
        int n = forest.get(0).size();

        // Collect all trees with height > 1
        List<int[]> trees = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            List<Integer> row = forest.get(i);
            for (int j = 0; j < n; j++) {
                int val = row.get(j);
                if (val > 1) {
                    trees.add(new int[]{val, i, j});
                }
            }
        }

        // Sort trees by height ascending
        Collections.sort(trees, Comparator.comparingInt(a -> a[0]));

        int totalSteps = 0;
        int curR = 0, curC = 0;

        for (int[] tree : trees) {
            int targetR = tree[1];
            int targetC = tree[2];
            int steps = bfs(forest, curR, curC, targetR, targetC, m, n);
            if (steps == -1) {
                return -1;
            }
            totalSteps += steps;
            curR = targetR;
            curC = targetC;
        }

        return totalSteps;
    }

    private int bfs(List<List<Integer>> forest, int sr, int sc, int tr, int tc, int m, int n) {
        if (sr == tr && sc == tc) {
            return 0;
        }

        boolean[][] visited = new boolean[m][n];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{sr, sc, 0});
        visited[sr][sc] = true;

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            int dist = cur[2];

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= m || nc < 0 || nc >= n) {
                    continue;
                }
                if (visited[nr][nc]) {
                    continue;
                }
                int cellVal = forest.get(nr).get(nc);
                if (cellVal == 0) {
                    continue; // cannot walk through
                }
                if (nr == tr && nc == tc) {
                    return dist + 1;
                }
                visited[nr][nc] = true;
                queue.offer(new int[]{nr, nc, dist + 1});
            }
        }

        return -1; // target unreachable
    }
}

