public class Solution {
    public int findKthNumber(int m, int n, int k) {
        int low = 1;
        int high = m * n;
        while (low < high) {
            int mid = low + (high - low) / 2;
            long count = 0;
            for (int i = 1; i <= m; i++) {
                count += Math.min(n, mid / i);
                if (count >= k) break; // early exit to avoid unnecessary work
            }
            if (count >= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

