import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.TreeSet;

public class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        List<Integer> result = new ArrayList<>();
        if (positions == null || positions.length == 0) {
            return result;
        }

        // Coordinate compression
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] pos : positions) {
            int left = pos[0];
            int size = pos[1];
            int right = left + size - 1;
            set.add(left);
            set.add(right);
        }
        List<Integer> coords = new ArrayList<>(set);
        int n = coords.size();

        SegmentTree seg = new SegmentTree(n);
        int globalMax = 0;

        for (int[] pos : positions) {
            int left = pos[0];
            int size = pos[1];
            int right = left + size - 1;

            int lIdx = lowerBound(coords, left);
            int rIdx = lowerBound(coords, right);

            int currentMax = seg.query(1, 0, n - 1, lIdx, rIdx);
            int newHeight = currentMax + size;
            seg.update(1, 0, n - 1, lIdx, rIdx, newHeight);

            globalMax = Math.max(globalMax, newHeight);
            result.add(globalMax);
        }

        return result;
    }

    private int lowerBound(List<Integer> list, int target) {
        int idx = Collections.binarySearch(list, target);
        if (idx < 0) {
            idx = -idx - 1;
        }
        return idx;
    }

    // Segment tree with range assignment and range maximum query
    private static class SegmentTree {
        int[] tree;
        int[] lazy;
        int n;

        SegmentTree(int n) {
            this.n = n;
            tree = new int[4 * n];
            lazy = new int[4 * n];
        }

        private void push(int node) {
            if (lazy[node] != 0) {
                int val = lazy[node];
                tree[node * 2] = val;
                tree[node * 2 + 1] = val;
                lazy[node * 2] = val;
                lazy[node * 2 + 1] = val;
                lazy[node] = 0;
            }
        }

        int query(int node, int l, int r, int ql, int qr) {
            if (ql > r || qr < l) {
                return 0;
            }
            if (ql <= l && r <= qr) {
                return tree[node];
            }
            push(node);
            int mid = (l + r) >> 1;
            int leftMax = query(node * 2, l, mid, ql, qr);
            int rightMax = query(node * 2 + 1, mid + 1, r, ql, qr);
            return Math.max(leftMax, rightMax);
        }

        void update(int node, int l, int r, int ul, int ur, int val) {
            if (ul > r || ur < l) {
                return;
            }
            if (ul <= l && r <= ur) {
                tree[node] = val;
                lazy[node] = val;
                return;
            }
            push(node);
            int mid = (l + r) >> 1;
            update(node * 2, l, mid, ul, ur, val);
            update(node * 2 + 1, mid + 1, r, ul, ur, val);
            tree[node] = Math.max(tree[node * 2], tree[node * 2 + 1]);
        }
    }
}

