import java.util.List;

public class Solution {
    // Trie node definition
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isWord;
    }

    // Build trie from dictionary
    private TrieNode buildTrie(List<String> dictionary) {
        TrieNode root = new TrieNode();
        for (String word : dictionary) {
            TrieNode node = root;
            for (char ch : word.toCharArray()) {
                int idx = ch - 'a';
                if (node.children[idx] == null) {
                    node.children[idx] = new TrieNode();
                }
                node = node.children[idx];
            }
            node.isWord = true;
        }
        return root;
    }

    // Find the shortest root that is a prefix of the word
    private String findRoot(TrieNode root, String word) {
        TrieNode node = root;
        StringBuilder sb = new StringBuilder();
        for (char ch : word.toCharArray()) {
            int idx = ch - 'a';
            if (node.children[idx] == null) {
                break;
            }
            sb.append(ch);
            node = node.children[idx];
            if (node.isWord) {
                return sb.toString();
            }
        }
        return word; // no root found
    }

    public String replaceWords(List<String> dictionary, String sentence) {
        if (dictionary == null || dictionary.isEmpty() || sentence == null) {
            return sentence;
        }

        TrieNode trieRoot = buildTrie(dictionary);
        StringBuilder result = new StringBuilder();
        String[] words = sentence.split(" ");

        for (int i = 0; i < words.length; i++) {
            String replaced = findRoot(trieRoot, words[i]);
            result.append(replaced);
            if (i < words.length - 1) {
                result.append(' ');
            }
        }

        return result.toString();
    }
}

