public class Solution {
    public int strangePrinter(String s) {
        if (s == null || s.length() == 0) {
            return 0;
        }
        int n = s.length();
        int[][] dp = new int[n][n];
        // dp[i][j] represents the minimum turns to print s[i..j]
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1; // single character
            for (int j = i + 1; j < n; j++) {
                // start with printing s[j] separately
                dp[i][j] = dp[i][j - 1] + 1;
                // try to merge printing of s[j] with a previous same character
                for (int k = i; k < j; k++) {
                    if (s.charAt(k) == s.charAt(j)) {
                        int val = dp[i][k];
                        if (k + 1 <= j - 1) {
                            val += dp[k + 1][j - 1];
                        }
                        dp[i][j] = Math.min(dp[i][j], val);
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
}

