public class Solution {
    private static final int MOD = 1_000_000_007;

    public int kInversePairs(int n, int k) {
        // Maximum possible inversions for n elements
        int maxPossible = n * (n - 1) / 2;
        if (k > maxPossible) {
            return 0;
        }

        // We only need to compute up to k inversions
        int[][] dp = new int[n + 1][k + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            int maxInvForI = Math.min(k, i * (i - 1) / 2);
            dp[i][0] = 1; // Only one way to have 0 inversions (sorted order)

            for (int j = 1; j <= maxInvForI; j++) {
                long val = dp[i][j - 1] + dp[i - 1][j];
                if (j >= i) {
                    val -= dp[i - 1][j - i];
                }
                dp[i][j] = (int) (val % MOD);
            }
        }

        return dp[n][k];
    }
}

