import java.util.List;
import java.util.Map;

public class Solution {
    public List<List<String>> findDuplicate(String[] paths) {
        Map<String, List<String>> contentMap = new HashMap<>();
        for (String pathInfo : paths) {
            String[] parts = pathInfo.split(" ");
            String dir = parts[0];
            for (int i = 1; i < parts.length; i++) {
                String filePart = parts[i];
                int idx = filePart.indexOf('(');
                String fileName = filePart.substring(0, idx);
                String content = filePart.substring(idx + 1, filePart.length() - 1);
                String fullPath = dir + "/" + fileName;
                contentMap.computeIfAbsent(content, k -> new ArrayList<>()).add(fullPath);
            }
        }
        List<List<String>> result = new ArrayList<>();
        for (List<String> group : contentMap.values()) {
            if (group.size() > 1) {
                result.add(group);
            }
        }
        return result;
    }
}

