public class Solution {
    public int findNumberOfLIS(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;

        int[] len = new int[n];   // length of LIS ending at i
        int[] cnt = new int[n];   // number of LIS ending at i

        for (int i = 0; i < n; i++) {
            len[i] = 1;   // at least the element itself
            cnt[i] = 1;
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i]) {
                    if (len[j] + 1 > len[i]) {
                        len[i] = len[j] + 1;
                        cnt[i] = cnt[j];
                    } else if (len[j] + 1 == len[i]) {
                        cnt[i] += cnt[j];
                    }
                }
            }
        }

        int maxLen = 0;
        for (int l : len) {
            if (l > maxLen) maxLen = l;
        }

        int total = 0;
        for (int i = 0; i < n; i++) {
            if (len[i] == maxLen) {
                total += cnt[i];
            }
        }
        return total;
    }
}

