public class Solution {
    public int minSteps(int n) {
        if (n <= 1) return 0;
        int steps = 0;
        for (int i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                steps += i;
                n /= i;
            }
        }
        if (n > 1) steps += n;
        return steps;
    }
}

