            int u = edge[0], v = edge[1];
            if (parent[v] == 0) {
                parent[v] = u;
            } else {
                candidate1 = new int[]{parent[v], v};
                candidate2 = new int[]{u, v};
                break; // we found a duplicate parent, no need to process further for parent array
            }
        }

        // Union-Find helper
        class DSU {
            int[] p, r;
            DSU(int size) {
                p = new int[size + 1];
                r = new int[size + 1];
                for (int i = 0; i <= size; i++) p[i] = i;
            }
            int find(int x) {
                if (p[x] != x) p[x] = find(p[x]);
                return p[x];
            }
            boolean union(int a, int b) {
                int pa = find(a), pb = find(b);
                if (pa == pb) return false;
                if (r[pa] < r[pb]) {
                    p[pa] = pb;
                } else if (r[pa] > r[pb]) {
                    p[pb] = pa;
                } else {
                    p[pb] = pa;
                    r[pa]++;
                }
                return true;
            }
        }

        // If there was a node with two parents
        if (candidate1 != null) {
            DSU dsu = new DSU(n);
            for (int[] edge : edges) {
                if (edge[0] == candidate2[0] && edge[1] == candidate2[1]) {
                    continue; // skip the second edge
                }
                if (!dsu.union(edge[0], edge[1])) {
                    // cycle found when ignoring candidate2, so remove candidate1
                    return candidate1;
                }
            }
            // No cycle when ignoring candidate2, so remove candidate2
            return candidate2;
        } else {
            // No node with two parents, just find the cycle
            DSU dsu = new DSU(n);
            for (int[] edge : edges) {
                if (!dsu.union(edge[0], edge[1])) {
                    return edge;
                }
            }
        }
        // Should never reach here
        return new int[]{-1, -1};
    }
}

