public class Solution {
    public int repeatedStringMatch(String a, String b) {
        if (a == null || b == null) {
            return -1;
        }
        int lenA = a.length();
        int lenB = b.length();
        if (lenA == 0) {
            return lenB == 0 ? 0 : -1;
        }

        int repeats = (lenB + lenA - 1) / lenA; // ceil(lenB / lenA)
        StringBuilder sb = new StringBuilder(repeats * lenA);
        for (int i = 0; i < repeats; i++) {
            sb.append(a);
        }

        if (sb.toString().contains(b)) {
            return repeats;
        }

        sb.append(a); // one more repetition
        if (sb.toString().contains(b)) {
            return repeats + 1;
        }

        return -1;
    }
}

