public class Solution {
    public int leastInterval(char[] tasks, int n) {
        if (tasks == null || tasks.length == 0) return 0;
        int[] freq = new int[26];
        for (char c : tasks) {
            freq[c - 'A']++;
        }

        int maxFreq = 0;
        int maxCount = 0;
        for (int f : freq) {
            if (f > maxFreq) {
                maxFreq = f;
                maxCount = 1;
            } else if (f == maxFreq) {
                maxCount++;
            }
        }

        int idle = (maxFreq - 1) * (n + 1) - (tasks.length - maxCount);
        if (idle < 0) idle = 0;
        return tasks.length + idle;
    }
}

