import java.util.*;

public class Solution {
    public String solveEquation(String equation) {
        String[] sides = equation.split("=");
        int[] left = parseSide(sides[0]);
        int[] right = parseSide(sides[1]);

        int coeff = left[0] - right[0];
        int constant = left[1] - right[1];

        if (coeff == 0) {
            if (constant == 0) {
                return "Infinite solutions";
            } else {
                return "No solution";
            }
        }

        int x = -constant / coeff;
        return "x=" + x;
    }

    private int[] parseSide(String s) {
        int coeff = 0;
        int constant = 0;
        int sign = 1;
        int num = 0;
        boolean hasNum = false;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '+') {
                if (hasNum) {
                    constant += sign * num;
                    hasNum = false;
                    num = 0;
                }
                sign = 1;
            } else if (c == '-') {
                if (hasNum) {
                    constant += sign * num;
                    hasNum = false;
                    num = 0;
                }
                sign = -1;
            } else if (c == 'x') {
                if (!hasNum) {
                    coeff += sign * 1;
                } else {
                    coeff += sign * num;
                    hasNum = false;
                    num = 0;
                }
            } else { // digit
                num = num * 10 + (c - '0');
                hasNum = true;
            }
        }

        if (hasNum) {
            constant += sign * num;
        }

        return new int[]{coeff, constant};
    }
}

