import java.util.concurrent.atomic.AtomicInteger;

public class Solution {

    public int findSecondMinimumValue(TreeNode root) {
        if (root == null) {
            return -1;
        }
        int min = root.val;
        AtomicInteger secondMin = new AtomicInteger(Integer.MAX_VALUE);
        dfs(root, min, secondMin);
        return secondMin.get() == Integer.MAX_VALUE ? -1 : secondMin.get();
    }

    private void dfs(TreeNode node, int min, AtomicInteger secondMin) {
        if (node == null) {
            return;
        }
        if (node.val > min) {
            secondMin.updateAndGet(v -> Math.min(v, node.val));
        } else {
            dfs(node.left, min, secondMin);
            dfs(node.right, min, secondMin);
        }
    }

    // Definition for a binary tree node.
    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int val) {
            this.val = val;
        }

        TreeNode(int val, TreeNode left, TreeNode right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }
}

