public class Solution {
    public boolean checkValidString(String s) {
        int minOpen = 0; // minimum possible number of open '('
        int maxOpen = 0; // maximum possible number of open '('

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                minOpen++;
                maxOpen++;
            } else if (c == ')') {
                minOpen = Math.max(0, minOpen - 1);
                maxOpen--;
            } else { // '*'
                minOpen = Math.max(0, minOpen - 1);
                maxOpen++;
            }

            // If at any point maxOpen becomes negative, there are more ')' than possible '('
            if (maxOpen < 0) {
                return false;
            }
        }

        // If minOpen is zero, all '(' can be matched
        return minOpen == 0;
    }
}

