            return 0;
        }
        Arrays.sort(nums);
        int n = nums.length;
        long count = 0;
        for (int k = n - 1; k >= 2; k--) {
            int left = 0;
            int right = k - 1;
            while (left < right) {
                if (nums[left] + nums[right] > nums[k]) {
