import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    private Map<String, Integer> memo = new HashMap<>();

    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        return dfs(price, special, needs);
    }

    private int dfs(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {
        String key = buildKey(needs);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // Base cost: buy all remaining items at regular price
        int minCost = 0;
        for (int i = 0; i < needs.size(); i++) {
            minCost += needs.get(i) * price.get(i);
        }

        // Try each special offer
        for (List<Integer> offer : special) {
            boolean canUse = true;
            for (int i = 0; i < needs.size(); i++) {
                if (needs.get(i) < offer.get(i)) {
                    canUse = false;
                    break;
                }
            }
            if (!canUse) continue;

            // Apply offer
            for (int i = 0; i < needs.size(); i++) {
                needs.set(i, needs.get(i) - offer.get(i));
            }

            int offerCost = offer.get(offer.size() - 1) + dfs(price, special, needs);
            if (offerCost < minCost) {
                minCost = offerCost;
            }

            // Revert changes
            for (int i = 0; i < needs.size(); i++) {
                needs.set(i, needs.get(i) + offer.get(i));
            }
        }

        memo.put(key, minCost);
        return minCost;
    }

    private String buildKey(List<Integer> needs) {
        StringBuilder sb = new StringBuilder();
        for (int n : needs) {
            sb.append(n).append('#');
        }
        return sb.toString();
    }
}

