public class Solution {
    public int maximumSwap(int num) {
        char[] digits = Integer.toString(num).toCharArray();
        int n = digits.length;
        // last occurrence of each digit
        int[] last = new int[10];
        for (int i = 0; i < n; i++) {
            last[digits[i] - '0'] = i;
        }
        // find first position to swap
        for (int i = 0; i < n; i++) {
            int cur = digits[i] - '0';
            // check for a larger digit to the right
            for (int d = 9; d > cur; d--) {
                if (last[d] > i) {
                    // swap
                    char temp = digits[i];
                    digits[i] = digits[last[d]];
                    digits[last[d]] = temp;
