import java.util.Arrays;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int n = nums.length;
        int total = 0;
        for (int num : nums) total += num;
        if (total % k != 0) return false;
        int target = total / k;

        // Sort in descending order to prune faster
        Arrays.sort(nums);
        for (int i = 0; i < n / 2; i++) {
            int tmp = nums[i];
            nums[i] = nums[n - 1 - i];
            nums[n - 1 - i] = tmp;
        }

        // Quick check: if any number is larger than target, impossible
        for (int num : nums) {
            if (num > target) return false;
        }

        int[] memo = new int[1 << n];
        Arrays.fill(memo, -1);
        return dfs(0, 0, k, target, nums, memo);
    }

    private boolean dfs(int usedMask, int currentSum, int remainingK, int target,
                        int[] nums, int[] memo) {
        if (remainingK == 0) return true;
        if (currentSum == target) {
            // Start filling the next subset
            return dfs(usedMask, 0, remainingK - 1, target, nums, memo);
        }
        if (memo[usedMask] != -1) return memo[usedMask] == 1;

        for (int i = 0; i < nums.length; i++) {
            if ((usedMask & (1 << i)) != 0) continue; // already used
            if (currentSum + nums[i] > target) continue; // would exceed target

            if (dfs(usedMask | (1 << i), currentSum + nums[i], remainingK, target, nums, memo)) {
                memo[usedMask] = 1;
                return true;
            }
        }

        memo[usedMask] = 0;
        return false;
    }
}

