import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<Integer> findClosestElements(int[] arr, int k, int x) {
        int n = arr.length;
        // Find the first index where arr[idx] >= x
        int left = 0, right = n - 1;
        int idx = n; // default to n if all elements < x
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] >= x) {
                idx = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        int l = idx - 1; // candidate left pointer
        int r = idx;     // candidate right pointer

        while (k > 0) {
            if (l < 0) {
                r++;
            } else if (r >= n) {
                l--;
            } else {
                int leftDiff = Math.abs(arr[l] - x);
                int rightDiff = Math.abs(arr[r] - x);
                if (leftDiff <= rightDiff) {
                    l--;
                } else {
                    r++;
                }
            }
            k--;
        }

        List<Integer> result = new ArrayList<>();
        for (int i = l + 1; i < r; i++) {
            result.add(arr[i]);
        }
        return result;
    }
}

