import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<List<String>> printTree(TreeNode root) {
        if (root == null) {
            return new ArrayList<>();
        }

        int height = getHeight(root);
        int rows = height + 1;
        int cols = (1 << (height + 1)) - 1; // 2^(height+1) - 1

        List<List<String>> res = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            List<String> row = new ArrayList<>(cols);
            for (int j = 0; j < cols; j++) {
                row.add("");
            }
            res.add(row);
        }

        fill(res, root, 0, (cols - 1) / 2, height);
        return res;
    }

    private int getHeight(TreeNode node) {
        if (node == null) {
            return -1; // height of empty tree is -1 so that a single node has height 0
        }
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    private void fill(List<List<String>> res, TreeNode node, int row, int col, int height) {
        if (node == null) {
            return;
        }
        res.get(row).set(col, String.valueOf(node.val));
        if (node.left != null) {
            int offset = 1 << (height - row - 1);
            fill(res, node.left, row + 1, col - offset, height);
        }
        if (node.right != null) {
            int offset = 1 << (height - row - 1);
            fill(res, node.right, row + 1, col + offset, height);
        }
    }
}

