public class Solution {

    private static class Pair {
        TreeNode node;
        long idx;

        Pair(TreeNode node, long idx) {
            this.node = node;
            this.idx = idx;
        }
    }

    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) {
            return 0;
        }

        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(root, 0));
        int maxWidth = 0;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            long levelStartIdx = queue.peek().idx;
            long levelEndIdx = levelStartIdx;

            for (int i = 0; i < levelSize; i++) {
                Pair current = queue.poll();
                levelEndIdx = current.idx;

                if (current.node.left != null) {
                    queue.offer(new Pair(current.node.left, current.idx * 2 + 1));
                }
                if (current.node.right != null) {
                    queue.offer(new Pair(current.node.right, current.idx * 2 + 2));
                }
            }

            int width = (int) (levelEndIdx - levelStartIdx + 1);
            if (width > maxWidth) {
                maxWidth = width;
            }
        }

        return maxWidth;
    }
}

