import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    /**
     * Builds a binary tree from a level‑order array representation.
     * Null values in the array represent missing children.
     *
     * @param values the array of Integer values
     * @return the root of the constructed binary tree
     */
    public static TreeNode buildTree(Integer[] values) {
        if (values == null || values.length == 0) {
            return null;
        }

        TreeNode root = new TreeNode(values[0]);
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        int i = 1;

        while (i < values.length) {
            TreeNode current = queue.poll();
            if (current == null) {
                continue;
            }

            // Left child
            Integer leftVal = values[i++];
            if (leftVal != null) {
                current.left = new TreeNode(leftVal);
                queue.offer(current.left);
            }

            if (i >= values.length) {
                break;
            }

            // Right child
            Integer rightVal = values[i++];
            if (rightVal != null) {
                current.right = new TreeNode(rightVal);
                queue.offer(current.right);
            }
        }

        return root;
    }
}

