public class Solution {
    public int[] constructArray(int n, int k) {
        int[] ans = new int[n];

        // Special case: k == 1 → descending order
        if (k == 1) {
            for (int i = 0; i < n; i++) {
                ans[i] = n - i;   // n, n-1, ..., 1
            }
            return ans;
        }

        int low = 1;
        int high = k + 1;

        // Build the first k+1 elements to guarantee k distinct differences
        for (int i = 0; i <= k; i++) {
            if (i % 2 == 0) {
                ans[i] = low++;
            } else {
                ans[i] = high--;
            }
        }

        // Fill the remaining positions with the unused numbers in ascending order
        low = k + 2; // next unused number after the first k+1
        for (int i = k + 1; i < n; i++) {
            ans[i] = low++;
        }

        return ans;
    }
}

