public class Solution {
    public int singleNumber(int[] nums) {
        int ones = 0, twos = 0;
        for (int num : nums) {
            // Update twos with bits that have appeared twice
            twos |= ones & num;
            // Update ones with bits that have appeared once
            ones ^= num;
            // Mask to remove bits that have appeared three times
            int mask = ~(ones & twos);
            ones &= mask;
            twos &= mask;
        }
        return ones;
    }
