public class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> row = new ArrayList<>();
        row.add(1); // first element of the first row

        for (int i = 1; i <= rowIndex; i++) {
            // Reserve space for the new element
            row.add(0);

            // iterate backwards to avoid overwriting values needed for the next calculation
            for (int j = i - 1; j >= 0; j--) {
                int left = row.get(j);
                int right = row.get(j + 1);
                row.set(j + 1, left + right);
            }
            row.set(0, 1); // first element of each row is always 1
        }

        return row;
    }
}

