public class Solution {
    public int compareVersion(String version1, String version2) {
        String[] revs1 = version1.split("\\.");
        String[] revs2 = version2.split("\\.");
        int len = Math.max(revs1.length, revs2.length);
        for (int i = 0; i < len; i++) {
            String r1 = i < revs1.length ? revs1[i] : "0";
            String r2 = i < revs2.length ? revs2[i] : "0";

            // Remove leading zeros
            r1 = r1.replaceFirst("^0+", "");
            r2 = r2.replaceFirst("^0+", "");
            if (r1.isEmpty()) r1 = "0";
            if (r2.isEmpty()) r2 = "0";

            if (r1.length() > r2.length()) return 1;
            if (r1.length() < r2.length()) return -1;
            int cmp = r1.compareTo(r2);
            if (cmp != 0) return cmp > 0 ? 1 : -1;
        }
        return 0;
    }
}

