import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.Queue;
import java.util.LinkedList;

public class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordDict) {
        if (beginWord == null || endWord == null || wordDict == null) {
            return 0;
        }

        Set<String> wordSet = new HashSet<>(wordDict);
        if (!wordSet.contains(endWord)) {
            return 0;
        }

        // If beginWord is the same as endWord, the shortest sequence length is 1
        if (beginWord.equals(endWord)) {
            return 1;
        }

        Queue<String> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();

        queue.offer(beginWord);
        visited.add(beginWord);
        int level = 1; // beginWord is counted as level 1

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String current = queue.poll();
                if (current.equals(endWord)) {
                    return level;
                }

                char[] chars = current.toCharArray();
                for (int pos = 0; pos < chars.length; pos++) {
                    char originalChar = chars[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == originalChar) {
                            continue;
                        }
                        chars[pos] = c;
                        String nextWord = new String(chars);
                        if (wordSet.contains(nextWord) && !visited.contains(nextWord)) {
                            queue.offer(nextWord);
                            visited.add(nextWord);
                        }
                    }
                    chars[pos] = originalChar; // restore original character
                }
            }
            level++;
        }

        return 0; // no possible transformation
    }
}

