public class Solution {

    /**
     * Builds a binary tree from an array representation.
     * The array is interpreted in level-order, where null indicates a missing node.
     *
     * @param values the array of Integer values
     * @return the root of the constructed binary tree
     */
    public static TreeNode buildTree(Integer[] values) {
        if (values == null || values.length == 0) {
            return null;
        }

        TreeNode[] nodes = new TreeNode[values.length];
        for (int i = 0; i < values.length; i++) {
            Integer v = values[i];
            nodes[i] = (v == null) ? null : new TreeNode(v);
        }

        for (int i = 0; i < values.length; i++) {
            TreeNode current = nodes[i];
            if (current != null) {
                int leftIdx = 2 * i + 1;
                int rightIdx = 2 * i + 2;
                if (leftIdx < values.length) {
                    current.left = nodes[leftIdx];
                }
                if (rightIdx < values.length) {
                    current.right = nodes[rightIdx];
                }
            }
        }

        return nodes[0];
    }
}

