import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;

public class Solution {
    public List<String> findRepeatedDnaSequences(String s) {
        List<String> result = new ArrayList<>();
        if (s == null || s.length() < 10) {
            return result;
        }

        // Map nucleotides to 2-bit values
        int[] map = new int[128];
        map['A'] = 0;
        map['C'] = 1;
        map['G'] = 2;
        map['T'] = 3;

        HashSet<Integer> seen = new HashSet<>();
        HashSet<String> repeated = new HashSet<>();

        int mask = 0;
        // Build the first 10-letter mask
        for (int i = 0; i < 10; i++) {
            mask = (mask << 2) | map[s.charAt(i)];
        }
        seen.add(mask);

        int maskLimit = (1 << 20) - 1; // keep only 20 bits

        for (int i = 10; i < s.length(); i++) {
            // Slide window: add new char and drop the oldest
            mask = ((mask << 2) | map[s.charAt(i)]) & maskLimit;
            if (seen.contains(mask)) {
                repeated.add(s.substring(i - 9, i + 1));
            } else {
                seen.add(mask);
            }
        }

        result.addAll(repeated);
        return result;
    }
}

