public class Solution {
    public int numDistinct(String text, String text2) {
        if (text == null || text2 == null) return 0;
        int m = text.length();
        int n = text2.length();
        if (n == 0) return 1;
        if (m < n) return 0;

        int[] dp = new int[n + 1];
        dp[0] = 1; // empty t

        for (int i = 1; i <= m; i++) {
            char sc = text.charAt(i - 1);
            // iterate backwards to avoid overwriting dp[j-1] needed for current i
            for (int j = n; j >= 1; j--) {
                if (sc == text2.charAt(j - 1)) {
                    dp[j] += dp[j - 1];
                }
            }
        }
        return dp[n];
    }
}

