import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;

public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        List<List<String>> result = new ArrayList<>();
        if (beginWord == null || endWord == null || wordList == null) {
            return result;
        }

        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return result;
        }

        // Build reverse graph: key -> set of predecessors
        Map<String, Set<String>> graph = new HashMap<>();
        for (String word : wordSet) {
            graph.put(word, new HashSet<>());
        }
        graph.put(beginWord, new HashSet<>()); // ensure beginWord is in graph

        // BFS
        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);
        Set<String> visitedThisLevel = new HashSet<>();
        Set<String> visited = new HashSet<>();
        visited.add(beginWord);
        boolean foundEnd = false;

        while (!queue.isEmpty() && !foundEnd) {
            int levelSize = queue.size();
            visitedThisLevel.clear();
            for (int i = 0; i < levelSize; i++) {
                String current = queue.poll();
                char[] curArr = current.toCharArray();
                for (int pos = 0; pos < curArr.length; pos++) {
                    char original = curArr[pos];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) continue;
                        curArr[pos] = c;
                        String next = new String(curArr);
                        if (wordSet.contains(next)) {
                            // Build reverse edge: next <- current
                            graph.get(next).add(current);
                            if (!visited.contains(next)) {
                                visitedThisLevel.add(next);
                                if (next.equals(endWord)) {
                                    foundEnd = true;
                                }
                            }
                        }
                    }
                    curArr[pos] = original;
                }
            }
            for (String word : visitedThisLevel) {
                visited.add(word);
                queue.offer(word);
            }
        }

        if (!foundEnd) {
            return result;
        }

        // DFS backtracking from endWord to beginWord
        LinkedList<String> path = new LinkedList<>();
        path.add(endWord);
        backtrack(endWord, beginWord, graph, path, result);
        return result;
    }

    private void backtrack(String current, String beginWord,
                           Map<String, Set<String>> graph,
                           LinkedList<String> path,
                           List<List<String>> result) {
        if (current.equals(beginWord)) {
            List<String> temp = new ArrayList<>(path);
            Collections.reverse(temp);
            result.add(temp);
            return;
        }
        for (String prev : graph.getOrDefault(current, Collections.emptySet())) {
            path.add(prev);
            backtrack(prev, beginWord, graph, path, result);
            path.removeLast();
        }
    }
}


