public class Solution {
    public String sortedArrayToBST(int[] nums) {
        if (nums == null || nums.length == 0) {
            return "";
        }
        TreeNode root = buildTree(nums, 0, nums.length - 1);
        return treeToString(root);
    }

    private TreeNode buildTree(int[] nums, int left, int right) {
        if (left > right) {
            return null;
        }
        int mid = left + (right - left) / 2;
        TreeNode node = new TreeNode(nums[mid]);
        node.left = buildTree(nums, left, mid - 1);
        node.right = buildTree(nums, mid + 1, right);
        return node;
    }

    private String treeToString(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        preOrder(root, sb);
        String result = sb.toString();

        // Remove trailing "null," segments
        while (result.endsWith("null,")) {
            result = result.substring(0, result.length() - 5);
        }
        // Remove trailing comma if present
        if (result.endsWith(",")) {
            result = result.substring(0, result.length() - 1);
        }
        return result;
    }

    private void preOrder(TreeNode node, StringBuilder sb) {
        if (node == null) {
            sb.append("null,");
            return;
        }
        sb.append(node.val).append(",");
        preOrder(node.left, sb);
        preOrder(node.right, sb);
    }
}

