import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int makeArrayIncreasing(int[] arr1, int[] arr2) {
        // Sort arr2 and remove duplicates
        Arrays.sort(arr2);
        int m = 0;
        for (int val : arr2) {
            if (m == 0 || arr2[m - 1] != val) {
                arr2[m++] = val;
            }
        }

        // dp maps a value to the minimal number of operations needed
        // to make the prefix ending with that value strictly increasing
        Map<Integer, Integer> dp = new HashMap<>();
        dp.put(Integer.MIN_VALUE, 0); // sentinel for the start

        for (int num : arr1) {
            Map<Integer, Integer> next = new HashMap<>();
            for (Map.Entry<Integer, Integer> entry : dp.entrySet()) {
                int prev = entry.getKey();
                int ops = entry.getValue();

                // Option 1: keep arr1[i] if it is greater than prev
                if (num > prev) {
                    next.merge(num, ops, Math::min);
                }

                // Option 2: replace arr1[i] with the smallest arr2 element > prev
                int idx = upperBound(arr2, m, prev);
                if (idx < m) {
                    int val = arr2[idx];
                    next.merge(val, ops + 1, Math::min);
                }
            }
            dp = next;
            if (dp.isEmpty()) {
                return -1; // impossible to continue
            }
        }

        int ans = Integer.MAX_VALUE;
        for (int ops : dp.values()) {
            ans = Math.min(ans, ops);
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }

    // Returns the index of the first element in arr[0..len) that is > target
    private int upperBound(int[] arr, int len, int target) {
        int l = 0, r = len;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (arr[mid] <= target) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        return l;
    }
}

