import java.util.*;

public class Solution {
    public int maximumSum(int[] arr) {
        int n = arr.length;
        if (n == 0) return 0; // not expected per problem statement

        long keep = arr[0];                     // max subarray sum ending at i without deletion
        long delete = Long.MIN_VALUE;           // max subarray sum ending at i with one deletion
        long ans = keep;

        for (int i = 1; i < n; i++) {
            long newKeep = Math.max(keep + arr[i], arr[i]);

            long newDelete;
            if (delete == Long.MIN_VALUE) {
                newDelete = keep; // delete current element
            } else {
                newDelete = Math.max(delete + arr[i], keep); // delete current or keep previous deletion
            }

            keep = newKeep;
            delete = newDelete;
            ans = Math.max(ans, Math.max(keep, delete));
        }
        return (int) ans;
    }
}

