import java.util.LinkedList;
import java.util.Queue;

public class Solution {
    public int maxDistance(int[][] grid) {
        int n = grid.length;
        int landCount = 0;
        int waterCount = 0;
        Queue<int[]> queue = new LinkedList<>();

        // Initialize queue with all land cells and count land/water
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    landCount++;
                    queue.offer(new int[]{i, j});
                } else {
                    waterCount++;
                }
            }
        }

        // If there is no land or no water, return -1
        if (landCount == 0 || waterCount == 0) {
            return -1;
        }

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int distance = -1;

        // BFS from all land cells simultaneously
        while (!queue.isEmpty()) {
            int size = queue.size();
            distance++; // increase distance for each layer
            for (int k = 0; k < size; k++) {
                int[] cur = queue.poll();
                int x = cur[0], y = cur[1];
                for (int[] d : dirs) {
                    int nx = x + d[0];
                    int ny = y + d[1];
                    if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] == 0) {
                        grid[nx][ny] = 2; // mark as visited
                        queue.offer(new int[]{nx, ny});
                    }
                }
            }
        }

        return distance;
    }
}

