public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        long movesPattern1 = 0; // even indices high, odd low
        long movesPattern2 = 0; // odd indices high, even low

        // Pattern 1: odd indices should be low
        for (int i = 1; i < n; i += 2) {
            int left = (i - 1 >= 0) ? nums[i - 1] : Integer.MAX_VALUE;
            int right = (i + 1 < n) ? nums[i + 1] : Integer.MAX_VALUE;
            int target = Math.min(left, right) - 1;
            if (nums[i] > target) {
                movesPattern1 += (long) nums[i] - target;
            }
        }

        // Pattern 2: even indices should be low
        for (int i = 0; i < n; i += 2) {
            int left = (i - 1 >= 0) ? nums[i - 1] : Integer.MAX_VALUE;
            int right = (i + 1 < n) ? nums[i + 1] : Integer.MAX_VALUE;
            int target = Math.min(left, right) - 1;
            if (nums[i] > target) {
                movesPattern2 += (long) nums[i] - target;
            }
        }

        return (int) Math.min(movesPattern1, movesPattern2);
    }
}

