import java.util.*;

public class Solution {

    /**
     * Returns the length of the longest substring with repeated characters after at most one swap.
     *
     * @param text the input string
     * @return the maximum length achievable
     */
    public int longestSubstring(String text) {
        if (text == null || text.length() == 0) {
            return 0;
        }

        int n = text.length();
        // Map each character to the list of its indices in the string
        Map<Character, List<Integer>> posMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            char ch = text.charAt(i);
            posMap.computeIfAbsent(ch, k -> new ArrayList<>()).add(i);
        }

        int result = 0;

        // For each character, analyze its occurrences
        for (Map.Entry<Character, List<Integer>> entry : posMap.entrySet()) {
            List<Integer> positions = entry.getValue();
            int totalCount = positions.size();

            int prevBlockLen = 0; // length of previous contiguous block
            int prevBlockEnd = -2; // end index of previous block

            for (int idx = 0; idx < positions.size(); idx++) {
                int startPos = positions.get(idx);
                int curBlockLen = 1;
                int curPos = startPos;

                // Determine current block length
                while (idx + 1 < positions.size() && positions.get(idx + 1) == curPos + 1) {
                    curBlockLen++;
                    idx++;
                    curPos = positions.get(idx);
                }

                // Case 1: Extend current block by one if there is an extra occurrence elsewhere
                if (totalCount > curBlockLen) {
                    result = Math.max(result, curBlockLen + 1);
                } else {
                    result = Math.max(result, curBlockLen);
                }

                // Case 2: Merge with previous block separated by exactly one different character
                if (prevBlockEnd + 2 == startPos) {
                    int mergedLen = prevBlockLen + curBlockLen;

                    // Do not exceed the total number of this character
                    if (mergedLen > totalCount) {
                        mergedLen = totalCount;
                    } else if (totalCount > mergedLen) {
                        // We can bring one more occurrence into the middle
                        mergedLen = Math.min(mergedLen + 1, totalCount);
                    }

                    result = Math.max(result, mergedLen);
                    prevBlockLen = mergedLen;   // use the capped value for the next iteration
                } else {
                    // No merge, just keep current block as previous
                    prevBlockLen = curBlockLen;
                }

                // Update previous block end index for next iteration
                prevBlockEnd = curPos;
            }
        }

        return result;
    }

    /**
     * Wrapper method expected by the test harness.
     *
     * @param text the input string
     * @return the maximum length achievable after at most one swap
     */
    public int maxRepOpt1(String text) {
        return longestSubstring(text);
    }
}

