public class Solution {
    public boolean parseBoolExpr(String expression) {
        int[] idx = {0};
        return parse(expression, idx);
    }

    private boolean parse(String s, int[] idx) {
        char c = s.charAt(idx[0]);

        if (c == 't') {
            idx[0]++;
            return true;
        }
        if (c == 'f') {
            idx[0]++;
            return false;
        }

        // operator
        idx[0]++; // skip operator
        idx[0]++; // skip '('

        boolean result;
        if (c == '!') {
            result = !parse(s, idx);
        } else if (c == '&') {
            result = true;
            while (s.charAt(idx[0]) != ')') {
                result &= parse(s, idx);
                if (s.charAt(idx[0]) == ',') idx[0]++;
            }
        } else { // '|'
            result = false;
            while (s.charAt(idx[0]) != ')') {
                result |= parse(s, idx);
                if (s.charAt(idx[0]) == ',') idx[0]++;
            }
        }

        idx[0]++; // skip ')'
        return result;
    }
}

