import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Solution for the smallest sufficient team problem.
 */
public class Solution {
    public int[] smallestSufficientTeam(String[] skills, List<List<String>> people) {
        int nSkills = skills.length;
        if (nSkills == 0) {
            return new int[0];
        }

        Map<String, Integer> skillToBit = new HashMap<>();
        for (int i = 0; i < nSkills; i++) {
            skillToBit.put(skills[i], i);
        }

        int[] personMask = new int[people.size()];
        for (int i = 0; i < people.size(); i++) {
            int mask = 0;
            for (String skill : people.get(i)) {
                Integer bit = skillToBit.get(skill);
                if (bit != null) {
                    mask |= (1 << bit);
                }
            }
            personMask[i] = mask;
        }

        int fullMask = (1 << nSkills) - 1;
        @SuppressWarnings("unchecked")
        List<Integer>[] dp = new List[1 << nSkills];
        dp[0] = new ArrayList<>();

        for (int i = 0; i < people.size(); i++) {
            int pMask = personMask[i];
            if (pMask == 0) continue;
            for (int mask = fullMask; mask >= 0; mask--) {
                if (dp[mask] == null) continue;
                int newMask = mask | pMask;
                if (dp[newMask] == null || dp[mask].size() + 1 < dp[newMask].size()) {
                    List<Integer> newTeam = new ArrayList<>(dp[mask]);
                    newTeam.add(i);
                    dp[newMask] = newTeam;
                }
            }
        }

        List<Integer> resultList = dp[fullMask];
        if (resultList == null) {
            return new int[0];
        }
        int[] result = new int[resultList.size()];
        for (int i = 0; i < resultList.size(); i++) {
            result[i] = resultList.get(i);
        }
        return result;
    }
}

