public class Solution {
    public List<String> invalidTransactions(String[] transactions) {
        int n = transactions.length;
        Transaction[] trans = new Transaction[n];
        for (int i = 0; i < n; i++) {
            String[] parts = transactions[i].split(",");
            String name = parts[0];
            int time = Integer.parseInt(parts[1]);
            int amount = Integer.parseInt(parts[2]);
            String city = parts[3];
            trans[i] = new Transaction(name, time, amount, city, transactions[i], i);
        }

        // Check amount > 1000
        for (Transaction t : trans) {
            if (t.amount > 1000) {
                t.invalid = true;
            }
        }

        // Check same name, different city within 60 minutes
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                Transaction a = trans[i];
                Transaction b = trans[j];
                if (a.name.equals(b.name) && !a.city.equals(b.city)) {
                    if (Math.abs(a.time - b.time) <= 60) {
                        a.invalid = true;
                        b.invalid = true;
                    }
                }
            }
        }

        List<String> result = new ArrayList<>();
        for (Transaction t : trans) {
            if (t.invalid) {
                result.add(t.original);
            }
        }
        return result;
    }

    private static class Transaction {
        String name;
        int time;
        int amount;
        String city;
        String original;
        int index;
        boolean invalid = false;

        Transaction(String name, int time, int amount, String city, String original, int index) {
            this.name = name;
            this.time = time;
            this.amount = amount;
            this.city = city;
            this.original = original;
            this.index = index;
        }
    }
}

