import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int kConcatenationMaxSum(int[] arr, int k) {
        long maxOne = kadane(arr);
        if (k == 1) {
            return modIfPositive(maxOne);
        }

        long totalSum = 0;
        for (int v : arr) {
            totalSum += v;
        }

        long maxTwo = kadaneTwice(arr);

        if (totalSum <= 0) {
            return modIfPositive(maxTwo);
        } else {
            long ans = maxTwo + (long) (k - 2) * totalSum;
            return modIfPositive(ans);
        }
    }

    private long kadane(int[] arr) {
        long maxEnding = 0;
        long maxSoFar = 0;
        for (int v : arr) {
            maxEnding = Math.max(v, maxEnding + v);
            maxSoFar = Math.max(maxSoFar, maxEnding);
        }
        return maxSoFar;
    }

    private long kadaneTwice(int[] arr) {
        int n = arr.length;
        long maxEnding = 0;
        long maxSoFar = 0;
        for (int i = 0; i < 2 * n; i++) {
            int v = arr[i % n];
            maxEnding = Math.max(v, maxEnding + v);
            maxSoFar = Math.max(maxSoFar, maxEnding);
        }
        return maxSoFar;
    }

    private int modIfPositive(long value) {
        if (value <= 0) {
            return 0;
        }
        return (int) (value % MOD);
    }
}

