import java.util.*;

public class Solution {
    public int[] relativeSortArray(int[] arr1, int[] arr2) {
        // Count occurrences of each element in arr1
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int val : arr1) {
            countMap.put(val, countMap.getOrDefault(val, 0) + 1);
        }

        // Prepare result array
        int[] result = new int[arr1.length];
        int idx = 0;

        // Place elements that appear in arr2 in the order of arr2
        for (int val : arr2) {
            int cnt = countMap.getOrDefault(val, 0);
            for (int i = 0; i < cnt; i++) {
                result[idx++] = val;
            }
            countMap.remove(val); // remove processed elements
        }

        // Remaining elements: sort ascending and append
        List<Integer> remaining = new ArrayList<>(countMap.keySet());
        Collections.sort(remaining);
        for (int val : remaining) {
            int cnt = countMap.get(val);
            for (int i = 0; i < cnt; i++) {
                result[idx++] = val;
            }
        }

        return result;
    }
}

