public class Solution {
    public List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        // Map to store frequency of each unique word mask
        Map<Integer, Integer> maskCount = new HashMap<>();

        for (String word : words) {
            int mask = 0;
            for (char c : word.toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            maskCount.merge(mask, 1, Integer::sum);
        }

        List<Integer> result = new ArrayList<>(puzzles.length);

        for (String puzzle : puzzles) {
            int puzzleMask = 0;
            for (char c : puzzle.toCharArray()) {
                puzzleMask |= 1 << (c - 'a');
            }
            int firstBit = 1 << (puzzle.charAt(0) - 'a');

            int count = 0;
            // Iterate over all subsets of puzzleMask
            for (int sub = puzzleMask; sub > 0; sub = (sub - 1) & puzzleMask) {
                if ((sub & firstBit) != 0) {
                    count += maskCount.getOrDefault(sub, 0);
                }
            }
            result.add(count);
        }

        return result;
    }
}

