public class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return 0;
        }
        int n = grid.length;
        int m = grid[0].length;
        int[][] right = new int[n][m];
        int[][] down = new int[n][m];

        // Precompute consecutive 1s to the right and downwards
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] == 1) {
                    right[i][j] = 1 + (j + 1 < m ? right[i][j + 1] : 0);
                    down[i][j] = 1 + (i + 1 < n ? down[i + 1][j] : 0);
                } else {
                    right[i][j] = 0;
                    down[i][j] = 0;
                }
            }
        }

        int best = 0;
        // Iterate over all possible top-left corners
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxSide = Math.min(right[i][j], down[i][j]);
                // Try larger squares first
                for (int side = maxSide; side > best; side--) {
                    if (down[i][j + side - 1] >= side && right[i + side - 1][j] >= side) {
                        best = side;
                        break; // No need to check smaller sides for this corner
                    }
                }
            }
        }

        return best * best;
    }
}

