import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Solution {
    // red -> 0
    // blue -> 1
    public int[] shortestAlternatingPaths(int n, int[][] redEdges, int[][] blueEdges) {
        List<Integer>[] redAdj = new ArrayList[n];
        List<Integer>[] blueAdj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            redAdj[i] = new ArrayList<>();
            blueAdj[i] = new ArrayList<>();
        }
        for (int[] e : redEdges) {
            redAdj[e[0]].add(e[1]);
        }
        for (int[] e : blueEdges) {
            blueAdj[e[0]].add(e[1]);
        }

        int INF = Integer.MAX_VALUE / 2;
        int[][] dist = new int[n][2];
        for (int i = 0; i < n; i++) {
            dist[i][0] = INF;
            dist[i][1] = INF;
        }
        Queue<int[]> q = new LinkedList<>();
        // start from node 0 with both colors
        dist[0][0] = 0;
        dist[0][1] = 0;
        q.offer(new int[]{0, 0});
        q.offer(new int[]{0, 1});

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int node = cur[0];
            int color = cur[1];
            int nextColor = 1 - color;
            List<Integer> neighbors = (color == 0) ? blueAdj[node] : redAdj[node];
            for (int nb : neighbors) {
                if (dist[nb][nextColor] > dist[node][color] + 1) {
                    dist[nb][nextColor] = dist[node][color] + 1;
                    q.offer(new int[]{nb, nextColor});
                }
            }
        }

        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            int d = Math.min(dist[i][0], dist[i][1]);
            ans[i] = d == INF ? -1 : d;
        }
        return ans;
    }
}

