import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        LinkedList<Integer> path = new LinkedList<>();
        int current = label;

        while (current > 0) {
            path.addFirst(current);
            if (current == 1) {
                break; // reached root
            }

            int level = 32 - Integer.numberOfLeadingZeros(current);
            long normal = (level % 2 == 0)
                    ? ((1L << level) - 1) - current + (1L << (level - 1))
                    : current;

            long parentNormal = normal / 2;
            current = (int) normalToZigzag(parentNormal, level - 1);
        }

        return path;
    }

    private long normalToZigzag(long normal, int level) {
        if (level % 2 == 0) { // even level: reversed
            long first = 1L << (level - 1);          // 2^(level-1)
            long last  = (1L << level) - 1;          // 2^level - 1
            return last - normal + first;
        } else { // odd level: same
            return normal;
        }
    }
}

