import com_github_leetcode.ListNode;
import java.util.HashMap;
import java.util.Map;

public class Solution {
    public ListNode removeZeroSumSublists(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;

        Map<Long, ListNode> sumToNode = new HashMap<>();
        long sum = 0;
        ListNode curr = dummy;
        while (curr != null) {
            sum += curr.val;
            sumToNode.put(sum, curr);
            curr = curr.next;
        }

        sum = 0;
        curr = dummy;
        while (curr != null) {
            sum += curr.val;
            ListNode next = sumToNode.get(sum).next;
            if (curr.next != next) {
                long tempSum = sum;
                ListNode temp = curr.next;
                while (temp != next) {
                    tempSum += temp.val;
                    sumToNode.remove(tempSum);
                    temp = temp.next;
                }
                curr.next = next;
            }
            curr = curr.next;
        }

        return dummy.next;
    }
}

