                long val = (long) s1 * a + (long) s2 * b + (long) s3 * i;
                if (val > max[k]) max[k] = val;
                if (val < min[k]) min[k] = val;
            }
        }

        long result = 0L;
        for (int k = 0; k < 8; k++) {
            long diff = max[k] - min[k];
            if (diff > result) result = diff;
        }
        return (int) result;
    }
}

