import java.util.HashMap;
import java.util.Map;

public class Solution {
    private final Map<String, Integer> memo = new HashMap<>();

    public int longestDecomposition(String text) {
        if (text == null || text.isEmpty()) {
            return 0;
        }
        return dfs(text);
    }

    private int dfs(String s) {
        if (s.isEmpty()) {
            return 0;
        }
        if (memo.containsKey(s)) {
            return memo.get(s);
        }

        int n = s.length();
        // Search for the longest prefix that equals a suffix
        for (int len = n / 2; len >= 1; len--) {
            if (s.substring(0, len).equals(s.substring(n - len))) {
                int middle = dfs(s.substring(len, n - len));
                int result = 2 + middle; // two matching chunks plus middle
                memo.put(s, result);
                return result;
            }
        }

        // No matching pair found; the whole string is one chunk
        memo.put(s, 1);
        return 1;
    }
}

