import java.util.*;

public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] result = new int[numPeople];
        if (candies == 0 || numPeople == 0) {
            return result;
        }

        long totalCandies = candies;
        long n = numPeople;

        // Find maximum m such that m*(m+1)/2 <= totalCandies
        long m = (long) ((Math.sqrt(1 + 8.0 * totalCandies) - 1) / 2);

        // Number of full rounds
        long k = m / n;

        // Base distribution after k full rounds
        for (int i = 0; i < numPeople; i++) {
            long personIndex = i + 1; // 1‑indexed
            long base = personIndex * k + n * k * (k - 1) / 2;
            result[i] = (int) base;
        }

        // Gifts in the partial round (first r people)
        long r = m % n;                     // number of gifts in the partial round
        for (int i = 1; i <= r; i++) {      // i is 1‑indexed
            long gift = n * k + i;          // amount of the i‑th gift in the partial round
            result[(int) (i - 1)] += (int) gift;
        }

        // Remaining candies after all full and partial gifts
        long used = m * (m + 1) / 2;
        long remaining = totalCandies - used;

        if (remaining > 0) {
            int startIndex = (int) (m % n); // 0‑based index of the last person
            result[startIndex] += (int) remaining;
        }

        return result;
    }
}

