public class Solution {
    public int[] maxDepthAfterSplit(String seq) {
        int n = seq.length();
        int[] answer = new int[n];
        int depth = 0;
        for (int i = 0; i < n; i++) {
            char c = seq.charAt(i);
            if (c == '(') {
                answer[i] = 1 - (depth % 2);
                depth++;
            } else { // ')'
                depth--;
                answer[i] = 1 - (depth % 2);
            }
        }
        return answer;
    }
}

