import java.util.*;

public class Solution {
    public String alphabetBoardPath(String target) {
        StringBuilder sb = new StringBuilder();
        int curRow = 0, curCol = 0;
        for (char ch : target.toCharArray()) {
            int targetRow = (ch - 'a') / 5;
            int targetCol = (ch - 'a') % 5;

            if (targetRow == 5) {
                // Destination is on the last row (only column 0 exists)
                // Move horizontally first to column 0
                while (curCol > targetCol) {
                    sb.append('L');
                    curCol--;
                }
                while (curCol < targetCol) {
                    sb.append('R');
                    curCol++;
                }
                // Then move vertically
                while (curRow > targetRow) {
                    sb.append('U');
                    curRow--;
                }
                while (curRow < targetRow) {
                    sb.append('D');
                    curRow++;
                }
            } else {
                // Destination is not on the last row
                // Move vertically first
                while (curRow > targetRow) {
                    sb.append('U');
                    curRow--;
                }
                while (curRow < targetRow) {
                    sb.append('D');
                    curRow++;
                }
                // Then move horizontally
                while (curCol > targetCol) {
                    sb.append('L');
                    curCol--;
                }
                while (curCol < targetCol) {
                    sb.append('R');
                    curCol++;
                }
            }
            sb.append('!');
        }
        return sb.toString();
    }
}

