public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        int[] deadlines = new int[n];
        for (int i = 0; i < n; i++) {
            if (dist[i] == 0) {
                deadlines[i] = -1; // cannot kill, monster already at city
            } else {
                // latest minute we can kill this monster
                deadlines[i] = (int) ((dist[i] - 1L) / speed[i]);
            }
        }
        Arrays.sort(deadlines);
        int kills = 0;
        for (int i = 0; i < n; i++) {
            if (deadlines[i] < i) {
                return kills;
            }
            kills++;
        }
        return kills; // all monsters can be eliminated
    }
}

