public class Solution {
    public long maxMatrixSum(int[][] matrix) {
        long sumAbs = 0;
        int countNeg = 0;
        long minAbs = Long.MAX_VALUE;

        for (int[] row : matrix) {
            for (int val : row) {
                long absVal = Math.abs((long) val);
                sumAbs += absVal;
                if (val < 0) {
                    countNeg++;
                }
                if (absVal < minAbs) {
                    minAbs = absVal;
                }
            }
        }

        if (countNeg % 2 == 0) {
            return sumAbs;
        } else {
            return sumAbs - 2 * minAbs;
        }
    }
}

