public class Solution {
    public int minSwaps(String s) {
        int balance = 0;   // number of unmatched '[' seen so far
        int swaps = 0;     // number of swaps performed

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') {
                balance++;
            } else { // c == ']'
                if (balance == 0) {
                    // Need to swap this ']' with a '[' that appears later
                    swaps++;
                    // After the swap, we effectively have one unmatched '['
                    balance = 1;
                } else {
                    balance--; // match this ']' with a previous '['
                }
            }
        }
        return swaps;
    }
}

