import java.util.Arrays;

public class Solution {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        int[] ans = new int[n];

        for (int i = 0; i < n; i++) {
            int x = obstacles[i];
            int l = 1, r = n;
            while (l <= r) {
                int mid = (l + r) >>> 1;
                if (dp[mid] > x) {
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            int pos = l;          // first index where dp[pos] > x
            dp[pos] = x;
            ans[i] = pos;
        }
        return ans;
    }
}

