public class Solution {
    public int[] findPeakGrid(int[][] mat) {
        int m = mat.length;
        int n = mat[0].length;
        int left = 0, right = n - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;
            // Find the row with the maximum element in column mid
            int maxRow = 0;
            for (int i = 1; i < m; i++) {
                if (mat[i][mid] > mat[maxRow][mid]) {
                    maxRow = i;
                }
            }

            int cur = mat[maxRow][mid];
            int leftVal = (mid - 1 >= 0) ? mat[maxRow][mid - 1] : -1;
            int rightVal = (mid + 1 < n) ? mat[maxRow][mid + 1] : -1;

            if (leftVal > cur) {
                right = mid - 1;
            } else if (rightVal > cur) {
                left = mid + 1;
            } else {
                return new int[]{maxRow, mid};
            }
        }

        // left == right, find the peak in this column
        int maxRow = 0;
        for (int i = 1; i < m; i++) {
            if (mat[i][left] > mat[maxRow][left]) {
                maxRow = i;
            }
        }
        return new int[]{maxRow, left};
    }
}

