import java.util.*;

public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layers = Math.min(m, n) / 2;

        for (int layer = 0; layer < layers; layer++) {
            int top = layer;
            int left = layer;
            int bottom = m - 1 - layer;
            int right = n - 1 - layer;

            // Extract elements of the current layer in counter‑clockwise order
            List<Integer> elems = new ArrayList<>();

            // 1. left column, top → bottom
            for (int row = top; row <= bottom; row++) {
                elems.add(grid[row][left]);
            }
            // 2. bottom row, left+1 → right
            for (int col = left + 1; col <= right; col++) {
                elems.add(grid[bottom][col]);
            }
            // 3. right column, bottom-1 → top
            for (int row = bottom - 1; row >= top; row--) {
                elems.add(grid[row][right]);
            }
            // 4. top row, right-1 → left+1
            for (int col = right - 1; col >= left + 1; col--) {
                elems.add(grid[top][col]);
            }

            int len = elems.size();
            int rot = k % len;
            if (rot != 0) {
                // Rotate left by rot positions
                List<Integer> rotated = new ArrayList<>(Collections.nCopies(len, 0));
                for (int i = 0; i < len; i++) {
                    rotated.set((i + rot) % len, elems.get(i));
                }
                elems = rotated;
            }

            // Write back rotated elements into the grid in the same order
            int idx = 0;
            // 1. left column, top → bottom
            for (int row = top; row <= bottom; row++) {
                grid[row][left] = elems.get(idx++);
            }
            // 2. bottom row, left+1 → right
            for (int col = left + 1; col <= right; col++) {
                grid[bottom][col] = elems.get(idx++);
            }
            // 3. right column, bottom-1 → top
            for (int row = bottom - 1; row >= top; row--) {
                grid[row][right] = elems.get(idx++);
            }
            // 4. top row, right-1 → left+1
            for (int col = right - 1; col >= left + 1; col--) {
                grid[top][col] = elems.get(idx++);
            }
        }

        return grid;
    }
}
